QT_ISI(26,{"4511":["(Ha Mim) hanya Allah sajalah yang mengetahui arti dan maksudnya.",[["حمٓ","Ha Mim"]]],"4512":["(Diturunkan Alkitab ini) yaitu Alquran; lafal ayat ini menjadi Mubtada (dari Allah) menjadi Khabar dari Mubtada (Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) di dalam perbuatan-Nya.",[["تَنزِيلُ","(The) wahyu"],["ٱلْكِتَـٰبِ","Kitab"],["مِنَ","(adalah) daripada"],["ٱللَّهِ","Allah"],["ٱلْعَزِيزِ","Yang Maha Perkasa"],["ٱلْحَكِيمِ","Yang Maha Bijaksana"]]],"4513":["(Kami tiada menciptakan langit dan bumi dan apa yang ada di antara keduanya melainkan) dengan tujuan (yang benar) guna menunjukkan kekuasaan dan keesaan Kami (dan dalam waktu yang ditentukan) bagi kemusnahannya, yaitu hingga hari kiamat. (Dan orang-orang yang kafir; terhadap apa yang diperingatkan kepada mereka) berupa dipertakuti dengan siksa (mereka berpaling)",[["مَا","Tidak"],["خَلَقْنَا","Kami mencipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["وَمَا","dan apa"],["بَيْنَهُمَآ","(adalah) antara keduanya"],["إِلَّا","kecuali"],["بِٱلْحَقِّ","dalam kebenaran"],["وَأَجَلٍۢ","dan (untuk) tempoh"],["مُّسَمًّۭى ۚ","dilantik"],["وَٱلَّذِينَ","Tetapi mereka yang"],["كَفَرُوا۟","kufur"],["عَمَّآ","daripada apa"],["أُنذِرُوا۟","mereka diberi amaran"],["مُعْرِضُونَ","(sedang) berpaling"]]],"4514":["(Katakanlah, \"Terangkanlah kepadaku) ceritakanlah oleh kalian kepadaku (tentang apa yang kalian seru) kalian sembah (selain Allah) yakni berhala-berhala; menjadi Maf'ul Awwal (perlihatkanlah kepadaku) ceritakanlah oleh kalian kepadaku (apakah yang telah mereka ciptakan) menjadi Maf'ul kedua (dari bumi ini) lafal ayat ini berkedudukan menjadi Maf'ul Tsani (atau adakah mereka berserikat) artinya, mempunyai andil (dalam) penciptaan (langit) bersama dengan Allah; lafal Am di sini bermakna Hamzah atau kata tanya yang menunjukkan makna ingkar. (Bawalah kepada-Ku Kitab yang sebelum ini) sebelum Alquran ini (atau peninggalan) yakni sisa-sisa (dari pengetahuan) yang ditemukan dari orang-orang terdahulu, yang hal tersebut membenarkan pengakuan kalian bahwa menyembah berhala itu dapat mendekatkan diri kalian kepada Allah? (jika kalian adalah orang-orang yang benar\") di dalam pengakuan kalian.",[["قُلْ","Katakanlah"],["أَرَءَيْتُم","Adakah kamu melihat"],["مَّا","apa"],["تَدْعُونَ","kamu panggil"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["أَرُونِى","Tunjukkan aku"],["مَاذَا","apa"],["خَلَقُوا۟","mereka telah mencipta"],["مِنَ","daripada"],["ٱلْأَرْضِ","bumi"],["أَمْ","atau"],["لَهُمْ","bagi mereka"],["شِرْكٌۭ","(adalah) sebarang bahagian"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ ۖ","langit"],["ٱئْتُونِى","Bawa aku"],["بِكِتَـٰبٍۢ","sebuah buku"],["مِّن","daripada"],["قَبْلِ","sebelum"],["هَـٰذَآ","ini"],["أَوْ","atau"],["أَثَـٰرَةٍۢ","jejak"],["مِّنْ","daripada"],["عِلْمٍ","pengetahuan"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"4515":["(Dan siapakah) Istifham atau kata tanya ini menunjukkan makna negatif, yakni tidak ada seorang pun (yang lebih sesat daripada orang yang menyeru) yang menyembah (selain Allah) (yang tidak dapat memperkenankan doanya sampai hari kiamat) yang dimaksud adalah berhala-berhala yang menjadi sesembahan mereka, sedikit pun dan untuk selamanya tidak akan dapat memperkenankan apa yang diminta oleh para penyembahnya (dan mereka terhadap seruan para penyembahnya) yakni penyembahan yang dilakukan oleh para penyembahnya (lalai) karena berhala-berhala itu adalah benda mati dan tidak berakal.",[["وَمَنْ","Dan siapa"],["أَضَلُّ","(adalah) lebih sesat"],["مِمَّن","daripada (dia) yang"],["يَدْعُوا۟","panggilan"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["مَن","yang"],["لَّا","tidak akan bertindak balas"],["يَسْتَجِيبُ","tidak akan bertindak balas"],["لَهُۥٓ","kepadanya"],["إِلَىٰ","sehingga"],["يَوْمِ","(the) Hari"],["ٱلْقِيَـٰمَةِ","(dari) Kebangkitan"],["وَهُمْ","dan mereka"],["عَن","daripada"],["دُعَآئِهِمْ","panggilan mereka"],["غَـٰفِلُونَ","(ada) tidak sedar"]]],"4516":["(Dan apabila manusia dikumpulkan pada hari kiamat niscaya sesembahan-sesembahan itu) berhala-berhala itu (terhadap mereka) yang menyembahnya (menjadi musuh mereka dan sesembahan-sesembahan itu terhadap penyembahan) para penyembahnya (ingkar) menyangkalnya.",[["وَإِذَا","Dan apabila"],["حُشِرَ","sedang berkumpul"],["ٱلنَّاسُ","manusia"],["كَانُوا۟","mereka akan menjadi"],["لَهُمْ","bagi mereka"],["أَعْدَآءًۭ","musuh"],["وَكَانُوا۟","dan mereka akan menjadi"],["بِعِبَادَتِهِمْ","ibadah mereka"],["كَـٰفِرِينَ","penafian"]]],"4517":["(Dan apabila dibacakan kepada mereka) kepada penduduk Mekah (ayat-ayat Kami) yakni Alquran (yang menjelaskan) atau yang jelas keadaannya (berkatalah orang-orang yang ingkar) di antara mereka (kepada kebenaran) kepada Alquran (ketika kebenaran itu datang kepada mereka, \"Ini adalah sihir yang nyata\") jelas sihirnya.",[["وَإِذَا","Dan apabila"],["تُتْلَىٰ","dibacakan"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتُنَا","Ayat Kami"],["بَيِّنَـٰتٍۢ","yang nyata"],["قَالَ","berkata"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لِلْحَقِّ","daripada kebenaran"],["لَمَّا","apabila"],["جَآءَهُمْ","ia datang kepada mereka"],["هَـٰذَا","Ini"],["سِحْرٌۭ","(adalah) sihir"],["مُّبِينٌ","yang nyata"]]],"4518":["(Bahkan) lafal Am di sini mempunyai makna sama dengan lafal Bal dan Hamzah yang menunjukkan makna ingkar (mereka mengatakan, \"Dia telah mengada-adakannya\") maksudnya, Alquran itu. (Katakanlah, \"Jika aku mengada-adakannya) umpamanya (maka kalian tiada mempunyai kuasa mempertahankan aku dari Allah) dari azab-Nya (barang sedikit pun) artinya, kalian tidak akan mampu menolak azab-Nya daripada diriku, jika Dia mengazab aku (Dia lebih mengetahui apa-apa yang kalian percakapkan tentangnya) tentang Alquran itu. (Cukuplah Dia) Yang Maha Tinggi (menjadi saksi antaraku dan antara kalian dan Dialah Yang Maha Pengampun) kepada orang yang bertobat (lagi Maha Penyayang\") kepada orang yang bertobat kepada-Nya; karena itu Dia tidak menyegerakan azab-Nya kepada mereka.",[["أَمْ","Atau"],["يَقُولُونَ","mereka berkata"],["ٱفْتَرَىٰهُ ۖ","Dia telah menciptanya"],["قُلْ","Katakanlah"],["إِنِ","Jika"],["ٱفْتَرَيْتُهُۥ","Aku telah menciptanya"],["فَلَا","maka tidak"],["تَمْلِكُونَ","kamu mempunyai kuasa"],["لِى","untuk aku"],["مِنَ","terhadap"],["ٱللَّهِ","Allah"],["شَيْـًٔا ۖ","sesuatu"],["هُوَ","Dia"],["أَعْلَمُ","lebih tahu"],["بِمَا","tentang apa"],["تُفِيضُونَ","kamu luahkan"],["فِيهِ ۖ","berkenaan dengannya"],["كَفَىٰ","Cukuplah Dia"],["بِهِۦ","Cukuplah Dia"],["شَهِيدًۢا","(sebagai) seorang Saksi"],["بَيْنِى","antara aku"],["وَبَيْنَكُمْ ۖ","dan antara kamu"],["وَهُوَ","dan Dia"],["ٱلْغَفُورُ","(ialah) Yang Maha Pengampun"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"4519":["(Katakanlah, \"Aku bukanlah rasul yang pertama) atau untuk, pertama kalinya (di antara rasul-rasul) maksudnya aku bukanlah rasul yang pertama, karena telah, banyak rasul yang diutus sebelumku, maka mengapa kalian mendustakan aku (dan aku tidak mengetahui apa yang akan diperbuat terhadapku dan tidak pula terhadap kalian) di dunia ini; apakah aku akan diusir dari negeriku, atau apakah aku akan dibunuh sebagaimana nasib yang telah dialami oleh nabi-nabi sebelumku, atau adakalanya kalian melempariku dengan batu, atau barangkali kalian akan tertimpa azab sebagaimana apa yang dialami oleh kaum yang mendustakan sebelum kalian. (Tiada lain) tidak lain (aku hanyalah mengikuti apa yang diwahyukan kepadaku) yaitu Alquran, dan aku sama sekali belum pernah membuat-buat dari diriku sendiri (dan aku tidak lain hanyalah seorang pemberi peringatan yang menjelaskan\") yang jelas peringatannya.",[["قُلْ","Katakanlah"],["مَا","Tidak"],["كُنتُ","aku"],["بِدْعًۭا","yang baru (satu)"],["مِّنَ","antara"],["ٱلرُّسُلِ","para Rasul"],["وَمَآ","dan bukan"],["أَدْرِى","aku tahu"],["مَا","apa"],["يُفْعَلُ","akan dilakukan"],["بِى","dengan aku"],["وَلَا","dan bukan"],["بِكُمْ ۖ","bersama kamu"],["إِنْ","Tidak"],["أَتَّبِعُ","aku ikut"],["إِلَّا","tetapi"],["مَا","apa"],["يُوحَىٰٓ","didedahkan"],["إِلَىَّ","kepada aku"],["وَمَآ","dan bukan"],["أَنَا۠","aku"],["إِلَّا","tetapi"],["نَذِيرٌۭ","seorang pemberi amaran"],["مُّبِينٌۭ","yang nyata"]]],"4520":["(Katakanlah, \"Terangkanlah kepadaku) ceritakanlah kepadaku, bagaimana pendapat kalian (jika ia) yakni jika Alquran itu (datang dari sisi Allah padahal kalian mengingkarinya) lafal Wakafartum Bihi merupakan jumlah Haliyah (dan seorang saksi dari Bani Israel mengakui kebenaran) yaitu Abdullah bin Salam (yang serupa dengan yang tersebut dalam Alquran) bahwasanya Alquran itu datang dari sisi Allah (lalu dia beriman) yakni saksi tersebut beriman kepada Alquran (sedangkan kalian menyombongkan diri) tidak mau beriman kepada Alquran. Sedangkan Jawab Syaratnya ialah 'Bukankah kalau demikian kalian adalah orang-orang yang lalim', hal ini disimpulkan dari pengertian ayat selanjutnya, ('Sesungguhnya Allah tiada memberi petunjuk kepada orang-orang yang lalim.\")",[["قُلْ","Katakanlah"],["أَرَءَيْتُمْ","Adakah kamu melihat"],["إِن","jika"],["كَانَ","ia adalah"],["مِنْ","daripada Allah"],["عِندِ","daripada Allah"],["ٱللَّهِ","daripada Allah"],["وَكَفَرْتُم","dan kamu tidak beriman"],["بِهِۦ","di dalamnya"],["وَشَهِدَ","dan bersaksi"],["شَاهِدٌۭ","seorang saksi"],["مِّنۢ","daripada"],["بَنِىٓ","(the) Bani Israel"],["إِسْرَٰٓءِيلَ","(the) Bani Israel"],["عَلَىٰ","kepada"],["مِثْلِهِۦ","(yang) seperti itu"],["فَـَٔامَنَ","lalu dia beriman"],["وَٱسْتَكْبَرْتُمْ ۖ","sedangkan kamu sombong"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["ٱلْقَوْمَ","manusia"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"4521":["(Dan orang-orang kafir berkata kepada orang-orang yang beriman) sehubungan dengan perihal orang-orang yang beriman, (\"Kalau sekiranya beriman) kepada Alquran itu (adalah suatu yang baik, tentulah mereka tiada mendahului kami beriman kepadanya. Dan karena mereka tidak mendapat petunjuk) yaitu orang-orang yang mengatakan demikian (dengannya) tidak mendapat petunjuk dari Alquran (maka mereka akan berkata, 'Ini) Alquran ini (adalah dusta) maksudnya, kebohongan (yang lama.'\")",[["وَقَالَ","Dan katakan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لِلَّذِينَ","daripada mereka yang"],["ءَامَنُوا۟","beriman"],["لَوْ","Jika"],["كَانَ","ia telah"],["خَيْرًۭا","kebaikan"],["مَّا","tidak"],["سَبَقُونَآ","mereka (akan) telah mendahului kami"],["إِلَيْهِ ۚ","kepadanya"],["وَإِذْ","Dan apabila"],["لَمْ","tidak"],["يَهْتَدُوا۟","mereka (ada) mendapat petunjuk"],["بِهِۦ","olehnya"],["فَسَيَقُولُونَ","mereka berkata"],["هَـٰذَآ","Ini"],["إِفْكٌۭ","(adalah) pembohongan"],["قَدِيمٌۭ","kuno"]]],"4522":["(Dan sebelumnya) sebelum Alquran (telah ada kitab Musa) kitab Taurat (sebagai petunjuk dan rahmat) bagi orang-orang yang beriman kepadanya; lafal Imaaman dan Rahmatan keduanya merupakan Hal. (Dan ini) yaitu Alquran (adalah Kitab yang membenarkan) kitab-kitab sebelumnya (dalam bahasa Arab) menjadi Hal dari Dhamir yang terkandung di dalam lafal Mushaddiquun (untuk memberi peringatan kepada orang-orang yang lalim) yakni orang-orang musyrik Mekah (dan) dia adalah (memberi kabar gembira kepada orang-orang yang berbuat baik) yakni orang-orang yang beriman.",[["وَمِن","Dan sebelum itu"],["قَبْلِهِۦ","Dan sebelum itu"],["كِتَـٰبُ","(ialah) Kitab Suci"],["مُوسَىٰٓ","(dari) Musa"],["إِمَامًۭا","(sebagai) panduan"],["وَرَحْمَةًۭ ۚ","dan rahmat"],["وَهَـٰذَا","Dan ini"],["كِتَـٰبٌۭ","(ialah) sebuah Kitab"],["مُّصَدِّقٌۭ","mengesahkan"],["لِّسَانًا","(dalam) bahasa"],["عَرَبِيًّۭا","bahasa arab"],["لِّيُنذِرَ","untuk memberi amaran"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","buat salah"],["وَبُشْرَىٰ","dan (sebagai) khabar gembira"],["لِلْمُحْسِنِينَ","bagi orang-orang yang berbuat baik"]]],"4523":["(Sesungguhnya orang-orang yang mengatakan, \"Rabb kami ialah Allah,\" kemudian mereka beristiqamah) atau menetapi ketaatan (maka tidak ada kekhawatiran terhadap mereka dan mereka tiada pula berduka cita.)",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["قَالُوا۟","berkata"],["رَبُّنَا","Wahai Tuhan kami"],["ٱللَّهُ","(ialah) Allah"],["ثُمَّ","kemudian"],["ٱسْتَقَـٰمُوا۟","tetap teguh"],["فَلَا","maka tidak"],["خَوْفٌ","bertakwa"],["عَلَيْهِمْ","ke atas mereka"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يَحْزَنُونَ","akan bersedih"]]],"4524":["(Mereka itulah penghuni-penghuni surga, mereka kekal di dalamnya) lafal Khaalidiina Fiihaa menjadi Hal atau kata keterangan keadaan (sebagai balasan) menjadi Mashdar yang dinashabkan oleh Fi'ilnya yang diperkirakan keberadaannya, yaitu lafal Yujzauna; artinya: mereka diberi pahala sebagai balasan (atas apa yang telah mereka kerjakan.)",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلْجَنَّةِ","(dari) Syurga"],["خَـٰلِدِينَ","kekal selama-lamanya"],["فِيهَا","di dalamnya"],["جَزَآءًۢ","ganjaran"],["بِمَا","bagi apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"4525":["(Kami perintahkan kepada manusia supaya berbuat baik kepada dua orang ibu bapaknya) menurut suatu qiraat lafal Ihsaan dibaca Husnan; maksudnya: Kami perintahkan manusia supaya berbuat baik kepada kedua orang tuanya. Lafal Ihsaanan adalah Mashdar yang dinashabkan oleh Fi'ilnya yang diperkirakan keberadaannya; demikian pula penjabarannya bila dibaca Husnan (ibunya mengandungnya dengan susah payah dan melahirkannya dengan susah pula) artinya penuh dengan susah payah. (Mengandungnya sampai menyapihnya) dari penyusuannya (adalah tiga puluh bulan) yakni dalam masa enam bulan sebagai batas yang paling minim bagi mengandung, sedangkan sisanya dua puluh empat bulan, yaitu lama masa penyusuan yang maksimal. Menurut suatu pendapat disebutkan bahwa jika sang ibu mengandungnya selama enam bulan atau sembilan bulan, maka sisanya adalah masa penyusuan (sehingga) menunjukkan makna Ghayah bagi jumlah yang diperkirakan keberadaannya, yakni dia hidup sehingga (apabila dia telah dewasa) yang dimaksud dengan pengertian dewasa ialah kekuatan fisik dan akal serta inteligensinya telah sempurna yaitu sekitar usia tiga puluh tiga tahun atau tiga puluh tahun (dan umurnya sampai empat puluh tahun) yakni genap mencapai empat puluh tahun, dalam usia ini seseorang telah mencapai batas maksimal kedewasaannya (ia berdoa, \"Ya Rabbku!) dan seterusnya. Ayat ini diturunkan berkenaan dengan Abu Bakar Ash-Shiddiq, yaitu sewaktu usianya mencapai empat puluh tahun sesudah dua tahun Nabi saw. diangkat menjadi rasul. Lalu ia beriman kepada Nabi saw. lalu beriman pula kedua orang tuanya, lalu menyusul anaknya yang bernama Abdurrahman, lalu cucunya yang bernama Atiq (Tunjukilah aku) maksudnya berilah ilham (untuk mensyukuri nikmat Engkau yang telah Engkau berikan) nikmat tersebut (kepadaku dan kepada ibu bapakku) yaitu nikmat tauhid (dan supaya aku dapat berbuat amal saleh yang Engkau ridai) maka Abu Bakar segera memerdekakan sembilan orang hamba sahaya yang beriman; mereka disiksa karena memeluk agama Allah (berilah kebaikan kepadaku dengan memberi kebaikan kepada cucuku) maka semua anak cucunya adalah orang-orang yang beriman. (Sesungguhnya aku bertobat kepada Engkau dan sesungguhnya aku termasuk orang-orang yang berserah diri.\")",[["وَوَصَّيْنَا","Dan telah Kami perintahkan"],["ٱلْإِنسَـٰنَ","(pada) lelaki"],["بِوَٰلِدَيْهِ","kepada ibu bapanya"],["إِحْسَـٰنًا ۖ","kebaikan"],["حَمَلَتْهُ","Membawanya"],["أُمُّهُۥ","ibunya"],["كُرْهًۭا","(dengan) kesusahan"],["وَوَضَعَتْهُ","dan melahirkannya"],["كُرْهًۭا ۖ","(dengan) kesusahan"],["وَحَمْلُهُۥ","Dan (kelahiran) dia"],["وَفِصَـٰلُهُۥ","dan menyapihnya"],["ثَلَـٰثُونَ","(adalah) tiga puluh"],["شَهْرًا ۚ","bulan"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["بَلَغَ","dia sampai"],["أَشُدَّهُۥ","kematangannya"],["وَبَلَغَ","dan mencapai"],["أَرْبَعِينَ","empat puluh"],["سَنَةًۭ","tahun"],["قَالَ","katanya"],["رَبِّ","Tuhanku"],["أَوْزِعْنِىٓ","berikanlah aku (kekuasaan)."],["أَنْ","bahawa"],["أَشْكُرَ","Aku mungkin bersyukur"],["نِعْمَتَكَ","(untuk) nikmat-Mu"],["ٱلَّتِىٓ","yang"],["أَنْعَمْتَ","telah Engkau anugerahkan"],["عَلَىَّ","atas aku"],["وَعَلَىٰ","dan seterusnya"],["وَٰلِدَىَّ","ibu bapa aku"],["وَأَنْ","dan bahawa"],["أَعْمَلَ","aku buat"],["صَـٰلِحًۭا","benar (perbuatan)"],["تَرْضَىٰهُ","yang berkenan kepada-Mu"],["وَأَصْلِحْ","dan menjadikan orang yang soleh"],["لِى","untuk aku"],["فِى","antara"],["ذُرِّيَّتِىٓ ۖ","keturunan aku"],["إِنِّى","sesungguhnya"],["تُبْتُ","aku berpaling"],["إِلَيْكَ","kepada-Mu"],["وَإِنِّى","dan sesungguhnya, aku"],["مِنَ","daripada"],["ٱلْمُسْلِمِينَ","mereka yang tunduk"]]],"4526":["(Mereka itulah) maksudnya yang mengatakan ucapan ini, yaitu Abu Bakar dan lain-lainnya (orang-orang yang Kami terima dari mereka amal baik) lafal Ahsana di sini bermakna Hasana (yang telah mereka kerjakan dan Kami ampuni kesalahan-kesalahan mereka, bersama penghuni-penghuni surga) lafal Fii Ash-haabil Jannah berkedudukan menjadi Hal atau kata keterangan keadaan maksudnya, mereka digolongkan ke dalam para penghuni surga (sebagai janji yang benar yang telah dijanjikan kepada mereka) yaitu sebagaimana yang telah diungkapkan dalam ayat yang lain, yakni firman-Nya, \"Allah menjanjikan kepada orang-orang yang mukmin lelaki dan perempuan, (akan mendapat) surga.\" (Q.S. At-Taubah, 72).",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلَّذِينَ","(adalah) mereka"],["نَتَقَبَّلُ","Kami akan terima"],["عَنْهُمْ","daripada mereka"],["أَحْسَنَ","(yang) terbaik"],["مَا","apa"],["عَمِلُوا۟","mereka lakukan"],["وَنَتَجَاوَزُ","dan Kami akan terlepas pandang"],["عَن","[dari]"],["سَيِّـَٔاتِهِمْ","perbuatan jahat mereka"],["فِىٓ","antara"],["أَصْحَـٰبِ","(para) sahabat"],["ٱلْجَنَّةِ ۖ","(dari) Syurga"],["وَعْدَ","Sebuah janji"],["ٱلصِّدْقِ","benar"],["ٱلَّذِى","yang"],["كَانُوا۟","mereka adalah"],["يُوعَدُونَ","dijanjikan"]]],"4527":["(Dan orang yang berkata kepada dua orang ibu bapaknya) menurut suatu qiraat dibaca Idgham dimaksud adalah jenisnya (\"Cis) dapat dibaca Uffin atau Uffan, merupakan Mashdar yang artinya, busuk dan buruk (bagi kamu keduanya) yakni aku marah kepada kamu berdua (apakah kamu keduanya memperingatkan kepadaku) menurut qiraat lain dibaca Ata'idannii, dengan diidgamkan (bahwa aku akan dibangkitkan) dari kubur (padahal sungguh telah berlalu beberapa umat) yakni generasi-generasi (sebelumku\") dan ternyata mereka tidak dikeluarkan dari kuburnya (lalu kedua ibu bapaknya itu memohon pertolongan kepada Allah) meminta pertolongan supaya anaknya sadar dan bertobat, seraya mengatakan, bahwa apabila kamu tidak mau bertobat, (\"Celakalah kamu) binasalah kamu (berimanlah) kepada adanya hari berbangkit. (Sesungguhnya janji Allah adalah benar.\" Lalu dia berkata: \"Ini tidak lain) maksudnya ucapan yang menyatakan adanya hari berbangkit ini (hanyalah dongengan orang-orang dahulu belaka\") artinya, kedustaan-kedustaan mereka.",[["وَٱلَّذِى","Tetapi orang yang"],["قَالَ","berkata"],["لِوَٰلِدَيْهِ","kepada ibu bapanya"],["أُفٍّۢ","Uff"],["لَّكُمَآ","kepada kamu berdua"],["أَتَعِدَانِنِىٓ","Adakah kamu berjanji kepada aku"],["أَنْ","bahawa"],["أُخْرَجَ","Aku akan dibawa keluar"],["وَقَدْ","dan telah pun meninggal dunia"],["خَلَتِ","dan telah pun meninggal dunia"],["ٱلْقُرُونُ","generasi"],["مِن","sebelum aku"],["قَبْلِى","sebelum aku"],["وَهُمَا","Dan mereka berdua"],["يَسْتَغِيثَانِ","minta bantuan"],["ٱللَّهَ","(milik) Allah"],["وَيْلَكَ","Celakalah kamu"],["ءَامِنْ","Percayalah"],["إِنَّ","Sesungguhnya"],["وَعْدَ","(the) Janji"],["ٱللَّهِ","(milik) Allah"],["حَقٌّۭ","(adalah) benar"],["فَيَقُولُ","Tetapi dia berkata"],["مَا","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّآ","tetapi"],["أَسَـٰطِيرُ","(the) cerita"],["ٱلْأَوَّلِينَ","(dari) orang-orang dahulu"]]],"4528":["(Mereka itulah orang-orang yang telah pasti) telah ditentukan (ketetapan atas mereka) yakni ketetapan azab (bersama umat-umat yang telah berlalu sebelum mereka dari jin dan manusia. Sesungguhnya mereka adalah orang-orang yang merugi.)",[["أُو۟لَـٰٓئِكَ","Itu"],["ٱلَّذِينَ","(adalah) mereka"],["حَقَّ","(telah) terbukti benar"],["عَلَيْهِمُ","terhadap mereka"],["ٱلْقَوْلُ","perkataan itu"],["فِىٓ","antara"],["أُمَمٍۢ","bangsa-bangsa"],["قَدْ","(yang) sudah meninggal dunia"],["خَلَتْ","(yang) sudah meninggal dunia"],["مِن","sebelum mereka"],["قَبْلِهِم","sebelum mereka"],["مِّنَ","daripada"],["ٱلْجِنِّ","(para) jin"],["وَٱلْإِنسِ ۖ","dan lelaki"],["إِنَّهُمْ","Sesungguhnya mereka"],["كَانُوا۟","adalah"],["خَـٰسِرِينَ","(golongan) yang rugi"]]],"4529":["(Dan bagi masing-masing mereka) bagi masing-masing dari orang mukmin dan orang kafir (derajat), derajat orang-orang yang beriman memperoleh kedudukan yang tinggi di dalam surga, sedangkan derajat orang-orang kafir memperoleh kedudukan di dasar neraka (menurut apa yang telah mereka kerjakan) berdasar pada amal ketaatan bagi orang-orang mukmin dan kemaksiatan bagi orang-orang kafir (dan agar Dia mencukupkan bagi mereka) yakni Allah mencukupkan bagi mereka; menurut suatu qiraat dibaca Walinuwaffiyahum (pekerjaan-pekerjaan mereka) maksudnya balasannya (sedangkan mereka tiada dirugikan) barang sedikit pun, misalkan untuk orang-orang mukmin dikurangi dan untuk orang-orang kafir ditambahi.",[["وَلِكُلٍّۢ","Dan untuk semua"],["دَرَجَـٰتٌۭ","(adalah) darjah"],["مِّمَّا","bagi apa"],["عَمِلُوا۟ ۖ","mereka lakukan"],["وَلِيُوَفِّيَهُمْ","dan supaya Dia memberi ganti kepada mereka sepenuhnya"],["أَعْمَـٰلَهُمْ","(untuk) perbuatan mereka"],["وَهُمْ","dan mereka"],["لَا","tidak akan dizalimi"],["يُظْلَمُونَ","tidak akan dizalimi"]]],"4530":["(Dan ingatlah hari ketika orang-orang kafir dihadapkan ke neraka) neraka diperlihatkan-Nya kepada mereka, kemudian dikatakan kepada mereka, (\"Kalian telah menghabiskan) dapat dibaca Adzhabtum, A-adzhabtum atau Adzhabtum (rezeki kalian yang baik) dengan cara menghambur-hamburkannya demi kelezatan kalian (dalam kehidupan dunia kalian saja dan kalian telah bersenang-senang) bersuka-ria (dengannya, maka pada hari ini kalian dibalasi dengan azab yang menghinakan) atau azab yang mengerikan (karena kalian telah menyombongkan diri yaitu bersikap takabur (di muka bumi tanpa hak dan karena kalian telah fasik\") atau berbuat kefasikan padanya, maka karena itu kalian diazab.",[["وَيَوْمَ","Dan (hari) itu"],["يُعْرَضُ","akan didedahkan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["عَلَى","kepada"],["ٱلنَّارِ","neraka"],["أَذْهَبْتُمْ","Kamu keletihan"],["طَيِّبَـٰتِكُمْ","perkara baik kamu"],["فِى","dalam"],["حَيَاتِكُمُ","hidup kamu"],["ٱلدُّنْيَا","dunia"],["وَٱسْتَمْتَعْتُم","dan kamu mengambil kesenangan kamu"],["بِهَا","di dalamnya"],["فَٱلْيَوْمَ","Jadi hari ini"],["تُجْزَوْنَ","kamu akan mendapat balasan"],["عَذَابَ","(dengan) hukuman"],["ٱلْهُونِ","memalukan"],["بِمَا","kerana"],["كُنتُمْ","kamu dahulu"],["تَسْتَكْبِرُونَ","sombong"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["بِغَيْرِ","tanpa"],["ٱلْحَقِّ","[yang] betul"],["وَبِمَا","dan kerana"],["كُنتُمْ","kamu dahulu"],["تَفْسُقُونَ","membangkang menderhaka"]]],"4531":["(Dan ingatlah saudara kaum Ad) yakni Nabi Hud a.s. (yaitu ketika) mulai lafal Idz dan seterusnya menjadi Badal Isytimal (dia memberi peringatan kepada kaumnya) maksudnya, mempertakuti mereka (di Al-Ahqaf) nama sebuah lembah tempat tinggal mereka yang terletak di negeri Yaman (dan sesungguhnya telah terdahulu beberapa orang pemberi peringatan) beberapa orang rasul (sebelumnya dan sesudahnya) sebelum Nabi Hud datang dan sesudahnya, kepada kaumnya masing-masing seraya mengatakan, (\"Janganlah kalian menyembah selain Allah) jumlah Waqad Khalat merupakan jumlah Mu'taridhah, atau kalimat sisipan (sesungguhnya aku khawatir kalian) jika kalian menyembah kepada selain Allah (akan ditimpa azab hari yang besar.\")",[["۞ وَٱذْكُرْ","Dan sebutkan"],["أَخَا","(yang) abang"],["عَادٍ","(daripada) Aad"],["إِذْ","apabila"],["أَنذَرَ","dia memberi amaran"],["قَوْمَهُۥ","umatnya"],["بِٱلْأَحْقَافِ","di Al-Ahqaf"],["وَقَدْ","dan telah pun meninggal dunia"],["خَلَتِ","dan telah pun meninggal dunia"],["ٱلنُّذُرُ","[para] pemberi amaran"],["مِنۢ","sebelum dia"],["بَيْنِ","sebelum dia"],["يَدَيْهِ","sebelum dia"],["وَمِنْ","dan selepas dia"],["خَلْفِهِۦٓ","dan selepas dia"],["أَلَّا","Itu tidak"],["تَعْبُدُوٓا۟","kamu menyembah"],["إِلَّا","kecuali"],["ٱللَّهَ","Allah"],["إِنِّىٓ","Sesungguhnya aku"],["أَخَافُ","[Aku] takut"],["عَلَيْكُمْ","bagi kamu"],["عَذَابَ","azab"],["يَوْمٍ","(dari) sehari"],["عَظِيمٍۢ","Hebat"]]],"4532":["(Mereka menjawab, \"Apakah kamu datang kepada kami untuk memalingkan kami dari menyembah tuhan-tuhan kami?) maksudnya kamu datang untuk memalingkan kami daripada menyembahnya. (Maka datangkanlah kepada kami azab yang telah kamu ancamkan kepada kami) bahwa jika kami menyembahnya pasti kami tertimpa azab (jika kamu termasuk orang-orang yang benar\") bahwasanya azab itu benar-benar menimpa kami.",[["قَالُوٓا۟","Mereka berkata"],["أَجِئْتَنَا","Adakah kamu datang kepada kami"],["لِتَأْفِكَنَا","untuk memalingkan kita"],["عَنْ","daripada"],["ءَالِهَتِنَا","tuhan kita"],["فَأْتِنَا","Kemudian bawa kami"],["بِمَا","apa"],["تَعِدُنَآ","kamu mengancam kami"],["إِن","jika"],["كُنتَ","kamu"],["مِنَ","daripada"],["ٱلصَّـٰدِقِينَ","yang benar"]]],"4533":["(Ia berkata) Nabi Hud berkata, (\"Sesungguhnya pengetahuan tentang itu hanya pada sisi Allah) artinya hanya Dialah yang mengetahui kapan azab itu menimpa kalian (dan aku hanya menyampaikan kepada kalian apa yang aku diutus dengan membawanya) untuk disampaikan kepada kalian (tetapi aku lihat kalian adalah kaum yang bodoh\") karena kalian meminta supaya azab didatangkan dengan segera.",[["قَالَ","Dia berkata"],["إِنَّمَا","Hanya"],["ٱلْعِلْمُ","pengetahuan itu"],["عِندَ","(ada) dengan Allah"],["ٱللَّهِ","(ada) dengan Allah"],["وَأُبَلِّغُكُم","dan aku sampaikan kepada kamu"],["مَّآ","apa"],["أُرْسِلْتُ","aku dihantar"],["بِهِۦ","dengannya"],["وَلَـٰكِنِّىٓ","tetapi"],["أَرَىٰكُمْ","aku nampak kamu"],["قَوْمًۭا","suatu kaum"],["تَجْهَلُونَ","jahil"]]],"4534":["(Maka tatkala mereka melihat azab itu) (berupa awan) atau mendung yang muncul di cakrawala langit (menuju ke lembah-lembah mereka, berkatalah mereka, \"Inilah awan yang akan menurunkan hujan kepada kami) maksudnya, awan yang membawa hujan buat kami, Allah swt. berfirman, ('Bahkan itulah azab yang kalian minta supaya datang dengan segera) maksudnya, azab itu yang kalian minta agar disegerakan datangnya (yaitu berupa angin) lafal Riihun menjadi Badal dari lafal Maa (yang mengandung azab yang pedih) yang menyakitkan.",[["فَلَمَّا","Kemudian apabila"],["رَأَوْهُ","mereka melihatnya"],["عَارِضًۭا","(sebagai) awan"],["مُّسْتَقْبِلَ","menghampiri"],["أَوْدِيَتِهِمْ","lembah mereka"],["قَالُوا۟","mereka berkata"],["هَـٰذَا","Ini"],["عَارِضٌۭ","(adalah) awan"],["مُّمْطِرُنَا ۚ","membawa kita hujan"],["بَلْ","Bahkan"],["هُوَ","ia"],["مَا","(ialah) apa"],["ٱسْتَعْجَلْتُم","kamu minta disegerakan"],["بِهِۦ ۖ","kamu minta disegerakan"],["رِيحٌۭ","angin"],["فِيهَا","di dalamnya"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۭ","yang pedih"]]],"4535":["(Yang menghancurkan) yang membinasakan (segala sesuatu) yang dilewatinya (dengan perintah Rabbnya) dengan seizin-Nya; maksudnya angin itu dapat membinasakan segala sesuatu yang dikehendaki-Nya untuk dibinasakan. Akhirnya binasalah kaum laki-laki dan wanita serta anak-anak mereka berikut dengan harta bendanya; semuanya terbawa terbang oleh angin yang besar itu antara langit dan bumi dalam keadaan tercabik-cabik. Kini yang tertinggal dalam keadaan selamat adalah Nabi Hud beserta orang-orang yang beriman kepadanya (maka jadilah mereka tidak ada yang kelihatan lagi kecuali bekas-bekas tempat tinggal mereka.' Demikianlah) sebagaimana Kami memberikan balasan kepada kaum Hud (Kami memberi balasan kepada kaum yang berdosa\") selain mereka.",[["تُدَمِّرُ","Memusnahkan"],["كُلَّ","setiap"],["شَىْءٍۭ","perkara"],["بِأَمْرِ","dengan (perintah)."],["رَبِّهَا","(dari) Tuhannya"],["فَأَصْبَحُوا۟","Kemudian mereka menjadi (demikian)"],["لَا","tidak"],["يُرَىٰٓ","dilihat"],["إِلَّا","kecuali"],["مَسَـٰكِنُهُمْ ۚ","kediaman mereka"],["كَذَٰلِكَ","Demikianlah"],["نَجْزِى","Kami membalas"],["ٱلْقَوْمَ","manusia"],["ٱلْمُجْرِمِينَ","[para] penjenayah"]]],"4536":["(Dan sesungguhnya Kami telah meneguhkan kedudukan mereka dalam hal-hal) (yang belum pernah) lafal In di sini dapat dikatakan sebagai In Nafiyah atau In Zaidah (Kami meneguhkan kedudukan kalian) hai penduduk Mekah (dalam hal itu) dalam hal kekuatan dan banyaknya harta benda (dan Kami telah memberikan kepada mereka pendengaran) lafal Sam'an bermakna Asmaa'an bermakna jamak (dan penglihatan serta hati) atau kalbu (tetapi pendengaran, penglihatan dan hati mereka itu tidak berguna sedikit jua pun bagi mereka) maksudnya, hal-hal tersebut sama sekali tidak dapat memberikan manfaat sedikit pun buat diri mereka; lafal Min di sini adalah Zaidah (karena) lafal Idz adalah yang dima'mulkan oleh lafal Aghnaa kemudian diberlakukan sebagai makna Ta'lil (mereka selalu mengingkari ayat-ayat Allah) yaitu hujah-hujah-Nya yang nyata (dan turunlah) yaitu menimpalah (kepada mereka apa yang dahulu selalu mereka memperolok-olokkannya) yaitu azab yang dahulu mereka suka memperolok-olokkannya.",[["وَلَقَدْ","Dan sungguh"],["مَكَّنَّـٰهُمْ","Kami telah menubuhkan mereka"],["فِيمَآ","pada apa"],["إِن","tidak"],["مَّكَّنَّـٰكُمْ","Kami telah menetapkan kamu"],["فِيهِ","di dalamnya"],["وَجَعَلْنَا","dan Kami jadikan"],["لَهُمْ","bagi mereka"],["سَمْعًۭا","pendengaran"],["وَأَبْصَـٰرًۭا","dan penglihatan"],["وَأَفْـِٔدَةًۭ","dan hati"],["فَمَآ","Tetapi tidak"],["أَغْنَىٰ","dimanfaatkan"],["عَنْهُمْ","mereka"],["سَمْعُهُمْ","pendengaran mereka"],["وَلَآ","dan bukan"],["أَبْصَـٰرُهُمْ","penglihatan mereka"],["وَلَآ","dan bukan"],["أَفْـِٔدَتُهُم","hati mereka"],["مِّن","sebarang"],["شَىْءٍ","perkara"],["إِذْ","apabila"],["كَانُوا۟","mereka adalah"],["يَجْحَدُونَ","menolak"],["بِـَٔايَـٰتِ","(the) Tanda-tanda"],["ٱللَّهِ","(milik) Allah"],["وَحَاقَ","dan diselubungi"],["بِهِم","mereka"],["مَّا","apa"],["كَانُوا۟","mereka dahulu"],["بِهِۦ","[padanya]"],["يَسْتَهْزِءُونَ","ejekan"]]],"4537":["(Dan sesungguhnya Kami telah membinasakan negeri-negeri di sekitar kalian) yakni penduduk-penduduknya, seperti kaum Tsamud, kaum Ad dan kaum Luth (dan Kami telah mendatangkan tanda-tanda kebesaran Kami berulang-ulang) maksudnya Kami telah mengulang-ulang hujah-hujah Kami yang nyata (supaya mereka kembali.)",[["وَلَقَدْ","Dan sungguh"],["أَهْلَكْنَا","Kami musnahkan"],["مَا","apa"],["حَوْلَكُم","mengelilingi kamu"],["مِّنَ","daripada"],["ٱلْقُرَىٰ","bandar-bandar"],["وَصَرَّفْنَا","dan Kami telah mempelbagaikan"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَرْجِعُونَ","kembali"]]],"4538":["(Maka mengapa tidak) atau kenapa tidak (menolong mereka) dengan cara menolak azab dari diri mereka (sesembahan-sesembahan selain Allah yang mereka jadikan) selain dari Allah (sebagai taqarrub) untuk mendekatkan diri mereka kepada Allah (dan sebagai tuhan-tuhan) di samping Allah, yaitu berupa berhala-berhala. Maf'ul pertama dari lafal Ittakhadza adalah Dhamir yang tidak disebutkan yang kembali kepada Isim Maushul, yaitu lafal Hum, sedangkan Maf'ul keduanya adalah lafal Qurbaanan, dan lafal Aalihatan sebagai Badal dari lafal Qurbaanan. (Bahkan tuhan-tuhan itu telah lenyap) yakni pergi (dari mereka) sewaktu azab itu datang menimpa mereka. (Itulah) yakni pengambilan mereka terhadap berhala-berhala sebagai tuhan-tuhan untuk mendekatkan diri kepada Allah (akibat kebohongan mereka) kedustaan mereka (dan apa yang dahulu mereka ada-adakan) yang dahulu mereka buat-buat. Maa adalah Mashdariyah atau Maushulah, sedangkan Dhamir yang kembali kepadanya tidak disebutkan yaitu lafal Fiihi; lengkapnya: Wa Maa Kaanuu Fiihi Yaftaruuna.",[["فَلَوْلَا","Kemudian mengapa (tidak) tidak"],["نَصَرَهُمُ","membantu mereka"],["ٱلَّذِينَ","mereka yang"],["ٱتَّخَذُوا۟","mereka telah mengambil"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["قُرْبَانًا","tuhan sebagai cara pendekatan"],["ءَالِهَةًۢ ۖ","tuhan sebagai cara pendekatan"],["بَلْ","Bahkan"],["ضَلُّوا۟","mereka sesat"],["عَنْهُمْ ۚ","daripada mereka"],["وَذَٰلِكَ","Dan bahawa"],["إِفْكُهُمْ","(adalah) kebatilan mereka"],["وَمَا","dan apa"],["كَانُوا۟","mereka adalah"],["يَفْتَرُونَ","mencipta"]]],"4539":["(Dan) ingatlah (ketika Kami hadapkan) Kami cenderungkan (kepadamu serombongan jin) yaitu jin Nashibin dari negeri Yaman atau Jin Nainawi, jumlah mereka ada tujuh atau sembilan jin. Nabi saw. ketika itu berada di lembah Nakhl sedang melakukan salat Subuh berjemaah dengan para sahabatnya. Demikianlah menurut hadis yang diriwayatkan oleh Bukhari dan Muslim (yang mendengarkan Alquran, maka tatkala mereka menghadiri pembacaannya, lalu mereka berkata) sebagian dari mereka berkata kepada sebagian yang lain, (\"Diamlah kalian\") untuk mendengarkan bacaannya. (Ketika pembacaan telah selesai) ketika nabi selesai membaca Alquran (mereka kembali) pulang kembali (kepada kaumnya untuk memberi peringatan) artinya, mereka kembali setelah mendengarkan Alquran kepada kaumnya sebagai pemberi peringatan akan datangnya azab jika mereka tidak beriman kepada Nabi. Mereka sebelum itu pemeluk agama Yahudi, lalu setelah mendengarkan bacaan Alquran mereka masuk Islam.",[["وَإِذْ","Dan apabila"],["صَرَفْنَآ","Kami mengarahkan"],["إِلَيْكَ","kepada kamu"],["نَفَرًۭا","sebuah parti"],["مِّنَ","daripada"],["ٱلْجِنِّ","jin"],["يَسْتَمِعُونَ","mendengar"],["ٱلْقُرْءَانَ","(kepada) al-Quran"],["فَلَمَّا","Dan apabila"],["حَضَرُوهُ","mereka menghadirinya"],["قَالُوٓا۟","mereka berkata"],["أَنصِتُوا۟ ۖ","Dengar dengan senyap"],["فَلَمَّا","Dan apabila"],["قُضِىَ","ia telah disimpulkan"],["وَلَّوْا۟","mereka berpatah balik"],["إِلَىٰ","kepada"],["قَوْمِهِم","rakyat mereka"],["مُّنذِرِينَ","(sebagai) pemberi amaran"]]],"4540":["(Mereka berkata, \"Hai kaum kami, sesungguhnya kami telah mendengarkan Kitab) yakni Alquran (yang telah diturunkan sesudah Musa yang membenarkan kitab-kitab sebelumnya) seperti kitab Taurat (lagi memimpin kepada kebenaran) kepada agama Islam (dan kepada jalan yang lurus) yaitu tuntunan agama Islam.",[["قَالُوا۟","Mereka berkata"],["يَـٰقَوْمَنَآ","Wahai kaum kami"],["إِنَّا","Sesungguhnya kami"],["سَمِعْنَا","[kami] telah mendengar"],["كِتَـٰبًا","sebuah Buku"],["أُنزِلَ","didedahkan"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["مُوسَىٰ","Musa"],["مُصَدِّقًۭا","mengesahkan"],["لِّمَا","apa"],["بَيْنَ","(ada) sebelum itu"],["يَدَيْهِ","(ada) sebelum itu"],["يَهْدِىٓ","membimbing"],["إِلَى","kepada"],["ٱلْحَقِّ","kebenaran"],["وَإِلَىٰ","dan kepada"],["طَرِيقٍۢ","a Laluan"],["مُّسْتَقِيمٍۢ","Lurus"]]],"4541":["(Hai kaum kami! Terimalah seruan orang yang menyeru kepada Allah) yakni seruan iman yang dilakukan oleh Nabi Muhammad saw. (dan berimanlah kepada-Nya, niscaya Dia akan mengampuni) Allah pasti akan mengampuni (dosa-dosa kalian) sebagian dari dosa-dosa kalian, diartikan demikian karena di antara dosa-dosa itu terdapat jenis dosa yang tidak dapat diampuni melainkan setelah mendapat kerelaan dari orang yang dianiaya oleh orang yang bersangkutan (dan melindungi kalian dari azab yang pedih) atau azab yang menyakitkan.",[["يَـٰقَوْمَنَآ","Wahai kaum kami"],["أَجِيبُوا۟","Balas"],["دَاعِىَ","(kepada) pemanggil"],["ٱللَّهِ","(milik) Allah"],["وَءَامِنُوا۟","dan beriman"],["بِهِۦ","dalam dirinya"],["يَغْفِرْ","Dia akan memaafkan"],["لَكُم","bagi kamu"],["مِّن","daripada"],["ذُنُوبِكُمْ","dosa kamu"],["وَيُجِرْكُم","dan akan melindungi kamu"],["مِّنْ","daripada"],["عَذَابٍ","azab"],["أَلِيمٍۢ","yang pedih"]]],"4542":["(Dan orang yang tidak menerima seruan orang yang menyeru kepada Allah maka dia tidak akan dapat melepaskan diri dari azab Allah di muka bumi) artinya ia tidak akan dapat melemahkan Allah dengan cara lari dari-Nya sehingga ia selamat dari azab-Nya (dan tidak ada baginya) yakni bagi orang yang tidak menerima seruan itu (selain Allah) (pelindung-pelindung) yang dapat menolak azab Allah daripada dirinya. (dalam kesesatan yang nyata\") jelas sesatnya.",[["وَمَن","Dan sesiapa"],["لَّا","tidak"],["يُجِبْ","bertindak balas"],["دَاعِىَ","(kepada) pemanggil"],["ٱللَّهِ","(milik) Allah"],["فَلَيْسَ","maka tidak"],["بِمُعْجِزٍۢ","dia boleh melarikan diri"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَلَيْسَ","dan bukan"],["لَهُۥ","baginya"],["مِن","selain Dia"],["دُونِهِۦٓ","selain Dia"],["أَوْلِيَآءُ ۚ","pelindung"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["فِى","(ada) dalam"],["ضَلَـٰلٍۢ","ralat"],["مُّبِينٍ","yang nyata"]]],"4543":["(Dan apakah mereka tidak memperhatikan) atau apakah orang-orang yang ingkar kepada hari berbangkit itu tidak mengetahui (bahwa sesungguhnya Allah yang menciptakan langit dan bumi dan Dia tidak merasa payah karena menciptakannya) artinya, Dia mampu menciptakan kesemuanya dengan mudah (kuasa) lafal Biqaadirin menjadi Khabar dari Anna, kemudian ditambahkan huruf Ba, karena pengertian ayat ini sejajar kekuatannya dengan kalimat Alaisallaahu Biqaadirin, artinya; Bukankah Allah kuasa (menghidupkan orang-orang mati? Ya) Dia Maha Kuasa untuk menghidupkan orang-orang mati (sesungguhnya Dia Maha Kuasa atas segala sesuatu.)",[["أَوَلَمْ","Jangan"],["يَرَوْا۟","mereka lihat"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["ٱلَّذِى","(ialah) Yang"],["خَلَقَ","dicipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["وَلَمْ","dan (adalah) tidak"],["يَعْىَ","penat"],["بِخَلْقِهِنَّ","oleh ciptaan mereka"],["بِقَـٰدِرٍ","(ada) mampu"],["عَلَىٰٓ","untuk memberi kehidupan"],["أَن","untuk memberi kehidupan"],["يُحْـِۧىَ","untuk memberi kehidupan"],["ٱلْمَوْتَىٰ ۚ","(kepada) orang mati"],["بَلَىٰٓ","ya"],["إِنَّهُۥ","sesungguhnya Dia"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","Maha Berkuasa"]]],"4544":["(Dan ingatlah hari ketika orang-orang kafir dihadapkan kepada neraka) ketika mereka diazab di dalamnya, lalu dikatakan kepada mereka, (\"Bukankah ini) yakni azab ini (benar?\" Mereka menjawab, \"Ya benar demi Rabb kami.\" Allah berfirman, \"Maka rasakanlah azab ini disebabkan kalian selalu ingkar.\")",[["وَيَوْمَ","Dan (hari) itu"],["يُعْرَضُ","terdedah"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["عَلَى","kepada"],["ٱلنَّارِ","neraka"],["أَلَيْسَ","bukan"],["هَـٰذَا","ini"],["بِٱلْحَقِّ ۖ","kebenaran"],["قَالُوا۟","Mereka akan berkata"],["بَلَىٰ","ya"],["وَرَبِّنَا ۚ","oleh Tuhan kita"],["قَالَ","Dia akan berkata"],["فَذُوقُوا۟","Kemudian rasa"],["ٱلْعَذَابَ","azab"],["بِمَا","kerana"],["كُنتُمْ","kamu pernah"],["تَكْفُرُونَ","kufur"]]],"4545":["(Maka bersabarlah kamu) di dalam menghadapi perlakuan kaummu yang menyakitkan itu (sebagaimana orang-orang yang mempunyai keteguhan hati) yaitu orang-orang yang teguh dan sabar di dalam menghadapi cobaan dan tantangan (dari rasul-rasul) sebelummu, karena itu kamu akan termasuk orang yang mempunyai keteguhan hati. Lafal Min di sini menunjukkan makna Bayan, sehingga pengertiannya menunjukkan, bahwa semua rasul-rasul itu mempunyai keteguhan hati. Tetapi menurut pendapat yang lain itu menunjukkan makna Lit Tab'idh, karena Nabi Adam bukanlah termasuk di antara mereka yang memiliki keteguhan hati, sebagaimana yang diungkapkan oleh ayat lain yaitu firman-Nya: \".. dan tidak Kami dapati padanya kemauan yang kuat.\" (Q.S. Thaha, 115) demikian pula Nabi Yunus tidak termasuk di antara mereka yang Ulil 'Azmi, sebagaimana yang diungkapkan oleh firman-Nya, \".. dan janganlah kamu seperti orang yang berada dalam (perut) ikan (Yunus).\" (Q.S. Al-Qalam, 48) (dan janganlah kamu meminta disegerakan azab bagi mereka) bagi kaummu yaitu disegerakan turunnya azab bagi mereka. Menurut pendapat lain, bahwa hal ini timbul sebagai reaksi dari sikap mereka terhadapnya, maka Nabi suka jika azab diturunkan kepada mereka, tetapi selanjutnya Nabi diperintahkan supaya bersabar dan jangan meminta supaya disegerakan azab bagi mereka. Karena sesungguhnya azab itu pasti akan menimpa mereka. (Pada hari mereka melihat apa yang diancamkan kepada mereka, mereka merasa seolah-olah) yang dimaksud adalah azab di akhirat mengingat lamanya masa di akhirat mereka merasa seolah-olah (tidak tinggal) di dunia menurut dugaan mereka (melainkan sesaat pada siang hari) Alquran ini adalah (suatu peringatan) peringatan dari Allah buat kalian (maka tidaklah) tiadalah (dibinasakan) sewaktu azab sudah di ambang pintu (melainkan orang-orang yang fasik) yaitu orang-orang yang kafir.",[["فَٱصْبِرْ","Jadi bersabarlah"],["كَمَا","seperti"],["صَبَرَ","mempunyai kesabaran"],["أُو۟لُوا۟","mereka yang berazam"],["ٱلْعَزْمِ","mereka yang berazam"],["مِنَ","daripada"],["ٱلرُّسُلِ","para Rasul"],["وَلَا","dan jangan"],["تَسْتَعْجِل","berusaha untuk menyegerakan"],["لَّهُمْ ۚ","bagi mereka"],["كَأَنَّهُمْ","Seolah-olah mereka telah"],["يَوْمَ","(the) Hari"],["يَرَوْنَ","mereka lihat"],["مَا","apa"],["يُوعَدُونَ","mereka telah dijanjikan"],["لَمْ","tidak"],["يَلْبَثُوٓا۟","kekal"],["إِلَّا","kecuali"],["سَاعَةًۭ","sejam"],["مِّن","daripada"],["نَّهَارٍۭ ۚ","sehari"],["بَلَـٰغٌۭ ۚ","Satu pemberitahuan"],["فَهَلْ","Tetapi akan"],["يُهْلَكُ","(mana-mana) dimusnahkan"],["إِلَّا","kecuali"],["ٱلْقَوْمُ","rakyat"],["ٱلْفَـٰسِقُونَ","yang durhaka"]]],"4546":["(Orang-orang yang kafir) dari kalangan penduduk Mekah (dan menghalang-halangi) orang-orang lainnya (dari jalan Allah) dari jalan keimanan (Allah melebur) menghapus (amal-amal mereka) seperti memberi makan dan menghubungkan silaturahim; mereka tidak akan melihat pahala amalnya di akhirat nanti dan mereka hanya mendapat balasan di dunia saja dari kemurahan-Nya.",[["ٱلَّذِينَ","Orang yang"],["كَفَرُوا۟","kufur"],["وَصَدُّوا۟","dan berpaling"],["عَن","daripada"],["سَبِيلِ","(jalan) Allah"],["ٱللَّهِ","(jalan) Allah"],["أَضَلَّ","Dia akan menyebabkan hilang"],["أَعْمَـٰلَهُمْ","perbuatan mereka"]]],"4547":["(Dan orang-orang yang beriman) yaitu para sahabat Anshar dan lainnya (dan mengerjakan amal-amal yang saleh serta beriman pula kepada apa yang diturunkan kepada Muhammad) yakni Alquran (dan itulah yang hak dari Rabb mereka, Allah menghapuskan daripada mereka) artinya, Dia mengampuni (kesalahan-kesalahan mereka dan memperbaiki keadaan mereka) karena itu mereka tidak lagi mendurhakai-Nya.",[["وَٱلَّذِينَ","Dan orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["وَءَامَنُوا۟","dan beriman"],["بِمَا","pada apa"],["نُزِّلَ","didedahkan"],["عَلَىٰ","kepada"],["مُحَمَّدٍۢ","Muhammad"],["وَهُوَ","dan ia"],["ٱلْحَقُّ","(adalah) kebenaran"],["مِن","daripada"],["رَّبِّهِمْ ۙ","Tuhan mereka"],["كَفَّرَ","Dia akan keluarkan"],["عَنْهُمْ","daripada mereka"],["سَيِّـَٔاتِهِمْ","kemungkaran mereka"],["وَأَصْلَحَ","dan menambah baik"],["بَالَهُمْ","keadaan mereka"]]],"4548":["(Yang demikian) maksudnya penghapusan amal dan pengampunan kesalahan-kesalahan itu (adalah karena) disebabkan (orang-orang kafir mengikuti yang batil) yakni ajakan setan (dan sesungguhnya orang-orang yang beriman mengikuti yang hak) yakni Alquran (dari Rabb mereka. Demikianlah) sebagaimana penjelasan tersebut (Allah membuat untuk manusia perbandingan-perbandingan bagi mereka) untuk menjelaskan keadaan mereka, yaitu orang kafir amalnya akan dihapus, sedangkan orang mukmin kesalahan-kesalahannya akan diampuni.",[["ذَٰلِكَ","Itu"],["بِأَنَّ","(adalah) kerana"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["ٱتَّبَعُوا۟","ikut"],["ٱلْبَـٰطِلَ","kepalsuan"],["وَأَنَّ","dan bahawa"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["ٱتَّبَعُوا۟","ikut"],["ٱلْحَقَّ","(kebenaran)."],["مِن","daripada"],["رَّبِّهِمْ ۚ","Tuhan mereka"],["كَذَٰلِكَ","Demikianlah"],["يَضْرِبُ","Allah hadirkan"],["ٱللَّهُ","Allah hadirkan"],["لِلنَّاسِ","kepada rakyat"],["أَمْثَـٰلَهُمْ","persamaan mereka"]]],"4549":["(Apabila kalian bertemu dengan orang-orang kafir di medan perang maka pancunglah batang leher mereka) lafal Dharbur Riqaab adalah bentuk Mashdar yang menggantikan kedudukan Fi'ilnya, karena asalnya adalah, Fadhribuu Riqaabahum artinya, maka pancunglah batang leher mereka. Maksudnya, bunuhlah mereka. Di sini diungkapkan dengan kalimat Dharbur Riqaab yang artinya memancung leher, karena pukulan yang mematikan itu kebanyakan dilakukan dengan cara memukul atau memancung batang leher. (Sehingga apabila kalian telah mengalahkan mereka) artinya kalian telah banyak membunuh mereka (maka kencangkanlah) tangkaplah dan tawanlah mereka lalu ikatlah mereka (ikatan mereka) dengan tali pengikat tawanan perang (dan sesudah itu kalian boleh membebaskan mereka) lafal Mannan adalah bentuk Mashdar yang menggantikan kedudukan Fi'ilnya; maksudnya, kalian memberikan anugerah kepada mereka, yaitu dengan cara melepaskan mereka tanpa imbalan apa-apa (atau menerima tebusan) artinya, kalian meminta tebusan berupa harta atau tukaran dengan kaum muslimin yang ditawan oleh mereka (sampai perang meletakkan) maksudnya, orang-orang yang terlibat di dalam peperangan itu meletakkan (senjatanya) artinya, menghentikan adu senjata dan adu lain-lainnya, misalnya orang-orang kafir menyerah kalah atau mereka menandatangani perjanjian gencatan senjata; hal inilah akhir dari suatu peperangan dan saling tawan-menawan. (Demikianlah) menjadi Khabar dari Mubtada yang diperkirakan keberadaannya, yaitu perkara tentang menghadapi orang-orang kafir adalah sebagaimana yang telah disebutkan tadi (apabila Allah menghendaki niscaya Allah dapat menang atas mereka) tanpa melalui peperangan lagi (tetapi) Dia memerintahkan kalian supaya berperang (untuk menguji sebagian kalian dengan sebagian yang lain) di antara mereka dalam peperangan itu, sebagian orang yang gugur di antara kalian ada yang dimasukkan ke dalam surga, dan sebagian lagi dimasukkan ke dalam neraka. (Dan orang-orang yang gugur) menurut suatu qiraat dibaca Qaataluu dan seterusnya, ayat ini diturunkan pada waktu perang Uhud, karena banyak di antara pasukan kaum muslimin yang gugur dan mengalami luka-luka (di jalan Allah, Allah tidak akan menyia-nyiakan) maksudnya, tidak akan menghapuskan (amal mereka.)",[["فَإِذَا","Maka apabila"],["لَقِيتُمُ","kamu jumpa"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["فَضَرْبَ","kemudian mogok"],["ٱلرِّقَابِ","leher"],["حَتَّىٰٓ","sehingga"],["إِذَآ","apabila"],["أَثْخَنتُمُوهُمْ","kamu telah menundukkan mereka"],["فَشُدُّوا۟","kemudian ikat dengan kuat"],["ٱلْوَثَاقَ","ikatan itu"],["فَإِمَّا","kemudian sama ada"],["مَنًّۢا","suatu nikmat"],["بَعْدُ","selepas itu"],["وَإِمَّا","atau"],["فِدَآءً","wang tebusan"],["حَتَّىٰ","sehingga"],["تَضَعَ","berbaring"],["ٱلْحَرْبُ","peperangan itu"],["أَوْزَارَهَا ۚ","bebannya"],["ذَٰلِكَ","Itu"],["وَلَوْ","Dan jika"],["يَشَآءُ","Allah telah menghendaki"],["ٱللَّهُ","Allah telah menghendaki"],["لَٱنتَصَرَ","nescaya Dia mengambil pembalasan"],["مِنْهُمْ","daripada mereka"],["وَلَـٰكِن","tetapi"],["لِّيَبْلُوَا۟","untuk menguji"],["بَعْضَكُم","sebahagian daripada kamu"],["بِبَعْضٍۢ ۗ","dengan orang lain"],["وَٱلَّذِينَ","Dan orang yang"],["قُتِلُوا۟","dibunuh"],["فِى","dalam"],["سَبِيلِ","(jalan) Allah"],["ٱللَّهِ","(jalan) Allah"],["فَلَن","maka tidak pernah"],["يُضِلَّ","Dia akan menyebabkan hilang"],["أَعْمَـٰلَهُمْ","perbuatan mereka"]]],"4550":["(Allah akan memberi petunjuk kepada mereka) di dunia dan di akhirat kepada yang bermanfaat buat diri mereka (dan memperbaiki keadaan mereka) di dunia dan di akhirat. Perbaikan di dunia adalah bagi mereka yang tidak gugur, yang termasuk ke dalam pengertian ungkapan Qutiluu dengan cara Taghlib, artinya lebih memprioritaskan mereka yang gugur di jalan Allah swt.",[["سَيَهْدِيهِمْ","Dia akan membimbing mereka"],["وَيُصْلِحُ","dan menambah baik"],["بَالَهُمْ","keadaan mereka"]]],"4551":["(Dan memasukkan mereka ke dalam surga yang telah diperkenalkan) telah dijelaskan (kepada mereka) sehingga mereka mengetahui tempat-tempat tinggal mereka dalam surga itu dan mereka telah mengenal istri-istri mereka dan telah mengenal pelayan-pelayan yang akan melayani mereka tanpa membutuhkan petunjuk lagi.",[["وَيُدْخِلُهُمُ","Dan akui mereka"],["ٱلْجَنَّةَ","(ke) Syurga"],["عَرَّفَهَا","Dia telah memaklumkannya"],["لَهُمْ","kepada mereka"]]],"4552":["(Hai orang-orang yang beriman! Jika kalian menolong Allah) yakni agama-Nya dan Rasul-Nya (niscaya Dia menolong kalian) atas musuh-musuh kalian (dan meneguhkan telapak kaki kalian) di dalam medan perang.",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوٓا۟","Wahai orang yang beriman"],["إِن","Jika"],["تَنصُرُوا۟","kamu tolong"],["ٱللَّهَ","Allah"],["يَنصُرْكُمْ","Dia akan membantu kamu"],["وَيُثَبِّتْ","dan teguhkan"],["أَقْدَامَكُمْ","kaki kamu"]]],"4553":["(Dan orang-orang yang kafir) dari kalangan penduduk Mekah; lafal ayat ini berkedudukan menjadi Mubtada, sedangkan Khabarnya, niscaya mereka celaka. Pengertian ini disimpulkan dari firman selanjutnya yaitu (maka kecelakaanlah bagi mereka) yakni kebinasaan dan kekecewaanlah yang akan mereka terima dari Allah (dan Allah menyesatkan amal perbuatan mereka) lafal ayat ini diathafkan pada Ta'isuu yang keberadaannya diperkirakan.",[["وَٱلَّذِينَ","Tetapi mereka yang"],["كَفَرُوا۟","kufur"],["فَتَعْسًۭا","kemusnahan (adalah)"],["لَّهُمْ","bagi mereka"],["وَأَضَلَّ","dan Dia akan menyebabkan hilang"],["أَعْمَـٰلَهُمْ","perbuatan mereka"]]],"4554":["(Yang demikian itu) kecelakaan dan penyesatan itu (adalah karena sesungguhnya mereka benci kepada apa yang diturunkan Allah) yakni Alquran yang diturunkan-Nya, di dalamnya terkandung masalah-masalah taklif atau kewajiban-kewajiban (lalu Allah menghapuskan pahala amal-amal mereka.)",[["ذَٰلِكَ","Itu"],["بِأَنَّهُمْ","(adalah) kerana mereka"],["كَرِهُوا۟","benci"],["مَآ","apa"],["أَنزَلَ","Allah telah menurunkan"],["ٱللَّهُ","Allah telah menurunkan"],["فَأَحْبَطَ","maka Dia telah menjadikan sia-sia"],["أَعْمَـٰلَهُمْ","perbuatan mereka"]]],"4555":["(Maka apakah mereka tidak mengadakan perjalanan di bumi sehingga mereka dapat memperhatikan bagaimana kesudahan orang-orang yang sebelum mereka; Allah telah menimpakan kebinasaan atas mereka) atas diri mereka, dan anak-anak serta harta benda mereka (dan orang-orang kafir akan menerima hal yang seperti itu) yaitu mereka akan menerima akibat-akibat yang sama dengan apa yang telah diterima oleh orang-orang kafir sebelum mereka.",[["۞ أَفَلَمْ","Jangan"],["يَسِيرُوا۟","mereka mengembara"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَيَنظُرُوا۟","dan lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلَّذِينَ","orang"],["مِن","sebelum mereka"],["قَبْلِهِمْ ۚ","sebelum mereka"],["دَمَّرَ","Allah hancurkan"],["ٱللَّهُ","Allah hancurkan"],["عَلَيْهِمْ ۖ","[atas] mereka"],["وَلِلْكَـٰفِرِينَ","dan bagi orang-orang kafir"],["أَمْثَـٰلُهَا","rupanya"]]],"4556":["(Yang demikian itu) dimenangkannya orang-orang mukmin dan dikalahkannya orang-orang kafir (karena sesungguhnya Allah adalah pelindung) pelindung dan penolong (orang-orang yang beriman dan karena sesungguhnya orang-orang kafir itu tiada mempunyai pelindung.)",[["ذَٰلِكَ","Itu"],["بِأَنَّ","(adalah) kerana"],["ٱللَّهَ","Allah"],["مَوْلَى","(ialah) Pelindung"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَأَنَّ","dan bahawa"],["ٱلْكَـٰفِرِينَ","orang-orang kafir"],["لَا","(ada) tidak"],["مَوْلَىٰ","pelindung"],["لَهُمْ","bagi mereka"]]],"4557":["(Sesungguhnya Allah memasukkan orang-orang yang beriman dan mengerjakan amal saleh ke dalam surga yang mengalir di bawahnya sungai-sungai. Dan orang-orang yang kafir itu bersenang-senang) di dunia (dan mereka makan seperti makannya binatang-binatang) tiada lagi yang menjadi kepentingan mereka selain dari perut dan nafsu syahwatnya dan mereka sama sekali tidak menoleh sedikit pun kepada masalah akhirat. (Dan neraka adalah tempat tinggal mereka) atau, tempat menetap dan tempat kembali mereka untuk selama-lamanya.",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يُدْخِلُ","akan mengaku"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["جَنَّـٰتٍۢ","(ke) Taman"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ ۖ","sungai-sungai"],["وَٱلَّذِينَ","tetapi mereka yang"],["كَفَرُوا۟","kufur"],["يَتَمَتَّعُونَ","mereka menikmati"],["وَيَأْكُلُونَ","dan makan"],["كَمَا","seperti"],["تَأْكُلُ","makan"],["ٱلْأَنْعَـٰمُ","lembu itu"],["وَٱلنَّارُ","dan Api"],["مَثْوًۭى","(akan menjadi) tempat tinggal"],["لَّهُمْ","bagi mereka"]]],"4558":["(Dan berapa banyaknya) sudah berapa banyak (negeri-negeri) yakni penduduknya (yang lebih kuat dari penduduk negerimu) lebih kuat daripada penduduk negeri Mekah (yang telah mengusirmu itu) Dhamir di sini lebih memperhatikan lafal Qaryah (Kami telah membinasakan mereka) di sini lebih diperhatikan makna yang terkandung pada lafal Qaryah yang pertama (maka tidak ada seorang penolong pun bagi mereka) dari kebinasaan yang Kami lakukan.",[["وَكَأَيِّن","Dan berapa banyak"],["مِّن","daripada"],["قَرْيَةٍ","sebuah bandar"],["هِىَ","yang"],["أَشَدُّ","(adalah) lebih kuat"],["قُوَّةًۭ","(dalam) kekuatan"],["مِّن","daripada"],["قَرْيَتِكَ","bandar kamu"],["ٱلَّتِىٓ","yang"],["أَخْرَجَتْكَ","telah menghalau kamu keluar"],["أَهْلَكْنَـٰهُمْ","Kami memusnahkan mereka"],["فَلَا","jadi tidak"],["نَاصِرَ","penolong"],["لَهُمْ","bagi mereka"]]],"4559":["(Maka apakah orang yang berpegang pada keterangan) yakni hujah dan argumentasi (yang datang dari Rabbnya) mereka adalah orang-orang mukmin (sama dengan orang yang dihiasi oleh keburukan amal perbuatannya) karena itu lalu ia memandangnya sebagai perbuatan yang baik, mereka adalah orang-orang kafir Mekah (dan mengikuti hawa nafsunya?) dalam menyembah berhala-berhala, maksudnya tentu saja tidak ada persamaan di antara keduanya.",[["أَفَمَن","Maka adakah (dia) yang"],["كَانَ","ialah"],["عَلَىٰ","pada"],["بَيِّنَةٍۢ","bukti yang jelas"],["مِّن","daripada"],["رَّبِّهِۦ","Tuhannya"],["كَمَن","seperti (dia) siapa"],["زُيِّنَ","dijadikan menarik"],["لَهُۥ","kepadanya"],["سُوٓءُ","(yang) jahat"],["عَمَلِهِۦ","(dari) perbuatannya"],["وَٱتَّبَعُوٓا۟","semasa mereka mengikut"],["أَهْوَآءَهُم","keinginan mereka"]]],"4560":["(Perumpamaan) gambaran tentang (surga yang dijanjikan kepada orang-orang yang bertakwa) dan yang menjadi milik bersama bagi orang-orang yang memasukinya. Lafal ayat ini menjadi Mubtada, sedangkan Khabarnya ialah (yang di dalamnya ada sungai-sungai dari air yang tiada berubah rasa dan baunya) dapat dibaca Aasinin atau Asinin, jika dibaca Aasinin wazannya sama dengan lafal Dhaaribin, jika dibaca Asinin Wazannya sama dengan lafal Hadzirun. Artinya, airnya tidak berubah atau tidak berbeda dengan air dunia yang dapat berubah karena ada sesuatu yang mencampurinya (sungai-sungai dari air susu yang tiada berubah rasanya) berbeda dengan air susu di dunia, karena air susu di dunia keluar dari susu (sungai-sungai dari khamar yang lezat rasanya) sangat lezat rasanya (bagi peminumnya) berbeda halnya dengan khamar di dunia, khamar dunia rasanya tidak enak bila diminum (dan sungai-sungai dari madu yang disaring) berbeda dengan madu di dunia, karena madu di dunia keluar dari perut tawon kemudian bercampur dengan lilin dan lain sebagainya (dan mereka memperoleh di dalamnya) berbagai macam jenis (dari aneka ragam buah-buahan, dan ampunan dari Rabb mereka) Rabb mereka rela terhadap mereka di samping kebaikan-Nya yang terus melimpah bagi mereka tanpa henti-hentinya, yaitu berupa kenikmatan-kenikmatan yang telah disebutkan tadi. Berbeda halnya dengan perihal seorang tuan atau pemilik hamba sahaya di dunia, karena sesungguhnya sekalipun majikan dari hamba sahaya itu berbuat baik kepadanya hal itu dibarengi dengan amarahnya, yakni terkadang sang majikan memarahinya (sama dengan orang yang kekal dalam neraka) lafal ayat ini menjadi Khabar dari Mubtada yang diperkirakan keberadaannya yakni, apakah orang yang berada dalam kenikmatan tersebut sama dengan orang yang kekal di dalam neraka (dan diberi minuman dengan air yang mendidih) yakni air yang sangat panas (sehingga memotong-motong ususnya?) artinya, minuman itu menghancurkan dan mencabik-cabik isi perutnya. Lafal Am'aa adalah bentuk jamak dari lafal Mi'a, sedangkan huruf Alifnya adalah ganti dari huruf Ya, karena sebagian dari mereka ada yang mengatakan Mi'yaani.",[["مَّثَلُ","Sebuah perumpamaan"],["ٱلْجَنَّةِ","(dari) Syurga"],["ٱلَّتِى","yang"],["وُعِدَ","dijanjikan"],["ٱلْمُتَّقُونَ ۖ","(kepada) orang-orang yang soleh"],["فِيهَآ","Di dalamnya"],["أَنْهَـٰرٌۭ","(adalah) sungai"],["مِّن","daripada"],["مَّآءٍ","air"],["غَيْرِ","tidak"],["ءَاسِنٍۢ","tercemar"],["وَأَنْهَـٰرٌۭ","dan sungai"],["مِّن","daripada"],["لَّبَنٍۢ","susu"],["لَّمْ","tidak"],["يَتَغَيَّرْ","perubahan"],["طَعْمُهُۥ","rasa dia"],["وَأَنْهَـٰرٌۭ","dan sungai"],["مِّنْ","daripada"],["خَمْرٍۢ","wain"],["لَّذَّةٍۢ","sedap"],["لِّلشَّـٰرِبِينَ","untuk (para) peminum"],["وَأَنْهَـٰرٌۭ","dan sungai"],["مِّنْ","daripada"],["عَسَلٍۢ","sayang"],["مُّصَفًّۭى ۖ","disucikan"],["وَلَهُمْ","dan untuk mereka"],["فِيهَا","di dalamnya"],["مِن","daripada"],["كُلِّ","semua"],["ٱلثَّمَرَٰتِ","buah-buahan"],["وَمَغْفِرَةٌۭ","dan pengampunan"],["مِّن","daripada"],["رَّبِّهِمْ ۖ","Tuhan mereka"],["كَمَنْ","seperti dia yang"],["هُوَ","seperti dia yang"],["خَـٰلِدٌۭ","(akan) kekal selama-lamanya"],["فِى","dalam"],["ٱلنَّارِ","neraka"],["وَسُقُوا۟","dan mereka akan diberi minum"],["مَآءً","air"],["حَمِيمًۭا","mendidih"],["فَقَطَّعَ","jadi ia terpotong-potong"],["أَمْعَآءَهُمْ","usus mereka"]]],"4561":["(Dan di antara mereka) orang-orang kafir itu (ada orang yang mendengarkan perkataanmu) sewaktu kamu berkhutbah Jumat, mereka adalah orang-orang munafik (sehingga apabila mereka keluar dari sisimu mereka berkata kepada orang-orang yang telah diberi ilmu pengetahuan) dari kalangan sahabat Nabi saw. antara lain adalah Ibnu Masud dan Ibnu Abbas r.a.; mereka mengatakan kepadanya dengan nada sinis dan mengejek, (\"Apakah yang dikatakannya tadi?\") dapat dibaca Aanifan atau Anifan, maksudnya kami kurang jelas. (Mereka itulah orang-orang yang dikunci mati hati mereka oleh Allah) dengan kekafiran (dan mengikuti hawa nafsu mereka) dalam kemunafikan.",[["وَمِنْهُم","Dan di antara mereka"],["مَّن","(adalah beberapa) siapa"],["يَسْتَمِعُ","dengar"],["إِلَيْكَ","kepada kamu"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["خَرَجُوا۟","mereka berlepas"],["مِنْ","daripada"],["عِندِكَ","kamu"],["قَالُوا۟","mereka berkata"],["لِلَّذِينَ","kepada mereka yang"],["أُوتُوا۟","telah diberikan"],["ٱلْعِلْمَ","pengetahuan itu"],["مَاذَا","Apa"],["قَالَ","(ada) katanya"],["ءَانِفًا ۚ","tadi"],["أُو۟لَـٰٓئِكَ","Itu"],["ٱلَّذِينَ","(adalah) mereka"],["طَبَعَ","Allah telah menetapkan meterai"],["ٱللَّهُ","Allah telah menetapkan meterai"],["عَلَىٰ","ke atas"],["قُلُوبِهِمْ","hati mereka"],["وَٱتَّبَعُوٓا۟","dan mereka mengikut"],["أَهْوَآءَهُمْ","keinginan mereka"]]],"4562":["(Dan orang-orang yang mendapat petunjuk) mereka adalah orang-orang mukmin (Dia menambah kepada mereka) yakni Allah swt. (petunjuk dan memberikan kepada mereka -balasan- ketakwaannya) maksudnya, Allah memberikan ilham kepada mereka untuk mengamalkan hal-hal yang dapat memelihara diri mereka dari neraka.",[["وَٱلَّذِينَ","Dan orang yang"],["ٱهْتَدَوْا۟","menerima hidayah"],["زَادَهُمْ","Dia menambah mereka"],["هُدًۭى","(dalam) bimbingan"],["وَءَاتَىٰهُمْ","dan memberi mereka"],["تَقْوَىٰهُمْ","kebenaran mereka"]]],"4563":["(Maka tidaklah yang mereka tunggu-tunggu) maksudnya tiadalah yang ditunggu-tunggu, oleh orang-orang kafir Mekah (melainkan hari kiamat yaitu kedatangannya kepada mereka) lafal An Ta'tiyahum menjadi Badal Isytimal dari lafal As-Saa'ah; yakni, perkaranya tiada lain hanyalah menunggu kedatangan kiamat kepada mereka (dengan tiba-tiba) atau secara sekonyong-konyong (karena sesungguhnya telah datang tanda-tandanya) alamat-alamatnya, antara lain diutusnya Nabi saw., terbelahnya bulan dan munculnya Ad-Dukhaan. (Maka apabila ia datang kepada mereka apakah faedahnya) yang dimaksud adalah kedatangan hari kiamat (kesadaran mereka) keinsafan mereka, tidak ada manfaatnya lagi buat mereka.",[["فَهَلْ","Kemudian lakukan"],["يَنظُرُونَ","mereka menunggu"],["إِلَّا","tetapi"],["ٱلسَّاعَةَ","(untuk) hari kiamat"],["أَن","bahawa"],["تَأْتِيَهُم","ia sepatutnya datang kepada mereka"],["بَغْتَةًۭ ۖ","tiba-tiba"],["فَقَدْ","Tetapi sesungguhnya"],["جَآءَ","telah datang"],["أَشْرَاطُهَا ۚ","petunjuknya"],["فَأَنَّىٰ","Kemudian bagaimana"],["لَهُمْ","kepada mereka"],["إِذَا","apabila"],["جَآءَتْهُمْ","telah datang kepada mereka"],["ذِكْرَىٰهُمْ","peringatan mereka"]]],"4564":["(Maka ketahuilah, bahwa sesungguhnya tidak ada Tuhan melainkan Allah) maksudnya, tetaplah engkau hai Muhammad pada prinsipmu yang demikian itu, karena itu bermanfaat kelak di hari kiamat (dan mohonlah ampunan bagi dosamu) yakni demi dosamu. Menurut suatu pendapat disebutkan, bahwa dikatakan demikian kepada Nabi Muhammad saw. dimaksud sebagai pelajaran buat umatnya, supaya mereka meniru jejaknya. Sedangkan bagi nabi dima'shum atau terpelihara dari perbuatan dosa. Memang Nabi saw. telah mengerjakan hal ini sebagaimana yang diungkapkan di dalam salah satu sabdanya yang mengatakan, \"Sesungguhnya aku selalu memohon ampun kepada Allah sebanyak seratus kali untuk setiap harinya.\" (dan bagi dosa orang-orang mukmin, laki-laki dan perempuan) di dalam ungkapan ayat ini terkandung penghormatan buat mereka, karena Allah swt. memerintahkan kepada nabi supaya memintakan ampun buat mereka. (Dan Allah mengetahui tempat kalian berusaha) tempat kalian bergerak di siang hari dalam rangka mencari upaya penghidupan (dan tempat tinggal kalian) maksudnya, tempat kalian beristirahat di tempat tidur kalian pada malam hari. Makna yang dimaksud ialah bahwa Allah swt. mengetahui semua hal ikhwal kalian, tiada sesuatu pun yang samar bagi-Nya, maka berhati-hatilah kalian kepada-Nya. Khitab dalam ayat ini ditujukan kepada orang-orang mukmin dan lain-lainnya.",[["فَٱعْلَمْ","Jadi tahulah"],["أَنَّهُۥ","bahawa [Dia]"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","tetapi"],["ٱللَّهُ","Allah"],["وَٱسْتَغْفِرْ","dan memohon ampun"],["لِذَنۢبِكَ","kerana dosamu"],["وَلِلْمُؤْمِنِينَ","dan bagi orang-orang yang beriman"],["وَٱلْمُؤْمِنَـٰتِ ۗ","dan wanita yang beriman"],["وَٱللَّهُ","Dan Allah"],["يَعْلَمُ","mengetahui"],["مُتَقَلَّبَكُمْ","pergerakan kamu"],["وَمَثْوَىٰكُمْ","dan tempat berehat kamu"]]],"4565":["(Dan orang-orang yang beriman berkata) dalam rangka meminta berjihad, (\"Mengapa tidak) atau kenapa tidak (diturunkan suatu surah?\") yang di dalamnya disebutkan masalah jihad. (Maka apabila diturunkan suatu surah yang muhkam) tiada suatu ayat pun darinya yang dimansukh (dan disebutkan di dalamnya perintah perang) anjuran untuk berperang bagi kalian (kalian lihat orang-orang yang di dalam hatinya ada penyakit) berupa keragu-raguan dalam memeluk agamamu, mereka adalah orang-orang munafik (melihat kepadamu dengan pandangan seperti orang yang pingsan) tidak sadarkan diri (karena takut mati) khawatir akan mati dan benci kepadanya; maksudnya mereka takut menghadapi peperangan dan sangat benci kepadanya. (Maka hal yang lebih utama bagi mereka) lafal ayat ini berkedudukan menjadi Mubtada, sedangkan Khabarnya ialah:",[["وَيَقُولُ","Dan katakan"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["لَوْلَا","kenapa tidak"],["نُزِّلَتْ","telah didedahkan"],["سُورَةٌۭ ۖ","a Surah"],["فَإِذَآ","Tetapi apabila"],["أُنزِلَتْ","didedahkan"],["سُورَةٌۭ","a Surah"],["مُّحْكَمَةٌۭ","tepat"],["وَذُكِرَ","dan disebut"],["فِيهَا","di dalamnya"],["ٱلْقِتَالُ ۙ","pergaduhan itu"],["رَأَيْتَ","kamu lihat"],["ٱلَّذِينَ","orang yang"],["فِى","dalam"],["قُلُوبِهِم","hati mereka"],["مَّرَضٌۭ","(adalah) penyakit"],["يَنظُرُونَ","mencari"],["إِلَيْكَ","pada kamu"],["نَظَرَ","satu pandangan"],["ٱلْمَغْشِىِّ","(dari) seorang pengsan"],["عَلَيْهِ","(dari) seorang pengsan"],["مِنَ","daripada"],["ٱلْمَوْتِ ۖ","kematian itu"],["فَأَوْلَىٰ","Tetapi lebih sesuai"],["لَهُمْ","bagi mereka"]]],"4566":["(Adalah taat dan mengucapkan perkataan yang baik) artinya bersikap baik terhadapmu. (Apabila telah tetap perintah) maksudnya, perang telah difardukan. (Maka jika mereka menepati kepada Allah) dalam beriman dan taat kepada-Nya (niscaya yang demikian itu lebih baik bagi mereka) Jumlah yang jatuh sesudah Lau merupakan Jawab dari lafal Idzaa.",[["طَاعَةٌۭ","(Adalah) ketaatan"],["وَقَوْلٌۭ","dan satu perkataan"],["مَّعْرُوفٌۭ ۚ","baik hati"],["فَإِذَا","Dan apabila"],["عَزَمَ","(adalah) ditentukan"],["ٱلْأَمْرُ","perkara itu"],["فَلَوْ","maka jika"],["صَدَقُوا۟","mereka telah benar"],["ٱللَّهَ","(kepada) Allah"],["لَكَانَ","pasti, ia akan menjadi"],["خَيْرًۭا","lebih baik"],["لَّهُمْ","bagi mereka"]]],"4567":["(Maka apakah sekiranya) dapat dibaca `Asaitum atau `Asiitum, di dalam ungkapan ini terkandung ungkapan Iltifat dari Ghaibah kepada Mukhathab; maksudnya barangkali kalian (jika kalian berpaling) memalingkan diri dari iman (kalian akan membuat kerusakan di muka bumi dan memutuskan hubungan kekeluargaan) maksudnya, kalian akan kembali kepada akhlak jahiliyah, yaitu gemar mengadakan kerusakan dan peperangan.",[["فَهَلْ","Kemudian akan"],["عَسَيْتُمْ","kamu barangkali"],["إِن","jika"],["تَوَلَّيْتُمْ","kamu diberi kuasa"],["أَن","bahawa"],["تُفْسِدُوا۟","kamu menyebabkan rasuah"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَتُقَطِّعُوٓا۟","dan terputus"],["أَرْحَامَكُمْ","pertalian persaudaraan kamu"]]],"4568":["(Mereka itulah) yakni orang-orang yang merusak itu (orang-orang yang dilaknati Allah dan ditulikan-Nya telinga mereka) dari mendengarkan perkara yang hak (dan dibutakan-Nya mata mereka) dari jalan petunjuk.",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلَّذِينَ","(adalah) mereka"],["لَعَنَهُمُ","Allah telah melaknat mereka"],["ٱللَّهُ","Allah telah melaknat mereka"],["فَأَصَمَّهُمْ","maka Dia menjadikan mereka tuli"],["وَأَعْمَىٰٓ","dan buta"],["أَبْصَـٰرَهُمْ","penglihatan mereka"]]],"4569":["(Maka apakah mereka tidak memperhatikan Alquran) yang dapat membimbing mereka untuk mengetahui perkara yang hak (ataukah) sebenarnya (pada hati) mereka (terdapat kuncinya) karena itu mereka tidak dapat memahami kebenaran.",[["أَفَلَا","Kemudian jangan"],["يَتَدَبَّرُونَ","mereka merenung"],["ٱلْقُرْءَانَ","(atas) al-Quran"],["أَمْ","atau"],["عَلَىٰ","ke atas"],["قُلُوبٍ","hati (mereka)."],["أَقْفَالُهَآ","(adalah) kunci"]]],"4570":["(Sesungguhnya orang-orang yang kembali) karena nifaq (ke belakang sesudah petunjuk itu jelas bagi mereka, setan telah menjadikan mereka memandang baik) artinya, setan telah menghiasi mereka (dan memanjangkan angan-angan mereka) dapat dibaca Umlii atau Amlaa; yang memanjangkan angan-angan mereka adalah setan berdasarkan kehendak dari Allah swt. karena pada kenyataannya Dialah yang menyesatkan mereka.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["ٱرْتَدُّوا۟","kembali"],["عَلَىٰٓ","pada"],["أَدْبَـٰرِهِم","belakang mereka"],["مِّنۢ","selepas"],["بَعْدِ","selepas"],["مَا","apa"],["تَبَيَّنَ","(telah) menjadi jelas"],["لَهُمُ","kepada mereka"],["ٱلْهُدَى ۙ","(dari) petunjuk"],["ٱلشَّيْطَـٰنُ","Syaitan"],["سَوَّلَ","terpikat"],["لَهُمْ","[untuk] mereka"],["وَأَمْلَىٰ","dan harapan yang berpanjangan"],["لَهُمْ","bagi mereka"]]],"4571":["(Yang demikian itu) yakni kesesatan mereka itu (karena sesungguhnya mereka itu berkata kepada orang-orang yang benci kepada apa yang diturunkan Allah) yakni berkata kepada orang-orang musyrik, (\"Kami akan mematuhi kalian dalam beberapa urusan\") yaitu bersedia untuk membantu dalam memusuhi Nabi saw. dan menghasut kaum muslimin supaya mereka tidak mau berjihad bersamanya. Orang-orang munafik itu mengatakan demikian secara rahasia, akan tetapi kemudian Allah swt. menampakkannya (sedangkan Allah mengetahui rahasia mereka) kalau dibaca Asraarahum berarti bentuk jamak dari lafal Sirrun yang artinya rahasia, kalau dibaca Israarahum berarti Mashdar.",[["ذَٰلِكَ","Itu"],["بِأَنَّهُمْ","(adalah) kerana mereka"],["قَالُوا۟","[mereka] berkata"],["لِلَّذِينَ","kepada mereka yang"],["كَرِهُوا۟","benci"],["مَا","apa"],["نَزَّلَ","Allah telah menurunkan"],["ٱللَّهُ","Allah telah menurunkan"],["سَنُطِيعُكُمْ","Kami akan mematuhi kamu"],["فِى","dalam"],["بَعْضِ","bahagian"],["ٱلْأَمْرِ ۖ","(dari) perkara itu"],["وَٱللَّهُ","Tetapi Allah"],["يَعْلَمُ","mengetahui"],["إِسْرَارَهُمْ","rahsia mereka"]]],"4572":["(Bagaimanakah) keadaan mereka (apabila malaikat mencabut nyawa mereka seraya memukul) lafal Yadhribuuna merupakan Hal atau kata keterangan keadaan dari malaikat (muka dan punggung mereka) dengan pemukul-pemukul dari besi.",[["فَكَيْفَ","Kemudian bagaimana"],["إِذَا","apabila"],["تَوَفَّتْهُمُ","bawa mereka dalam kematian"],["ٱلْمَلَـٰٓئِكَةُ","para Malaikat"],["يَضْرِبُونَ","menarik perhatian"],["وُجُوهَهُمْ","muka mereka"],["وَأَدْبَـٰرَهُمْ","dan belakang mereka"]]],"4573":["(Yang demikian itu) yakni, kematian mereka seperti yang telah disebutkan tadi (karena sesungguhnya mereka mengikuti apa yang menimbulkan kemurkaan Allah dan karena mereka membenci keridaan-Nya) artinya, mereka tidak mau mengamalkan hal-hal yang membuat keridaan-Nya (sebab itu Allah menghapus pahala amal-amal mereka.)",[["ذَٰلِكَ","Itu"],["بِأَنَّهُمُ","(adalah) kerana mereka"],["ٱتَّبَعُوا۟","diikuti"],["مَآ","apa"],["أَسْخَطَ","marah"],["ٱللَّهَ","Allah"],["وَكَرِهُوا۟","dan dibenci"],["رِضْوَٰنَهُۥ","Keredhaannya"],["فَأَحْبَطَ","jadi Dia menjadikan tidak berharga"],["أَعْمَـٰلَهُمْ","perbuatan mereka"]]],"4574":["(Atau apakah orang-orang yang ada penyakit dalam kalbunya mengira bahwa Allah tidak akan menampakkan kedengkian mereka) kepada Nabi saw. dan orang-orang mukmin?",[["أَمْ","Atau buat"],["حَسِبَ","fikir"],["ٱلَّذِينَ","orang yang"],["فِى","dalam"],["قُلُوبِهِم","hati mereka"],["مَّرَضٌ","(adalah) penyakit"],["أَن","bahawa"],["لَّن","tidak pernah"],["يُخْرِجَ","adakah Allah akan melahirkan"],["ٱللَّهُ","adakah Allah akan melahirkan"],["أَضْغَـٰنَهُمْ","kebencian mereka"]]],"4575":["(Dan kalau Kami menghendaki, niscaya Kami tunjukkan mereka kepadamu) atau Kami kenalkan mereka kepadamu, kemudian huruf Lam Taukid diulangi pada firman berikutnya (sehingga kamu benar-benar dapat mengenal mereka dengan tanda-tanda) berikut ciri-ciri khas mereka. (Dan sungguh kamu benar-benar akan mengenal mereka) huruf Wawu menunjukkan makna bagi Qasam atau sumpah yang tidak disebutkan, sedangkan lafal sesudahnya merupakan Jawabnya (dari kiasan-kiasan perkataan mereka) atau makna perkataan mereka, bilamana mereka berkata di hadapanmu mereka pasti menyindir dengan kata-kata yang mengandung hinaan terhadap perkara kaum muslimin (dan Allah mengetahui perbuatan-perbuatan kalian.)",[["وَلَوْ","Dan jika"],["نَشَآءُ","Kami berkehendak"],["لَأَرَيْنَـٰكَهُمْ","sesungguhnya Kami dapat memperlihatkannya kepadamu"],["فَلَعَرَفْتَهُم","dan kamu akan mengenali mereka"],["بِسِيمَـٰهُمْ ۚ","dengan markah mereka"],["وَلَتَعْرِفَنَّهُمْ","tetapi pasti, kamu akan mengenali mereka"],["فِى","oleh"],["لَحْنِ","(nada)."],["ٱلْقَوْلِ ۚ","(daripada) ucapan mereka"],["وَٱللَّهُ","Dan Allah"],["يَعْلَمُ","mengetahui"],["أَعْمَـٰلَكُمْ","perbuatan kamu"]]],"4576":["(Dan sesungguhnya Kami benar-benar akan menguji kalian) mencoba kalian dengan berjihad dan lainnya (agar Kami mengetahui) dengan pengetahuan yang tampak (orang-orang yang berjihad dan bersabar di antara kalian) dalam berjihad dan lainnya (dan agar Kami menyatakan) menampakkan (hal ikhwal kalian) tentang ketaatan kalian dan kedurhakaan kalian di dalam masalah jihad dan masalah-masalah lainnya. Ketiga Fi'il yang ada dalam ayat ini, ketiga-tiganya dapat dibaca dengan memakai huruf Mudhara'ah Ya atau Nun.",[["وَلَنَبْلُوَنَّكُمْ","Dan sesungguhnya Kami akan menguji kamu"],["حَتَّىٰ","sehingga"],["نَعْلَمَ","Kami membuat jelas"],["ٱلْمُجَـٰهِدِينَ","mereka yang berusaha"],["مِنكُمْ","antara kamu"],["وَٱلصَّـٰبِرِينَ","dan yang sabar"],["وَنَبْلُوَا۟","dan Kami akan menguji"],["أَخْبَارَكُمْ","urusan kamu"]]],"4577":["(Sesungguhnya orang-orang kafir dan menghalang-halangi jalan Allah) jalan yang hak (dan memusuhi rasul) atau menentangnya (setelah petunjuk itu jelas bagi mereka) yang dimaksud petunjuk adalah jalan Allah tadi (mereka tidak dapat memberi mudarat kepada Allah sedikit pun. Dan Allah akan menghapuskan amal mereka) seperti sedekah dan lain-lainnya, yaitu pahalanya. Di akhirat kelak mereka tidak akan dapat melihat pahalanya. Ayat ini diturunkan berkenaan dengan orang-orang kafir yang terlibat dalam perang Badar, atau orang-orang kafir Bani Quraizhah dan Bani Nadhir.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["وَصَدُّوا۟","dan berpaling"],["عَن","daripada"],["سَبِيلِ","(jalan) Allah"],["ٱللَّهِ","(jalan) Allah"],["وَشَآقُّوا۟","dan menentang"],["ٱلرَّسُولَ","Rasul"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["مَا","[apa]"],["تَبَيَّنَ","(telah) diperjelaskan"],["لَهُمُ","kepada mereka"],["ٱلْهُدَىٰ","bimbingan"],["لَن","tidak pernah"],["يَضُرُّوا۟","adakah mereka akan membahayakan"],["ٱللَّهَ","Allah"],["شَيْـًۭٔا","(dalam) apa-apa"],["وَسَيُحْبِطُ","dan Dia akan membuat tidak bernilai"],["أَعْمَـٰلَهُمْ","perbuatan mereka"]]],"4578":["(Hai orang-orang yang beriman! Taatlah kepada Allah dan taatlah kepada rasul dan janganlah kalian merusakkan amal-amal kalian) dengan melakukan perbuatan-perbuatan maksiat, umpamanya.",[["۞ يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوٓا۟","Wahai orang yang beriman"],["أَطِيعُوا۟","Patuh"],["ٱللَّهَ","Allah"],["وَأَطِيعُوا۟","dan taat"],["ٱلرَّسُولَ","Rasul"],["وَلَا","dan jangan"],["تُبْطِلُوٓا۟","buat sia-sia"],["أَعْمَـٰلَكُمْ","perbuatan kamu"]]],"4579":["(Sesungguhnya orang-orang yang kafir dan menghalangi jalan Allah) tuntunan-Nya, yaitu jalan petunjuk (kemudian mereka mati dalam keadaan kafir, maka sekali-kali Allah tidak akan memberi ampun kepada mereka) ayat ini diturunkan berkenaan dengan orang-orang kafir yang dikubur di Al-Qulaib, seusai perang Badar.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["وَصَدُّوا۟","dan berpaling"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["ثُمَّ","kemudian"],["مَاتُوا۟","meninggal dunia"],["وَهُمْ","sedangkan mereka"],["كُفَّارٌۭ","(adalah) orang-orang kafir"],["فَلَن","tidak pernah"],["يَغْفِرَ","adakah Allah akan mengampuni"],["ٱللَّهُ","adakah Allah akan mengampuni"],["لَهُمْ","mereka"]]],"4580":["(Janganlah kalian lemah) merasa lemah (dan minta damai) dapat dibaca As-Salmi atau As-Silmi, artinya damai bersama dengan orang-orang kafir bila kalian bertemu dengan mereka dalam perang (padahal kalianlah yang di atas) lafal Al-A'launa asalnya adalah Al-A'lawuuna, kemudian Wawu Lam Fi'ilnya dibuang sehingga jadilah Al-A'launa, artinya, yang menang dan yang mengalahkan (dan Allah pun beserta kalian) yakni bantuan dan pertolongan-Nya (dan Dia sekali-kali tidak akan mengurangi) Allah tidak akan mengurangi kalian (amal-amal kalian) pahala amal-amal kalian.",[["فَلَا","Jadi (jangan)"],["تَهِنُوا۟","melemahkan"],["وَتَدْعُوٓا۟","dan panggil"],["إِلَى","bagi"],["ٱلسَّلْمِ","kedamaian"],["وَأَنتُمُ","sedangkan kamu"],["ٱلْأَعْلَوْنَ","(adalah) unggul"],["وَٱللَّهُ","dan Allah"],["مَعَكُمْ","(ada) bersama kamu"],["وَلَن","dan tidak pernah"],["يَتِرَكُمْ","akan menghalang kamu"],["أَعْمَـٰلَكُمْ","(dari) perbuatan kamu"]]],"4581":["(Sesungguhnya kehidupan dunia) maksudnya, menyibukkan diri dalam kehidupan dunia (hanyalah permainan dan senda gurau. Dan jika kalian beriman serta bertakwa) kepada Allah, yang demikian itu adalah termasuk perkara akhirat (Allah akan memberikan pahala kepada kalian dan Dia tidak akan meminta harta-harta kalian) semuanya, melainkan hanya zakat yang diwajibkan.",[["إِنَّمَا","Hanya"],["ٱلْحَيَوٰةُ","kehidupan"],["ٱلدُّنْيَا","dunia"],["لَعِبٌۭ","(adalah) bermain"],["وَلَهْوٌۭ ۚ","dan keseronokan"],["وَإِن","Dan jika"],["تُؤْمِنُوا۟","kamu beriman"],["وَتَتَّقُوا۟","dan bertakwalah kepada Allah"],["يُؤْتِكُمْ","Dia akan memberi kamu"],["أُجُورَكُمْ","ganjaran kamu"],["وَلَا","dan bukan"],["يَسْـَٔلْكُمْ","akan bertanya kepada kamu"],["أَمْوَٰلَكُمْ","(untuk) kekayaan kamu"]]],"4582":["(Jika Dia memintanya dari kalian lalu mendesak kalian) mendesak meminta zakat tersebut (niscaya kalian akan kikir dan keluarlah) karena kekikiran kalian (kedengkian kalian) terhadap agama Islam.",[["إِن","Jika"],["يَسْـَٔلْكُمُوهَا","Dia akan meminta kamu untuk itu"],["فَيُحْفِكُمْ","dan tekan kamu"],["تَبْخَلُوا۟","kamu akan menahan"],["وَيُخْرِجْ","dan Dia akan melahirkan"],["أَضْغَـٰنَكُمْ","kebencian kamu"]]],"4583":["(Ingatlah kalian) wahai, kalian ingatlah (kalian ini orang-orang yang diajak untuk menafkahkan harta kalian pada jalan Allah) maksudnya untuk menafkahkan apa yang telah diwajibkan atas kalian, yaitu zakat. (Maka di antara kalian ada orang yang kikir, dan siapa yang kikir sesungguhnya dia hanyalah kikir terhadap dirinya sendiri) lafal Bakhila dapat bermuta'addikan 'Ala atau 'An, untuk itu dapat dikatakan Rakhila 'Alaihi dan Bakhila 'Anhu. (Dan Allahlah Yang Maha Kaya) artinya, tidak membutuhkan infak kalian (sedangkan kalianlah orang-orang yang berhajat) kepada-Nya (dan jika kalian berpaling) dari taat kepada-Nya (niscaya Dia akan mengganti kalian dengan kaum yang lain) Dia akan menjadikan yang lain sebagai pengganti kalian (dan mereka tidak akan seperti kalian) tidak akan berpaling dari taat kepada-Nya, bahkan mereka benar-benar akan taat kepada-Nya.",[["هَـٰٓأَنتُمْ","Di sini kamu"],["هَـٰٓؤُلَآءِ","ini"],["تُدْعَوْنَ","dipanggil"],["لِتُنفِقُوا۟","untuk berbelanja"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ","(dari) Allah"],["فَمِنكُم","tetapi di antara kamu"],["مَّن","(adalah beberapa) siapa"],["يَبْخَلُ ۖ","menahan"],["وَمَن","dan sesiapa"],["يَبْخَلْ","menahan"],["فَإِنَّمَا","kemudian sahaja"],["يَبْخَلُ","dia menahan"],["عَن","daripada"],["نَّفْسِهِۦ ۚ","dirinya sendiri"],["وَٱللَّهُ","Tetapi Allah"],["ٱلْغَنِىُّ","(adalah) Bebas daripada keperluan"],["وَأَنتُمُ","sedangkan kamu"],["ٱلْفُقَرَآءُ ۚ","(adalah) orang yang memerlukan"],["وَإِن","Dan jika"],["تَتَوَلَّوْا۟","kamu berpaling"],["يَسْتَبْدِلْ","Dia akan menggantikan kamu"],["قَوْمًا","(dengan) suatu kaum"],["غَيْرَكُمْ","selain kamu"],["ثُمَّ","kemudian"],["لَا","tidak"],["يَكُونُوٓا۟","mereka akan menjadi"],["أَمْثَـٰلَكُم","(yang) menyukai kamu"]]],"4584":["(Sesungguhnya Kami telah memberikan kemenangan kepadamu) maksudnya Kami telah memastikan kemenangan bagimu atas kota Mekah dan kota-kota lainnya di masa mendatang secara paksa melalui jihadmu (yaitu kemenangan yang nyata) artinya, kemenangan yang jelas dan nyata.",[["إِنَّا","Sesungguhnya"],["فَتَحْنَا","Kami telah memberikan kemenangan"],["لَكَ","kepada kamu"],["فَتْحًۭا","sebuah kemenangan"],["مُّبِينًۭا","yang nyata"]]],"4585":["(Supaya Allah memberi ampunan kepadamu) berkat jihadmu itu (terhadap dosamu yang telah lalu dan yang akan datang) supaya umatmu mau berjihad karena akan mendapat ampunan seperti kamu. Pengertian ayat ini mengandung penakwilan, mengingat para nabi maksum dari segala perbuatan dosa yang hal ini telah ditetapkan berdasarkan dalil aqli dan naqli. Dengan demikian maka huruf Lam pada permulaan ayat ini menunjukkan makna Illatul Ghaaiyyah dan lafal yang dimasukinya merupakan Musabbab bukan Sebab (serta menyempurnakan) melalui kemenangan tersebut (nikmat-Nya) pemberian nikmat-Nya (atasmu dan memimpin kamu) melalui kemenangan itu (kepada jalan) yakni tuntunan (yang lurus) artinya Allah memantapkan kamu pada agama Islam.",[["لِّيَغْفِرَ","Itu boleh memaafkan"],["لَكَ","bagi kamu"],["ٱللَّهُ","Allah"],["مَا","apa"],["تَقَدَّمَ","didahulukan"],["مِن","daripada"],["ذَنۢبِكَ","dosa kamu"],["وَمَا","dan apa"],["تَأَخَّرَ","akan menyusul"],["وَيُتِمَّ","dan lengkap"],["نِعْمَتَهُۥ","nikmatNya"],["عَلَيْكَ","ke atas kamu"],["وَيَهْدِيَكَ","dan membimbing kamu"],["صِرَٰطًۭا","(ke) Jalan"],["مُّسْتَقِيمًۭا","Lurus"]]],"4586":["(Dan supaya Allah menolongmu) melalui agama Islam itu (dengan pertolongan yang mulia) tidak pernah hina atau pertolongan yang kuat dan tidak dapat dikalahkan.",[["وَيَنصُرَكَ","Dan Allah boleh menolong kamu"],["ٱللَّهُ","Dan Allah boleh menolong kamu"],["نَصْرًا","(dengan) bantuan"],["عَزِيزًا","perkasa"]]],"4587":["(Dialah yang telah menurunkan ketenangan) yakni ketenteraman (ke dalam kalbu orang-orang mukmin supaya keimanan mereka bertambah di samping keimanan mereka) kepada syariat-syariat agama, yaitu sewaktu turun salah satu daripadanya mereka langsung beriman antara lain ialah syariat berjihad. (Dan kepunyaan Allahlah tentara langit dan bumi) jika Dia menghendaki untuk menolong agama-Nya tanpa kalian, niscaya Dia dapat melakukannya (dan adalah Allah Maha Mengetahui) semua makhluk-Nya (lagi Maha Bijaksana) di dalam perbuatan-Nya, yakni Dia terus-menerus bersifat demikian.",[["هُوَ","Dia"],["ٱلَّذِىٓ","(ialah) Yang"],["أَنزَلَ","diturunkan"],["ٱلسَّكِينَةَ","[the] ketenangan"],["فِى","dalam (ke)"],["قُلُوبِ","(the) hati"],["ٱلْمُؤْمِنِينَ","(dari) orang-orang yang beriman"],["لِيَزْدَادُوٓا۟","supaya mereka bertambah"],["إِيمَـٰنًۭا","(dalam) iman"],["مَّعَ","dengan"],["إِيمَـٰنِهِمْ ۗ","iman mereka"],["وَلِلَّهِ","Dan untuk Allah"],["جُنُودُ","(adalah) tuan rumah"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["وَكَانَ","dan Allah"],["ٱللَّهُ","dan Allah"],["عَلِيمًا","Maha Mengetahui"],["حَكِيمًۭا","Maha Bijaksana"]]],"4588":["(Supaya Dia memasukkan) lafal Liyudkhila ini berta'alluq kepada lafal yang tidak disebutkan, yakni Dia memerintahkan berjihad supaya memasukkan (orang-orang mukmin laki-laki dan perempuan ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya dan supaya Dia menutupi kesalahan-kesalahan mereka. Dan yang demikian itu adalah keberuntungan yang besar di sisi Allah.)",[["لِّيُدْخِلَ","Supaya Dia mengakui"],["ٱلْمُؤْمِنِينَ","lelaki yang beriman"],["وَٱلْمُؤْمِنَـٰتِ","dan wanita yang beriman"],["جَنَّـٰتٍۢ","(ke) Taman"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهَا","di bawah mereka"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["خَـٰلِدِينَ","(untuk) kekal selama-lamanya"],["فِيهَا","di dalamnya"],["وَيُكَفِّرَ","dan (untuk) mengalih keluar"],["عَنْهُمْ","daripada mereka"],["سَيِّـَٔاتِهِمْ ۚ","kemungkaran mereka"],["وَكَانَ","dan adalah"],["ذَٰلِكَ","bahawa"],["عِندَ","dengan"],["ٱللَّهِ","Allah"],["فَوْزًا","satu kejayaan"],["عَظِيمًۭا","yang besar"]]],"4589":["(Dan supaya Dia mengazab orang-orang munafik laki-laki dan perempuan dan orang-orang musyrik laki-laki dan perempuan yang mereka itu berprasangka buruk terhadap Allah) dapat dibaca As-Sau' atau As-Suu' dan demikian pula pada ayat selanjutnya. Mereka berprasangka bahwa Allah pasti tidak akan menolong Nabi Muhammad saw. dan orang-orang mukmin. (Mereka akan mendapat giliran yang amat buruk) yaitu akan mendapatkan kehinaan dan azab (dan Allah memurkai mereka dan mengutuk mereka) artinya menjauhkan mereka dari rahmat-Nya (serta menyediakan bagi mereka neraka Jahanam. Dan neraka Jahanam itulah seburuk-buruk tempat kembali) tempat kembali yang paling buruk.",[["وَيُعَذِّبَ","Dan Dia (boleh) mengazab"],["ٱلْمُنَـٰفِقِينَ","lelaki munafik"],["وَٱلْمُنَـٰفِقَـٰتِ","dan perempuan-perempuan munafik"],["وَٱلْمُشْرِكِينَ","dan orang-orang musyrik"],["وَٱلْمُشْرِكَـٰتِ","dan perempuan-perempuan musyrik"],["ٱلظَّآنِّينَ","yang beranggapan"],["بِٱللَّهِ","tentang Allah"],["ظَنَّ","satu andaian"],["ٱلسَّوْءِ ۚ","jahat"],["عَلَيْهِمْ","atas mereka"],["دَآئِرَةُ","(adalah) giliran"],["ٱلسَّوْءِ ۖ","(dari) kejahatan"],["وَغَضِبَ","dan kemurkaan Allah (adalah)"],["ٱللَّهُ","dan kemurkaan Allah (adalah)"],["عَلَيْهِمْ","ke atas mereka"],["وَلَعَنَهُمْ","dan Dia telah mengutuk mereka"],["وَأَعَدَّ","dan disediakan"],["لَهُمْ","bagi mereka"],["جَهَنَّمَ ۖ","Neraka"],["وَسَآءَتْ","dan jahat"],["مَصِيرًۭا","(adalah) destinasi"]]],"4590":["(Dan kepunyaan Allahlah tentara langit dan bumi. Dan adalah Allah Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) di dalam perbuatan-Nya, yakni Dia terus-menerus bersifat demikian.",[["وَلِلَّهِ","Dan untuk Allah"],["جُنُودُ","(adalah) tuan rumah"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["وَكَانَ","dan Allah"],["ٱللَّهُ","dan Allah"],["عَزِيزًا","(adalah) Maha Perkasa"],["حَكِيمًا","Maha Bijaksana"]]],"4591":["(Sesungguhnya Kami mengutus kamu sebagai saksi) atas umatmu pada hari kiamat nanti (dan pembawa berita gembira) kepada mereka di dunia (dan pemberi peringatan) maksudnya memberi peringatan dan mempertakuti mereka selama di dunia akan siksa neraka kelak di akhirat bila mereka melakukan perbuatan yang berdosa.",[["إِنَّآ","Sesungguhnya Kami"],["أَرْسَلْنَـٰكَ","[Kami] telah menghantar kamu"],["شَـٰهِدًۭا","(sebagai) saksi"],["وَمُبَشِّرًۭا","dan (sebagai) pembawa berita gembira"],["وَنَذِيرًۭا","dan (sebagai) pemberi amaran"]]],"4592":["(Supaya kamu sekalian beriman kepada Allah dan Rasul-Nya) lafal Litu`minuu dapat dibaca Liyu`minuu, demikian pula pada tiga tempat lainnya dalam ayat ini, sesudahnya (menguatkan agama-Nya) maksudnya supaya kalian menolong agama-Nya; dan menurut suatu qiraat lafal Tu'azziruuhu dibaca Tu'azzizuuhu (membesarkan-Nya) artinya supaya kalian mengagungkan-Nya, Dhamir pada kedua fi'il tersebut dapat merujuk, kepada Allah atau Rasul-Nya (dan supaya kalian bertasbih kepada-Nya) yakni kepada Allah (di waktu pagi dan petang) pada setiap pagi dan sore.",[["لِّتُؤْمِنُوا۟","Supaya kamu beriman"],["بِٱللَّهِ","kepada Allah"],["وَرَسُولِهِۦ","dan Rasul-Nya"],["وَتُعَزِّرُوهُ","dan (boleh) memuliakannya"],["وَتُوَقِّرُوهُ","dan hormatilah dia"],["وَتُسَبِّحُوهُ","dan bertasbih kepada-Nya"],["بُكْرَةًۭ","pagi"],["وَأَصِيلًا","dan petang"]]],"4593":["(Sesungguhnya orang-orang yang berjanji setia kepada kamu) yaitu melakukan baiat Ridwan di Hudaibiah (sesungguhnya mereka berjanji setia kepada Allah) pengertian ini sama dengan makna yang terkandung dalam ayat lainnya, yaitu firman-Nya, \"Barang siapa yang menaati rasul, sesungguhnya ia telah menaati Allah.\" (Q.S. An-Nisa, 80). (Tangan kekuasaan Allah berada di atas tangan mereka) yang berbaiat kepada Nabi saw. Maksudnya, bahwa Allah swt. menyaksikan pembaiatan mereka, maka Dia kelak akan memberikan balasan pahala-Nya kepada mereka (maka barang siapa yang melanggar janjinya) yakni merusak baiatnya (maka sesungguhnya ia hanya melanggar) karena itu akibat dari pelanggarannya akan menimpa (dirinya sendiri dan barang siapa menepati janjinya kepada Allah maka Allah akan memberinya) dapat dibaca Fasaya`tiihi atau Fasanu`tiihi, kalau dibaca Fasanu`tihi artinya, Kami akan memberinya (pahala yang besar.)",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يُبَايِعُونَكَ","berikrar taat setia kepadamu"],["إِنَّمَا","sahaja"],["يُبَايِعُونَ","mereka berikrar taat setia"],["ٱللَّهَ","(kepada) Allah"],["يَدُ","(The) Tangan"],["ٱللَّهِ","(milik) Allah"],["فَوْقَ","(sudah) tamat"],["أَيْدِيهِمْ ۚ","tangan mereka"],["فَمَن","Kemudian sesiapa sahaja"],["نَّكَثَ","melanggar (sumpahnya)"],["فَإِنَّمَا","kemudian sahaja"],["يَنكُثُ","dia pecah"],["عَلَىٰ","terhadap"],["نَفْسِهِۦ ۖ","dirinya sendiri"],["وَمَنْ","dan sesiapa"],["أَوْفَىٰ","memenuhi"],["بِمَا","apa"],["عَـٰهَدَ","dia telah berakad"],["عَلَيْهُ","(dengan)"],["ٱللَّهَ","Allah"],["فَسَيُؤْتِيهِ","tidak lama lagi Dia akan memberinya"],["أَجْرًا","ganjaran"],["عَظِيمًۭا","yang besar"]]],"4594":["(Orang-orang Badui yang tertinggal akan mengatakan) yang dimaksud adalah mereka yang tinggal di sekitar kota Madinah yang tidak mau ikut dengan kamu sewaktu kamu meminta mereka supaya berangkat bersamamu ke Mekah pada tahun perjanjian Hudaibiah karena merasa takut orang-orang Quraisy nanti akan mencegatmu. Mereka akan mengatakan sekembalimu dari Mekah, (\"Harta dan keluarga kami telah merintangi kami) sehingga kami tidak dapat keluar untuk berangkat bersamamu (maka mohonkanlah ampunan untuk kami\") kepada Allah, karena kami tidak dapat ikut keluar bersamamu. Lalu Allah menjawab kepada mereka seraya mendustakan alasan mereka itu melalui firman selanjutnya, (\"Mereka mengucapkan dengan lidahnya) yaitu meminta untuk memohonkan ampunan buat mereka dan perkataan mereka yang lainnya sebelum itu (apa yang tidak ada dalam hatinya) karena mereka adalah orang-orang yang berdusta di dalam alasannya. (Katakanlah, \"Maka siapakah) Istifham atau kata tanya di sini mengandung makna negatif, yakni tidak ada seorang pun (yang dapat menghalang-halangi kehendak Allah jika Dia menghendaki kemudaratan bagi kalian) dapat dibaca Dharran atau Dhurran (atau jika Dia menghendaki manfaat bagi kalian.\" Sebenarnya Allah Maha Mengetahui apa yang kalian kerjakan) artinya Dia terus-menerus bersifat demikian.",[["سَيَقُولُ","Akan berkata"],["لَكَ","kepada kamu"],["ٱلْمُخَلَّفُونَ","mereka yang tinggal di belakang"],["مِنَ","daripada"],["ٱلْأَعْرَابِ","orang Badwi"],["شَغَلَتْنَآ","Membuat kami sibuk"],["أَمْوَٰلُنَا","harta kita"],["وَأَهْلُونَا","dan keluarga kita"],["فَٱسْتَغْفِرْ","jadi minta ampun"],["لَنَا ۚ","bagi kami"],["يَقُولُونَ","Mereka berkata"],["بِأَلْسِنَتِهِم","dengan lidah mereka"],["مَّا","apa"],["لَيْسَ","bukan"],["فِى","dalam"],["قُلُوبِهِمْ ۚ","hati mereka"],["قُلْ","Katakanlah"],["فَمَن","Kemudian siapa"],["يَمْلِكُ","mempunyai kuasa"],["لَكُم","bagi kamu"],["مِّنَ","terhadap"],["ٱللَّهِ","Allah"],["شَيْـًٔا","(dalam) apa-apa"],["إِنْ","jika"],["أَرَادَ","Dia berniat"],["بِكُمْ","bagi kamu"],["ضَرًّا","kemudaratan"],["أَوْ","atau"],["أَرَادَ","Dia berniat"],["بِكُمْ","bagi kamu"],["نَفْعًۢا ۚ","satu faedah"],["بَلْ","Bahkan"],["كَانَ","ialah"],["ٱللَّهُ","Allah"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["خَبِيرًۢا","Maha Mengetahui"]]],"4595":["(Tetapi) lafal Bal pada kedua tempat, yakni pada ayat ini dan ayat sebelumnya, menunjukkan makna Intiqal atau perpindahan dari suatu pembahasan kepada pembahasan yang lain (kalian menyangka bahwa rasul dan orang-orang mukmin tidak sekali-kali akan kembali kepada keluarganya untuk selama-lamanya dan hal tersebut dipandang baik menurut hati kalian) yakni bahwa mereka mengharapkan supaya rasul dan orang-orang mukmin tertumpas habis sehingga mereka tidak kembali lagi ke Madinah (dan kalian telah menyangka dengan sangkaan-sangkaan yang buruk) yakni sangkaan seperti ini dan sangkaan-sangkaan yang buruk lainnya (dan kalian menjadi kaum yang binasa) lafal Buura adalah bentuk jamak dari lafal Baairun, yakni binasa menurut Allah dengan berprasangka seperti itu.",[["بَلْ","Bahkan"],["ظَنَنتُمْ","kamu fikir"],["أَن","bahawa"],["لَّن","(akan) tidak pernah"],["يَنقَلِبَ","kembali"],["ٱلرَّسُولُ","Rasul"],["وَٱلْمُؤْمِنُونَ","dan orang-orang yang beriman"],["إِلَىٰٓ","kepada"],["أَهْلِيهِمْ","keluarga mereka"],["أَبَدًۭا","pernah"],["وَزُيِّنَ","yang dibuat kelihatan adil"],["ذَٰلِكَ","yang dibuat kelihatan adil"],["فِى","dalam"],["قُلُوبِكُمْ","hati kamu"],["وَظَنَنتُمْ","Dan kamu mengandaikan"],["ظَنَّ","satu andaian"],["ٱلسَّوْءِ","jahat"],["وَكُنتُمْ","dan kamu menjadi"],["قَوْمًۢا","suatu kaum"],["بُورًۭا","hancur"]]],"4596":["(Dan barang siapa yang tidak beriman kepada Allah dan rasul-Nya maka sesungguhnya Kami menyediakan untuk orang-orang kafir neraka yang menyala-nyala) neraka yang apinya sangat besar nyalanya.",[["وَمَن","Dan sesiapa"],["لَّمْ","(telah) tidak beriman"],["يُؤْمِنۢ","(telah) tidak beriman"],["بِٱللَّهِ","kepada Allah"],["وَرَسُولِهِۦ","dan Rasul-Nya"],["فَإِنَّآ","maka sesungguhnya Kami"],["أَعْتَدْنَا","[Kami] telah bersedia"],["لِلْكَـٰفِرِينَ","bagi orang-orang kafir"],["سَعِيرًۭا","api yang menyala-nyala"]]],"4597":["(Dan hanya kepunyaan Allahlah kerajaan langit dan bumi, Dia memberi ampun kepada siapa yang dikehendaki-Nya dan mengazab siapa yang dikehendaki-Nya Dan adalah Allah Maha Pengampun lagi Maha Penyayang\") Dia terus menerus bersifat demikian.",[["وَلِلَّهِ","Dan untuk Allah"],["مُلْكُ","(ialah) kerajaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["يَغْفِرُ","Dia memaafkan"],["لِمَن","yang"],["يَشَآءُ","Dia kehendaki"],["وَيُعَذِّبُ","dan menghukum"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["وَكَانَ","Dan adakah"],["ٱللَّهُ","Allah"],["غَفُورًۭا","Selalu Memaafkan"],["رَّحِيمًۭا","Maha Mengasihani"]]],"4598":["(Orang-orang yang tertinggal itu akan berkata) yakni mereka yang telah disebutkan tadi (apabila kalian berangkat menuju tempat barang rampasan) yang dimaksud adalah ganimah perang Khaibar (untuk mengambilnya, \"Biarkanlah kami) maksudnya janganlah kalian halangi kami (mengikuti kalian\") supaya kami dapat mengambil sebagian dari ganimah tersebut (mereka bermaksud) dengan sikap mereka yang demikian itu (hendak merubah keputusan Allah) menurut suatu qiraat dibaca Kalimullah artinya, janji atau ancaman-Nya. Maksudnya, mereka mengubah ancaman Allah dengan ganimah Khaibar yang khusus hanya untuk mereka yang ikut dalam baiat Ridwan di Hudaibiyah. (Katakanlah, \"Kalian sekali-kali tidak boleh mengikuti kami; demikian Allah telah menetapkan sebelumnya\") sebelum kami kembali (mereka akan mengatakan, \"Sebenarnya kalian dengki kepada kami\") bila kami ikut memperoleh ganimah bersama kalian, karena bagian kalian akan berkurang jadinya. (Bahkan mereka tidak mengerti) masalah agama (melainkan sedikit sekali) dari kalangan mereka yang mengerti tentangnya.",[["سَيَقُولُ","Akan berkata"],["ٱلْمُخَلَّفُونَ","mereka yang tinggal di belakang"],["إِذَا","apabila"],["ٱنطَلَقْتُمْ","kamu tetapkan"],["إِلَىٰ","ke arah"],["مَغَانِمَ","(yang) rampasan perang"],["لِتَأْخُذُوهَا","untuk mengambilnya"],["ذَرُونَا","Izinkan kami"],["نَتَّبِعْكُمْ ۖ","(untuk) mengikut kamu"],["يُرِيدُونَ","Mereka mahu"],["أَن","kepada"],["يُبَدِّلُوا۟","berubah"],["كَلَـٰمَ","(the) Perkataan"],["ٱللَّهِ ۚ","(milik) Allah"],["قُل","Katakanlah"],["لَّن","tidak pernah"],["تَتَّبِعُونَا","adakah kamu akan mengikuti kami"],["كَذَٰلِكُمْ","Demikianlah"],["قَالَ","Allah berfirman"],["ٱللَّهُ","Allah berfirman"],["مِن","sebelum"],["قَبْلُ ۖ","sebelum"],["فَسَيَقُولُونَ","Kemudian mereka akan berkata"],["بَلْ","Bahkan"],["تَحْسُدُونَنَا ۚ","kamu dengki kami"],["بَلْ","Bahkan"],["كَانُوا۟","mereka adalah"],["لَا","tidak"],["يَفْقَهُونَ","persefahaman"],["إِلَّا","kecuali"],["قَلِيلًۭا","sedikit"]]],"4599":["(Katakanlah kepada orang-orang Badui yang tertinggal,) yakni orang-orang Badui yang tertinggal tadi sebagai cobaan buat mereka (\"Kalian akan diajak untuk memerangi kaum yang mempunyai) kaum yang memiliki (kekuatan yang besar) menurut suatu pendapat dikatakan, bahwa yang dimaksud adalah menghadapi orang-orang Bani Hanifah yang menguasai tanah Yamamah, dan menurut pendapat yang lain lagi, yang dimaksud adalah kerajaan Persia dan kerajaan Romawi (kalian akan memerangi mereka) lafal ayat ini menjadi Hal atau kata keterangan keadaan bagi lafal yang diperkirakan keberadaannya, yaitu kaum yang dimaksud tadi (atau) mereka (menyerah) karena itu maka kalian tidak berperang lagi. (Maka jika kalian patuhi) ajakan untuk memerangi mereka itu (niscaya Allah akan memberikan kepada kalian pahala yang baik dan jika kalian berpaling sebagaimana kalian telah berpaling sebelumnya, niscaya Dia akan mengazab kalian dengan azab yang pedih\") azab yang menyakitkan.",[["قُل","Katakanlah"],["لِّلْمُخَلَّفِينَ","kepada mereka yang tertinggal"],["مِنَ","daripada"],["ٱلْأَعْرَابِ","orang Badwi"],["سَتُدْعَوْنَ","Kamu akan dipanggil"],["إِلَىٰ","kepada"],["قَوْمٍ","suatu kaum"],["أُو۟لِى","pemilik kekuatan tentera"],["بَأْسٍۢ","pemilik kekuatan tentera"],["شَدِيدٍۢ","yang besar"],["تُقَـٰتِلُونَهُمْ","kamu akan memerangi mereka"],["أَوْ","atau"],["يُسْلِمُونَ ۖ","mereka akan menyerahkan"],["فَإِن","Kemudian jika"],["تُطِيعُوا۟","kamu taat"],["يُؤْتِكُمُ","Allah akan berikan kamu"],["ٱللَّهُ","Allah akan berikan kamu"],["أَجْرًا","ganjaran"],["حَسَنًۭا ۖ","kebaikan"],["وَإِن","tetapi jika"],["تَتَوَلَّوْا۟","kamu berpaling"],["كَمَا","seperti"],["تَوَلَّيْتُم","kamu berpaling"],["مِّن","sebelum"],["قَبْلُ","sebelum"],["يُعَذِّبْكُمْ","Dia akan menghukum kamu"],["عَذَابًا","(dengan) hukuman"],["أَلِيمًۭا","yang pedih"]]],"4600":["(Tiada dosa atas orang-orang yang buta dan atas orang yang pincang dan atas orang yang sakit) apabila tidak ikut berjihad. (Dan barang siapa yang taat kepada Allah dan Rasul-Nya, niscaya Allah akan memasukkannya) dapat dibaca Yudkhilhu atau Nudkhilhu, kalau dibaca Nudkhilhu artinya, niscaya Kami akan memasukkannya (ke dalam surga yang mengalir di bawahnya sungai-sungai dan barang siapa yang berpaling niscaya akan diazab-Nya) dapat dibaca Yu'adzdzibhu atau Nu'adzdzibhu, kalau dibaca Nu'adzdzibhu artinya, niscaya Kami akan mengazabnya (dengan azab yang pedih.)",[["لَّيْسَ","bukan"],["عَلَى","ke atas"],["ٱلْأَعْمَىٰ","yang buta"],["حَرَجٌۭ","sebarang kesalahan"],["وَلَا","dan bukan"],["عَلَى","pada"],["ٱلْأَعْرَجِ","yang lumpuh"],["حَرَجٌۭ","sebarang kesalahan"],["وَلَا","dan bukan"],["عَلَى","pada"],["ٱلْمَرِيضِ","yang sakit"],["حَرَجٌۭ ۗ","sebarang kesalahan"],["وَمَن","Dan sesiapa"],["يُطِعِ","patuh"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["يُدْخِلْهُ","Dia akan mengakuinya"],["جَنَّـٰتٍۢ","(ke) Taman"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهَا","di bawah mereka"],["ٱلْأَنْهَـٰرُ ۖ","sungai-sungai"],["وَمَن","tetapi sesiapa sahaja"],["يَتَوَلَّ","berpaling"],["يُعَذِّبْهُ","Dia akan menghukumnya"],["عَذَابًا","(dengan) hukuman"],["أَلِيمًۭا","yang pedih"]]],"4601":["(Sesungguhnya Allah telah rida terhadap orang-orang mukmin ketika mereka berjanji setia kepadamu) di Hudaibiyah (di bawah pohon) yaitu pohon Samurah, jumlah mereka yang menyatakan baiat itu ada seribu tiga ratus orang atau lebih. Kemudian mereka berbaiat kepada Nabi saw. yaitu hendaknya mereka saling bahu-membahu melawan orang-orang Quraisy dan janganlah mereka lari karena takut mati (maka Dia mengetahui) yakni Allah mengetahui (apa yang ada dalam hati mereka) yaitu kejujuran dan kesetiaan mereka (lalu menurunkan ketenangan atas mereka dan memberi balasan kepada mereka dengan kemenangan yang dekat waktunya) yaitu takluknya tanah Khaibar sesudah mereka kembali dari Hudaibiyah.",[["۞ لَّقَدْ","Sungguh"],["رَضِىَ","Allah redha"],["ٱللَّهُ","Allah redha"],["عَنِ","dengan"],["ٱلْمُؤْمِنِينَ","orang yang beriman"],["إِذْ","apabila"],["يُبَايِعُونَكَ","mereka berjanji setia kepadamu"],["تَحْتَ","bawah"],["ٱلشَّجَرَةِ","pokok itu"],["فَعَلِمَ","dan Dia tahu"],["مَا","apa"],["فِى","(telah) masuk"],["قُلُوبِهِمْ","hati mereka"],["فَأَنزَلَ","maka Dia menurunkan"],["ٱلسَّكِينَةَ","ketenangan itu"],["عَلَيْهِمْ","ke atas mereka"],["وَأَثَـٰبَهُمْ","dan memberi ganjaran kepada mereka"],["فَتْحًۭا","(dengan) kemenangan"],["قَرِيبًۭا","dekat"]]],"4602":["(Serta harta rampasan yang banyak yang dapat mereka ambil) dari tanah Khaibar. (Dan adalah Allah Maha Perkasa lagi Maha Bijaksana) Dia terus-menerus bersifat demikian.",[["وَمَغَانِمَ","Dan harta rampasan perang"],["كَثِيرَةًۭ","banyak"],["يَأْخُذُونَهَا ۗ","yang akan mereka ambil"],["وَكَانَ","dan adalah"],["ٱللَّهُ","Allah"],["عَزِيزًا","Maha Perkasa"],["حَكِيمًۭا","Maha Bijaksana"]]],"4603":["(Allah menjanjikan kepada kalian harta rampasan yang banyak yang dapat kalian ambil) dari penaklukan-penaklukan (maka disegerakan-Nya harta rampasan ini untuk kalian) yang dimaksud adalah harta rampasan tanah Khaibar (dan Dia menahan tangan manusia dari kalian) yakni ulah mereka terhadap anak-anak dan istri-istri kalian sewaktu kalian berangkat berperang dan memang orang-orang Yahudi, sewaktu kalian keluar bermaksud untuk membinasakan mereka, akan tetapi Allah melemparkan ke dalam hati mereka rasa takut sehingga mereka tidak berani melakukannya (dan agar hal itu) yakni harta rampasan yang disegerakan itu; lafal ayat ini diathafkan kepada lafal yang diperkirakan keberadaannya; yaitu lafal Litasykuruuhu yang artinya, supaya kalian bersyukur kepada-Nya (menjadi bukti bagi orang-orang mukmin) yang menunjukkan bahwa mereka mendapat pertolongan dari Allah (dan agar Dia menunjuki kalian kepada jalan yang lurus) yakni jalan untuk bertawakal dan menyerahkan segala sesuatu kepada Allah swt.",[["وَعَدَكُمُ","Allah telah berjanji kepadamu"],["ٱللَّهُ","Allah telah berjanji kepadamu"],["مَغَانِمَ","harta rampasan perang"],["كَثِيرَةًۭ","banyak"],["تَأْخُذُونَهَا","bahawa kamu akan mengambilnya"],["فَعَجَّلَ","dan Dia telah bersegera"],["لَكُمْ","bagi kamu"],["هَـٰذِهِۦ","ini"],["وَكَفَّ","dan telah menahan"],["أَيْدِىَ","(the) tangan"],["ٱلنَّاسِ","(daripada) rakyat"],["عَنكُمْ","daripada kamu"],["وَلِتَكُونَ","bahawa ia mungkin"],["ءَايَةًۭ","satu tanda"],["لِّلْمُؤْمِنِينَ","untuk orang yang beriman"],["وَيَهْدِيَكُمْ","dan Dia boleh memberi petunjuk kepada kamu"],["صِرَٰطًۭا","(ke) Jalan"],["مُّسْتَقِيمًۭا","Lurus"]]],"4604":["(Dan harta-harta rampasan yang lain) lafal Ukhraa ini menjadi Sifat dari lafal yang diperkirakan keberadaannya yaitu Maghaanima yang berkedudukan menjadi Mubtada (yang kalian belum dapat menguasainya) yaitu harta rampasan dari negeri Persia dan negeri Romawi (yang sungguh Allah telah meliputinya) dengan ilmu-Nya bahwa semuanya kelak akan kalian raih. (Dan adalah Allah Maha Kuasa atas segala sesuatu) yakni Dia terus menerus bersifat demikian.",[["وَأُخْرَىٰ","Dan lain-lain"],["لَمْ","tidak"],["تَقْدِرُوا۟","kamu mempunyai kuasa"],["عَلَيْهَا","atas mereka"],["قَدْ","pasti"],["أَحَاطَ","Allah meliputi"],["ٱللَّهُ","Allah meliputi"],["بِهَا ۚ","mereka"],["وَكَانَ","dan adalah"],["ٱللَّهُ","Allah"],["عَلَىٰ","atas"],["كُلِّ","semua"],["شَىْءٍۢ","benda"],["قَدِيرًۭا","Maha Berkuasa"]]],"4605":["(Dan sekiranya orang-orang kafir itu memerangi kalian) sewaktu kalian di Hudaibiah (pastilah mereka berbalik melarikan diri ke belakang, kemudian mereka tiada memperoleh pelindung) yang dapat memelihara dan menjaga mereka (dan tidak pula penolong.)",[["وَلَوْ","Dan jika"],["قَـٰتَلَكُمُ","lawan kamu"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لَوَلَّوُا۟","nescaya mereka akan berpaling"],["ٱلْأَدْبَـٰرَ","bahagian belakang"],["ثُمَّ","Kemudian"],["لَا","tidak"],["يَجِدُونَ","mereka akan dapati"],["وَلِيًّۭا","mana-mana pelindung"],["وَلَا","dan bukan"],["نَصِيرًۭا","mana-mana pembantu"]]],"4606":["(Sebagai suatu sunatullah) lafal ayat ini adalah Mashdar yang berfungsi mengukuhkan makna jumlah kalimat sebelumnya, yaitu mengenai kalahnya orang-orang kafir dan ditolong-Nya orang-orang mukmin. Maksudnya yang demikian itu merupakan suatu sunatullah (yang telah berlaku sejak dahulu, kamu sekali-kali tidak akan menemukan perubahan bagi sunatullah itu) sebagai ganti darinya.",[["سُنَّةَ","(Cara yang ditetapkan)."],["ٱللَّهِ","(milik) Allah"],["ٱلَّتِى","yang"],["قَدْ","meninggal dunia"],["خَلَتْ","meninggal dunia"],["مِن","sebelum"],["قَبْلُ ۖ","sebelum"],["وَلَن","dan tidak pernah"],["تَجِدَ","kamu akan dapati"],["لِسُنَّةِ","di (jalan) Allah"],["ٱللَّهِ","di (jalan) Allah"],["تَبْدِيلًۭا","sebarang perubahan"]]],"4607":["(Dan Dialah yang menahan tangan mereka dari kalian dan tangan kalian dari mereka di lembah Mekah) yakni di Hudaibiah (sesudah Allah memenangkan kalian atas mereka) karena sesungguhnya delapan puluh orang lelaki dari kalangan mereka mengelilingi perkemahan kalian dengan tujuan untuk menyergap kalian, tetapi akhirnya mereka dapat dilumpuhkan dan mereka dihadapkan kepada Rasulullah saw. maka ia memberi maaf kepada mereka lalu dilepaskannya mereka dengan bebas. Hal ini merupakan penyebab adanya perjanjian gencatan senjata (dan adalah Allah Maha Melihat apa yang kalian kerjakan.) Lafal Ta'maluuna dapat dibaca Ya'maluuna, kalau dibaca Ya'maluuna maka artinya, \"Dan adalah Allah Maha Melihat apa yang mereka kerjakan.\" Maksud ungkapan ayat ini ialah bahwa Allah masih tetap bersifat demikian.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["كَفَّ","ditahan"],["أَيْدِيَهُمْ","tangan mereka"],["عَنكُمْ","daripada kamu"],["وَأَيْدِيَكُمْ","dan tangan kamu"],["عَنْهُم","daripada mereka"],["بِبَطْنِ","dalam"],["مَكَّةَ","Makkah"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["أَنْ","bahawa"],["أَظْفَرَكُمْ","Dia memberi kamu kemenangan"],["عَلَيْهِمْ ۚ","atas mereka"],["وَكَانَ","Dan adakah"],["ٱللَّهُ","Allah"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["بَصِيرًا","Maha Melihat"]]],"4608":["(Merekalah orang-orang yang kafir yang menghalangi kalian dari Masjidilharam) yakni menghalangi kalian untuk memasukinya (dan hewan kurban) diathafkan kepada Dhamir Kum yang ada pada lafal Washadduukum (dalam keadaan tertahan) yakni terhenti, lafal ini menjadi Hal atau kata keterangan keadaan (tidak dapat mencapai tempatnya) yaitu tempat penyembelihannya sebagaimana biasanya, lafal ayat ini berkedudukan menjadi Badal Isytimal. (Dan kalau tidaklah karena laki-laki yang mukmin dan perempuan-perempuan yang mukmin) yang masih ada tinggal bersama dengan orang-orang kafir di Mekah (yang tiada kalian ketahui) keimanan mereka (bahwa kalian akan membunuh mereka) kalian akan membunuh mereka bersama dengan orang-orang kafir, sekiranya kalian diizinkan-Nya untuk melakukan penaklukan. Lafal ayat ini menjadi Badal Isytimal dari Dhamir Hum yang terdapat pada lafal Lam Ta'lamuuhum (yang menyebabkan kalian berdosa) yakni perbuatan yang berdosa (tanpa pengetahuan) kalian tentangnya. Semua Dhamir Ghaibah yang ada menunjukkan makna untuk kedua jenis, yaitu jenis lelaki dan perempuan, hal tersebut hanya memprioritaskan Mudzakkar. Jawab dari lafal Laulaa tidak disebutkan, yakni tentulah Allah mengizinkan kalian untuk melakukan penaklukan, tetapi ketika itu Dia ternyata tidak mengizinkan kalian melakukan hal itu. (Supaya Allah memasukkan siapa yang dikehendaki-Nya ke dalam rahmat-Nya) seperti orang-orang mukmin yang telah disebutkan tadi. (Sekiranya mereka tidak bercampur-baur) seandainya mereka membedakan dari orang-orang kafir (tentulah Kami akan mengazab orang-orang kafir di antara mereka) yakni di antara penduduk Mekah pada saat itu juga, seumpamanya Kami memberikan izin kepada kalian untuk melakukan penaklukan (dengan azab yang pedih) azab yang menyakitkan.",[["هُمُ","mereka"],["ٱلَّذِينَ","(adalah) mereka yang"],["كَفَرُوا۟","kufur"],["وَصَدُّوكُمْ","dan menghalang kamu"],["عَنِ","daripada"],["ٱلْمَسْجِدِ","Al-Masjid Al-Haraam"],["ٱلْحَرَامِ","Al-Masjid Al-Haraam"],["وَٱلْهَدْىَ","manakala persembahan"],["مَعْكُوفًا","(telah) dihalang"],["أَن","daripada"],["يَبْلُغَ","mencapai"],["مَحِلَّهُۥ ۚ","tempatnya (berkorban)"],["وَلَوْلَا","Dan jika tidak"],["رِجَالٌۭ","(untuk) lelaki"],["مُّؤْمِنُونَ","beriman"],["وَنِسَآءٌۭ","dan wanita"],["مُّؤْمِنَـٰتٌۭ","beriman"],["لَّمْ","tidak"],["تَعْلَمُوهُمْ","kamu mengenali mereka"],["أَن","bahawa"],["تَطَـُٔوهُمْ","kamu boleh memijak mereka"],["فَتُصِيبَكُم","dan akan menimpa kamu"],["مِّنْهُم","daripada mereka"],["مَّعَرَّةٌۢ","sebarang kemudaratan"],["بِغَيْرِ","tanpa"],["عِلْمٍۢ ۖ","pengetahuan"],["لِّيُدْخِلَ","Supaya Allah mengaku"],["ٱللَّهُ","Supaya Allah mengaku"],["فِى","kepada"],["رَحْمَتِهِۦ","KerahimanNya"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["لَوْ","Jika"],["تَزَيَّلُوا۟","mereka telah terpisah"],["لَعَذَّبْنَا","sesungguhnya Kami akan mengazab"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مِنْهُمْ","antara mereka"],["عَذَابًا","(dengan) hukuman"],["أَلِيمًا","yang pedih"]]],"4609":["(Ketika menanamkan) berta'alluq kepada lafal La'adzdzabnaa (orang-orang kafir itu) menjadi Fa'il dari lafal Ja'ala (ke dalam hati mereka kesombongan) perasaan tinggi diri dari sesuatu (yaitu kesombongan jahiliah) menjadi Badal dari lafal Hamiyah. Makna yang dimaksud ialah hambatan dan cegahan mereka terhadap Nabi dan para sahabatnya untuk mencapai Masjidilharam (lalu Allah menurunkan ketenangan kepada Rasul-Nya dan kepada orang-orang mukmin) lalu akhirnya Nabi saw. dan para sahabatnya mengadakan perdamaian dengan mereka, yaitu hendaknya mereka diperbolehkan kembali ke Mekah tahun depan dan ternyata mereka tidak terbakar atau terpancing oleh panasnya perasaan, tidak sebagaimana yang menimpa orang-orang kafir, akhirnya peperangan antara mereka terhindarkan (dan Allah mewajibkan kepada mereka) yakni kepada orang-orang mukmin (kalimat takwa) yaitu \"Tiada Tuhan selain Allah dan Muhammad utusan Allah\", kalimat ini dikaitkan dengan takwa, karena merupakan penyebabnya (dan adalah mereka lebih berhak dengannya) yakni dengan kalimat takwa itu daripada orang-orang kafir (dan patut memilikinya) merupakan Athaf Tafsir. (Dan adalah Allah Maha Mengetahui segala sesuatu) artinya Dia tetap bersifat demikian, dan di antara apa yang diketahui oleh Allah swt. ialah bahwa orang-orang mukmin itu berhak memiliki kalimat takwa itu.",[["إِذْ","Apabila"],["جَعَلَ","telah meletakkan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["فِى","dalam"],["قُلُوبِهِمُ","hati mereka"],["ٱلْحَمِيَّةَ","penghinaan"],["حَمِيَّةَ","(yang) penghinaan"],["ٱلْجَـٰهِلِيَّةِ","(pada masa) kejahilan"],["فَأَنزَلَ","Kemudian Allah menurunkan"],["ٱللَّهُ","Kemudian Allah menurunkan"],["سَكِينَتَهُۥ","ketenangannya"],["عَلَىٰ","ke atas"],["رَسُولِهِۦ","RasulNya"],["وَعَلَى","dan seterusnya"],["ٱلْمُؤْمِنِينَ","orang yang beriman"],["وَأَلْزَمَهُمْ","dan membuat mereka mematuhi"],["كَلِمَةَ","(kepada) perkataan"],["ٱلتَّقْوَىٰ","(dari) kebenaran"],["وَكَانُوٓا۟","dan mereka"],["أَحَقَّ","lebih layak"],["بِهَا","daripadanya"],["وَأَهْلَهَا ۚ","dan layak untuknya"],["وَكَانَ","Dan adakah"],["ٱللَّهُ","Allah"],["بِكُلِّ","daripada setiap"],["شَىْءٍ","perkara"],["عَلِيمًۭا","Maha Mengetahui"]]],"4610":["(Sesungguhnya Allah akan membuktikan kepada Rasul-Nya tentang kebenaran mimpinya dengan sebenarnya) Rasulullah saw. bermimpi pada tahun terjadinya perjanjian Hudaibiah, yaitu sebelum beliau berangkat menuju ke Hudaibiah, bahwasanya ia memasuki kota Mekah bersama-sama dengan para sahabatnya dalam keadaan aman hingga mereka dapat bercukur dan ada pula yang hanya memendekkan rambutnya. Kemudian Rasulullah saw. menceritakan hal mimpinya itu kepada para sahabatnya, maka mereka sangat gembira mendengarnya. Ketika para sahabat berangkat bersama Rasulullah menuju Mekah, tiba-tiba mereka dihalang-halangi oleh orang-orang kafir sewaktu mereka sampai di Hudaibiah. Akhirnya mereka kembali ke Madinah dengan perasaan yang berat, pada saat itu timbullah rasa keraguan di dalam hati sebagian orang-orang munafik, lalu turunlah ayat ini. Firman-Nya, \"Bil haqqi\" berta'alluq kepada lafal Shadaqa, atau merupakan Hal atau kata keterangan keadaan dari lafal Ar-Ru'yaa sedangkan kalimat sesudahnya berfungsi menjadi penafsirnya (yaitu bahwa sesungguhnya kamu sekalian pasti akan memasuki Masjidilharam, insya Allah) lafal Insya Allah artinya, jika Allah menghendaki, hanyalah sebagai kalimat Tabarruk saja, yaitu untuk meminta keberkahan (dalam keadaan aman dengan mencukur rambut kepala) mencukur semua rambut kepala (dan mengguntingnya) yakni menggunting sebagiannya saja; kedua lafal ini merupakan Hal bagi lafal yang diperkirakan keberadaannya (sedangkan kalian tidak merasa takut) selama-lamanya (Maka Allah mengetahui) di dalam perjanjian damai itu (apa yang tidak kalian ketahui) mengenai kemaslahatan yang terkandung di dalamnya (dan Dia memberikan sebelum itu) sebelum kalian memasuki Mekah (kemenangan yang dekat) yaitu ditaklukkannya tanah Khaibar, kemudian mimpi itu menjadi kenyataan pada tahun berikutnya.",[["لَّقَدْ","Sungguh"],["صَدَقَ","Allah dah tunaikan"],["ٱللَّهُ","Allah dah tunaikan"],["رَسُولَهُ","RasulNya"],["ٱلرُّءْيَا","penglihatan"],["بِٱلْحَقِّ ۖ","dalam kebenaran"],["لَتَدْخُلُنَّ","Pasti, kamu akan masuk"],["ٱلْمَسْجِدَ","Al-Masjid Al-Haraam"],["ٱلْحَرَامَ","Al-Masjid Al-Haraam"],["إِن","jika"],["شَآءَ","Allah berkehendak"],["ٱللَّهُ","Allah berkehendak"],["ءَامِنِينَ","selamat"],["مُحَلِّقِينَ","setelah bercukur"],["رُءُوسَكُمْ","kepala kamu"],["وَمُقَصِّرِينَ","dan dipendekkan"],["لَا","tidak"],["تَخَافُونَ ۖ","takut"],["فَعَلِمَ","Tetapi Dia tahu"],["مَا","apa"],["لَمْ","tidak"],["تَعْلَمُوا۟","kamu tahu"],["فَجَعَلَ","dan Dia menjadikan"],["مِن","selain"],["دُونِ","selain"],["ذَٰلِكَ","bahawa"],["فَتْحًۭا","sebuah kemenangan"],["قَرِيبًا","dekat"]]],"4611":["(Dialah yang mengutus Rasul-Nya dengan membawa petunjuk dan agama yang hak agar dimenangkan-Nya) agama yang hak itu (terhadap semua agama) atas agama-agama yang lainnya. (Dan cukuplah Allah sebagai saksi) bahwasanya kamu diutus untuk membawa hal tersebut, sebagaimana yang diungkapkan-Nya pada ayat berikut ini.",[["هُوَ","Dia"],["ٱلَّذِىٓ","(ialah) Yang"],["أَرْسَلَ","(telah) menghantar"],["رَسُولَهُۥ","RasulNya"],["بِٱلْهُدَىٰ","dengan bimbingan"],["وَدِينِ","dan (agama) itu"],["ٱلْحَقِّ","yang benar"],["لِيُظْهِرَهُۥ","supaya Dia (boleh) menjadikannya menang"],["عَلَى","atas"],["ٱلدِّينِ","agama-agama"],["كُلِّهِۦ ۚ","semua"],["وَكَفَىٰ","Dan cukuplah"],["بِٱللَّهِ","Allah"],["شَهِيدًۭا","(sebagai) seorang Saksi"]]],"4612":["(Muhammad itu) lafal ayat ini berkedudukan menjadi Mubtada (adalah utusan Allah) menjadi Khabar dari Mubtada (dan orang-orang yang bersama dengan dia) yakni para sahabatnya yang terdiri dari kaum mukminin. Lafal ayat ini menjadi Mubtada sedangkan Khabarnya ialah (adalah keras) yakni mereka adalah orang-orang yang bersikap keras (terhadap orang-orang kafir) mereka tidak mengasihaninya (tetapi berkasih sayang sesama mereka) menjadi Khabar yang kedua; yakni mereka saling kasih-mengasihi di antara sesama mukmin bagaikan kasih orang tua kepada anaknya (kamu lihat mereka) kamu perhatikan mereka (rukuk dan sujud) keduanya merupakan Hal atau kata keterangan keadaan (mencari) lafal ayat ini merupakan jumlah Isti`naf, yakni mereka melakukan demikian dalam rangka mencari (karunia Allah dan keridaan-Nya, tanda-tanda mereka) ciri-ciri mereka, lafal ayat ini menjadi Mubtada (tampak pada muka mereka) menjadi Khabar dari Mubtada. Tanda-tanda tersebut berupa nur dan sinar yang putih bersih yang menjadi ciri khas mereka kelak di akhirat, sebagai pertanda bahwa mereka orang-orang yang gemar bersujud sewaktu di dunia (dari bekas sujud.) Lafal ayat ini berta'alluq kepada lafal yang menjadi Ta'alluq atau gantungan bagi Khabar, yaitu lafal Kaainatan. Kemudian dii'rabkan sebagai Hal karena mengingat Dhamirnya yang dipindahkan kepada Khabar. (Demikianlah) sifat-sifat yang telah disebutkan tadi (sifat-sifat mereka) yakni gambaran tentang mereka, kalimat ayat ini menjadi Mubtada (di dalam kitab Taurat) menjadi Khabarnya (dan sifat-sifat mereka dalam kitab Injil) menjadi Mubtada, sedangkan Khabarnya adalah (yaitu seperti tanaman yang mengeluarkan tunasnya) dapat dibaca Syath`ahu atau Syatha`ahu, yakni tunasnya (maka tunas itu menjadikan tanaman itu kuat) dapat dibaca Fa`aazarahuu atau Fa`azarahu, yakni tunas itu membuat tanaman menjadi kuat (lalu menjadi besarlah dia) membesarlah dia (dan tegak lurus) yakni kuat dan tegak lurus (di atas pokoknya) lafal Suuq ini adalah bentuk jamak dari lafal Saaqun (tanaman itu menyenangkan hati penanam-penanamnya) karena keindahannya. Perumpamaan ini merupakan gambaran tentang keadaan para sahabat karena mereka pada mulanya berjumlah sedikit lagi masih lemah, kemudian jumlah mereka makin bertambah banyak dan bertambah kuat dengan sistem yang sangat rapi (karena Allah hendak menjengkelkan hati orang-orang kafir dengan kekuatan orang-orang mukmin) lafal ayat ini berta'alluq kepada lafal yang tidak disebutkan yang disimpulkan dari kalimat sebelumnya, yakni mereka diserupakan demikian karena Allah hendak menjengkelkan hati orang-orang kafir (Allah menjanjikan kepada orang-orang yang beriman dan mengerjakan amal yang saleh dari kalangan mereka) yakni para sahabat; huruf Min di sini menunjukkan makna Bayanul Jinsi atau untuk menjelaskan jenis, bukan untuk menunjukkan makna Tab'idh atau sebagian, demikian itu karena para sahabat semuanya memiliki sifat-sifat tersebut (ampunan dan pahala yang besar) yakni surga; kedua pahala itu berlaku pula bagi orang-orang sesudah mereka, sebagaimana yang telah dijelaskan dalam berbagai ayat lainnya",[["مُّحَمَّدٌۭ","Muhammad"],["رَّسُولُ","(ialah) Rasul"],["ٱللَّهِ ۚ","daripada Allah"],["وَٱلَّذِينَ","dan orang yang"],["مَعَهُۥٓ","(ada) bersamanya"],["أَشِدَّآءُ","(adalah) tegas"],["عَلَى","terhadap"],["ٱلْكُفَّارِ","orang kafir"],["رُحَمَآءُ","dan penyayang"],["بَيْنَهُمْ ۖ","sesama mereka"],["تَرَىٰهُمْ","Kamu melihat mereka"],["رُكَّعًۭا","tunduk"],["سُجَّدًۭا","dan sujud"],["يَبْتَغُونَ","mencari"],["فَضْلًۭا","Bounty"],["مِّنَ","daripada Allah"],["ٱللَّهِ","daripada Allah"],["وَرِضْوَٰنًۭا ۖ","dan kesenangan"],["سِيمَاهُمْ","Tanda mereka"],["فِى","(berada) di atas"],["وُجُوهِهِم","muka mereka"],["مِّنْ","daripada"],["أَثَرِ","(yang) jejak"],["ٱلسُّجُودِ ۚ","(dari) sujud"],["ذَٰلِكَ","Itu"],["مَثَلُهُمْ","(adalah) persamaan mereka"],["فِى","dalam"],["ٱلتَّوْرَىٰةِ ۚ","Taurah"],["وَمَثَلُهُمْ","Dan persamaan mereka"],["فِى","dalam"],["ٱلْإِنجِيلِ","Injeel"],["كَزَرْعٍ","(ialah) seperti biji benih"],["أَخْرَجَ","(yang) menghantar"],["شَطْـَٔهُۥ","pucuknya"],["فَـَٔازَرَهُۥ","kemudian menguatkannya"],["فَٱسْتَغْلَظَ","kemudian ia menjadi tebal"],["فَٱسْتَوَىٰ","dan ia berdiri"],["عَلَىٰ","ke atas"],["سُوقِهِۦ","batangnya"],["يُعْجِبُ","menggembirakan"],["ٱلزُّرَّاعَ","para penabur"],["لِيَغِيظَ","supaya Dia (boleh) murka"],["بِهِمُ","oleh mereka"],["ٱلْكُفَّارَ ۗ","orang kafir"],["وَعَدَ","Allah dah janji"],["ٱللَّهُ","Allah dah janji"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["مِنْهُم","antara mereka"],["مَّغْفِرَةًۭ","pengampunan"],["وَأَجْرًا","dan ganjaran"],["عَظِيمًۢا","yang besar"]]],"4613":["(Hai orang-orang yang beriman, janganlah kalian mendahului) berasal dari lafal Qadima yang maknanya sama dengan lafal Taqaddama artinya, janganlah kalian mendahului baik melalui perkataan atau perbuatan kalian (di hadapan Allah dan Rasul-Nya) yang menyampaikan wahyu dari-Nya, makna yang dimaksud ialah janganlah kalian mendahului Allah dan Rasul-Nya tanpa izin dari keduanya (dan bertakwalah kepada Allah. Sesungguhnya Allah Maha Mendengar) semua perkataan kalian (lagi Maha Mengetahui) semua perbuatan kalian. Ayat ini diturunkan berkenaan dengan perdebatan antara Abu Bakar r.a., dan sahabat Umar r.a. Mereka berdua melakukan perdebatan di hadapan Nabi saw. mengenai pengangkatan Aqra' bin Habis atau Qa'qa' bin Ma'bad. Ayat selanjutnya diturunkan berkenaan dengan orang yang mengangkat suaranya keras-keras di hadapan Nabi saw. yaitu firman-Nya:",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["لَا","Jangan"],["تُقَدِّمُوا۟","meletakkan (diri kamu) ke hadapan"],["بَيْنَ","di hadapan Allah"],["يَدَىِ","di hadapan Allah"],["ٱللَّهِ","di hadapan Allah"],["وَرَسُولِهِۦ ۖ","dan Rasul-Nya"],["وَٱتَّقُوا۟","dan takutlah kepada Allah"],["ٱللَّهَ ۚ","dan takutlah kepada Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["سَمِيعٌ","(adalah) Yang Maha Mendengar"],["عَلِيمٌۭ","Maha Mengetahui"]]],"4614":["(\"Hai orang-orang beriman janganlah kalian meninggikan suara kalian) bila kalian berbicara (lebih dari suara Nabi) bila ia berbicara (dan janganlah kalian berkata kepadanya dengan suara keras) bila kalian berbicara dengannya (sebagaimana kerasnya suara sebagian kalian terhadap sebagian yang lain) tetapi rendahkanlah suara kalian di bawah suaranya demi untuk menghormati dan mengagungkannya (supaya tidak dihapus pahala amal kalian sedangkan kalian tidak menyadarinya\") maksudnya, takutlah kalian akan hal tersebut disebabkan suara kalian yang tinggi dan keras di hadapannya. Ayat berikutnya diturunkan berkenaan dengan orang-orang yang merendahkan suaranya di hadapan Nabi saw.",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["لَا","Jangan"],["تَرْفَعُوٓا۟","menaikkan"],["أَصْوَٰتَكُمْ","suara kamu"],["فَوْقَ","di atas"],["صَوْتِ","(suara)."],["ٱلنَّبِىِّ","(dari) Nabi"],["وَلَا","dan jangan"],["تَجْهَرُوا۟","bersuara"],["لَهُۥ","kepadanya"],["بِٱلْقَوْلِ","dalam ucapan"],["كَجَهْرِ","seperti (kenyaringan)."],["بَعْضِكُمْ","(dari) sebahagian kamu"],["لِبَعْضٍ","kepada orang lain"],["أَن","jangan-jangan"],["تَحْبَطَ","menjadi tidak bernilai"],["أَعْمَـٰلُكُمْ","perbuatan kamu"],["وَأَنتُمْ","sedangkan kamu"],["لَا","jangan"],["تَشْعُرُونَ","mempersepsikan"]]],"4615":["(\"Sesungguhnya orang-orang yang merendahkan suaranya di sisi Rasulullah, mereka itulah orang-orang yang telah diuji) dicoba (hati mereka oleh Allah untuk bertakwa) artinya, ujian untuk menampakkan ketakwaan mereka. (Bagi mereka ampunan dan pahala yang besar\") yakni surga. Ayat berikutnya diturunkan berkenaan dengan orang-orang yang datang di waktu tengah hari kepada Nabi saw. sedangkan Nabi saw. pada saat itu berada di dalam rumahnya, lalu mereka memanggil-manggilnya, yaitu firman-Nya:",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يَغُضُّونَ","lebih rendah"],["أَصْوَٰتَهُمْ","suara mereka"],["عِندَ","(dalam) kehadiran"],["رَسُولِ","(dari) Rasulullah"],["ٱللَّهِ","(dari) Rasulullah"],["أُو۟لَـٰٓئِكَ","mereka"],["ٱلَّذِينَ","(adalah) mereka"],["ٱمْتَحَنَ","Allah dah uji"],["ٱللَّهُ","Allah dah uji"],["قُلُوبَهُمْ","hati mereka"],["لِلتَّقْوَىٰ ۚ","untuk kebenaran"],["لَهُم","Untuk mereka"],["مَّغْفِرَةٌۭ","(ialah) pengampunan"],["وَأَجْرٌ","dan ganjaran"],["عَظِيمٌ","yang besar"]]],"4616":["(\"Sesungguhnya orang-orang yang memanggil kamu dari luar kamar) yakni dari luar kamar istri-istrinya. Lafal Hujuraat bentuk jamak dari lafal Hujratun, yang artinya; sepetak tanah yang dikelilingi oleh tembok atau lainnya, yang digunakan sebagai tempat tinggal. Masing-masing di antara mereka memanggil Nabi saw. dari belakang kamar-kamarnya, karena mereka tidak mengetahui di kamar manakah Nabi saw. berada. Mereka memanggilnya dengan suara yang biasa dilakukan oleh orang-orang Arab Badui, yaitu dengan suara yang keras dan kasar (kebanyakan mereka tidak mengerti) tentang apa yang harus mereka kerjakan di dalam menghadapi kedudukanmu yang tinggi, dan sikap penghormatan manakah yang pantas mereka lakukan untukmu.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يُنَادُونَكَ","panggil kamu"],["مِن","daripada"],["وَرَآءِ","belakang"],["ٱلْحُجُرَٰتِ","bilik persendirian"],["أَكْثَرُهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْقِلُونَ","faham"]]],"4617":["(Dan kalau sekiranya mereka bersabar) lafal Annahum berada dalam Mahall Rafa' sebagai Mubtada. Tetapi menurut pendapat lain menjadi Fa'il dari Fi'il yang diperkirakan keberadaannya, yaitu lafal Tsabata (sampai kamu keluar menemui mereka, sesungguhnya itu adalah lebih baik bagi mereka, dan Allah Maha Pengampun lagi Maha Penyayang\") kepada orang yang bertobat di antara mereka. Ayat berikut ini diturunkan berkenaan dengan Walid bin Uqbah. Ia telah diutus oleh Nabi saw. ke Bani Mushthaliq untuk menarik zakat, tetapi ia merasa takut terhadap mereka, karena dahulu di masa jahiliah ia bermusuhan dengan mereka. Akhirnya di tengah perjalanan ia kembali lagi seraya melaporkan, bahwa mereka tidak mau membayar zakat dan bahkan mereka hampir saja membunuhnya. Karena itu hampir saja Nabi saw. bermaksud untuk memerangi mereka, hanya karena mereka keburu datang menghadap Nabi saw. seraya mengingkari apa yang telah dikatakan oleh Walid mengenai mereka.",[["وَلَوْ","Dan jika"],["أَنَّهُمْ","mereka"],["صَبَرُوا۟","telah bersabar"],["حَتَّىٰ","sehingga"],["تَخْرُجَ","kamu keluar"],["إِلَيْهِمْ","kepada mereka"],["لَكَانَ","sudah tentu ia akan menjadi"],["خَيْرًۭا","lebih baik"],["لَّهُمْ ۚ","bagi mereka"],["وَٱللَّهُ","Dan Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"4618":["(Hai orang-orang yang beriman! Jika datang kepada kalian orang fasik membawa suatu berita) (maka periksalah oleh kalian) kebenaran beritanya itu, apakah ia benar atau berdusta. Menurut suatu qiraat dibaca Fatatsabbatuu berasal dari lafal Ats-Tsabaat, artinya telitilah terlebih dahulu kebenarannya (agar kalian tidak menimpakan musibah kepada suatu kaum) menjadi Maf'ul dari lafal Fatabayyanuu, yakni dikhawatirkan hal tersebut akan menimpa musibah kepada suatu kaum (tanpa mengetahui keadaannya) menjadi Hal atau kata keterangan keadaan dari Fa'il, yakni tanpa sepengetahuannya (yang menyebabkan kalian) membuat kalian (atas perbuatan kalian itu) yakni berbuat kekeliruan terhadap kaum tersebut (menyesal) selanjutnya Rasulullah saw. mengutus Khalid kepada mereka sesudah mereka kembali ke negerinya. Ternyata Khalid tiada menjumpai mereka melainkan hanya ketaatan dan kebaikan belaka, lalu ia menceritakan hal tersebut kepada Nabi saw.",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوٓا۟","Wahai orang yang beriman"],["إِن","Jika"],["جَآءَكُمْ","datang kepada kamu"],["فَاسِقٌۢ","seorang yang jahat"],["بِنَبَإٍۢ","dengan maklumat"],["فَتَبَيَّنُوٓا۟","menyiasat"],["أَن","jangan-jangan"],["تُصِيبُوا۟","kamu membahayakan"],["قَوْمًۢا","suatu kaum"],["بِجَهَـٰلَةٍۢ","dalam kejahilan"],["فَتُصْبِحُوا۟","maka kamu menjadi"],["عَلَىٰ","atas"],["مَا","apa"],["فَعَلْتُمْ","kamu telah lakukan"],["نَـٰدِمِينَ","menyesal"]]],"4619":["(Dan ketahuilah oleh kamu sekalian bahwa di kalangan kalian ada Rasulullah) maka janganlah sekali-kali kalian mengatakan hal-hal yang batil, karena sesungguhnya Allah akan memberitahukannya seketika itu juga. (Kalau ia menuruti kemauan kalian dalam banyak urusan) yang kalian beritakan tidak sesuai dengan kenyataannya, oleh karena itu maka hasilnya sesuai dengan apa yang kalian beritakan itu (niscaya kalian akan mendapat dosa) yakni benar-benar kalian mendapat dosa karena hal itu, yaitu dosa memberikan keterangan yang palsu (tetapi Allah menjadikan kalian cinta kepada keimanan dan menjadikan iman itu indah) yakni dipandang baik (dalam hati kalian serta menjadikan kalian benci kepada kekafiran, kefasikan dan kedurhakaan) pengertian Istidrak yang dikandung oleh lafal Laakin dipandang dari segi makna bukan lafalnya, karena sesungguhnya orang yang cinta kepada keimanan memiliki sifat-sifat berbeda dengan sifat-sifat yang dimiliki oleh orang-orang yang telah disebutkan tadi. (Mereka itulah) di dalam ungkapan ini terkandung iltifat dari Mukhathab (orang-orang yang mengikuti jalan yang lurus) yakni orang-orang yang teguh dalam agamanya.",[["وَٱعْلَمُوٓا۟","Dan tahu"],["أَنَّ","bahawa"],["فِيكُمْ","antara kamu"],["رَسُولَ","(ialah) Rasulullah"],["ٱللَّهِ ۚ","(ialah) Rasulullah"],["لَوْ","Jika"],["يُطِيعُكُمْ","dia harus mematuhi kamu"],["فِى","dalam"],["كَثِيرٍۢ","banyak"],["مِّنَ","daripada"],["ٱلْأَمْرِ","perkara itu"],["لَعَنِتُّمْ","nescaya kamu akan berada dalam kesukaran"],["وَلَـٰكِنَّ","tetapi"],["ٱللَّهَ","Allah"],["حَبَّبَ","telah disayangi"],["إِلَيْكُمُ","kepada kamu"],["ٱلْإِيمَـٰنَ","Iman"],["وَزَيَّنَهُۥ","dan telah menjadikannya menyenangkan"],["فِى","dalam"],["قُلُوبِكُمْ","hati kamu"],["وَكَرَّهَ","dan telah membuat kebencian"],["إِلَيْكُمُ","kepada kamu"],["ٱلْكُفْرَ","ketidakpercayaan"],["وَٱلْفُسُوقَ","dan penentangan"],["وَٱلْعِصْيَانَ ۚ","dan kemaksiatan"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["هُمُ","(adalah) mereka"],["ٱلرَّٰشِدُونَ","mereka yang mendapat petunjuk"]]],"4620":["(Sebagai karunia dari Allah) lafal Fadhlan adalah Mashdar yang dinashabkan oleh Fi'ilnya yang keberadaannya diperkirakan sebelumnya, yaitu lafal Afdhala (dan nikmat) dari-Nya. (Dan Allah Maha Mengetahui) keadaan mereka (lagi Maha Bijaksana) di dalam memberikan nikmat-Nya kepada mereka.",[["فَضْلًۭا","Sebuah Bounty"],["مِّنَ","daripada Allah"],["ٱللَّهِ","daripada Allah"],["وَنِعْمَةًۭ ۚ","dan nikmat"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌ","Maha Mengetahui"],["حَكِيمٌۭ","Maha Bijaksana"]]],"4621":["(Dan jika ada dua golongan dari orang-orang mukmin) hingga akhir ayat. Ayat ini diturunkan berkenaan dengan suatu masalah, yaitu bahwa Nabi saw. pada suatu hari menaiki keledai kendaraannya, lalu ia melewati Ibnu Ubay. Ketika melewatinya tiba-tiba keledai yang dinaikinya itu kencing, lalu Ibnu Ubay menutup hidungnya, maka berkatalah Ibnu Rawwahah kepadanya, \"Demi Allah, sungguh bau kencing keledainya jauh lebih wangi daripada bau minyak kesturimu itu,\" maka terjadilah antara kaum mereka berdua saling baku hantam dengan tangan, terompah dan pelepah kurma (berperang) Dhamir yang ada pada ayat ini dijamakkan karena memandang dari segi makna yang dikandung lafal Thaaifataani, karena masing-masing Thaaifah atau golongan terdiri dari sekelompok orang. Menurut suatu qiraat ada pula yang membacanya Iqtatalataa, yakni hanya memandang dari segi lafal saja (maka damaikanlah antara keduanya) dan Dhamir pada lafal ini ditatsniyahkan karena memandang dari segi lafal. (Jika berbuat aniaya) atau berbuat melewati batas (salah satu dari kedua golongan itu terhadap golongan yang lain maka perangilah golongan yang berbuat aniaya itu sehingga golongan itu kembali) artinya, rujuk kembali (kepada perintah Allah) kepada jalan yang benar (jika golongan itu telah kembali kepada perintah Allah maka damaikanlah antara keduanya dengan adil) yaitu dengan cara pertengahan (dan berlaku adillah) bersikap jangan memihaklah. (Sesungguhnya Allah menyukai orang-orang yang berlaku adil.)",[["وَإِن","Dan jika"],["طَآئِفَتَانِ","dua pihak"],["مِنَ","antara"],["ٱلْمُؤْمِنِينَ","orang yang beriman"],["ٱقْتَتَلُوا۟","bergaduh"],["فَأَصْلِحُوا۟","kemudian berdamai"],["بَيْنَهُمَا ۖ","antara mereka berdua"],["فَإِنۢ","Tetapi jika"],["بَغَتْ","menindas"],["إِحْدَىٰهُمَا","salah seorang daripada mereka"],["عَلَى","pada"],["ٱلْأُخْرَىٰ","yang lain"],["فَقَـٰتِلُوا۟","kemudian bergaduh"],["ٱلَّتِى","satu yang"],["تَبْغِى","menindas"],["حَتَّىٰ","sehingga"],["تَفِىٓءَ","ia kembali"],["إِلَىٰٓ","kepada"],["أَمْرِ","(perintah)."],["ٱللَّهِ ۚ","(milik) Allah"],["فَإِن","Kemudian jika"],["فَآءَتْ","ia kembali"],["فَأَصْلِحُوا۟","kemudian berdamai"],["بَيْنَهُمَا","antara mereka"],["بِٱلْعَدْلِ","dengan keadilan"],["وَأَقْسِطُوٓا۟ ۖ","dan berlaku adil"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يُحِبُّ","suka"],["ٱلْمُقْسِطِينَ","mereka yang berlaku adil"]]],"4622":["(Sesungguhnya orang-orang mukmin adalah saudara) dalam seagama (karena itu damaikanlah antara kedua saudara kalian) apabila mereka berdua bersengketa. Menurut qiraat yang lain dibaca Ikhwatikum, artinya saudara-saudara kalian (dan bertakwalah kepada Allah supaya kalian mendapat rahmat.)",[["إِنَّمَا","Hanya"],["ٱلْمُؤْمِنُونَ","orang yang beriman"],["إِخْوَةٌۭ","(adalah) saudara"],["فَأَصْلِحُوا۟","jadi berdamai"],["بَيْنَ","antara"],["أَخَوَيْكُمْ ۚ","saudara-saudara kamu"],["وَٱتَّقُوا۟","dan takutlah kepada Allah"],["ٱللَّهَ","dan takutlah kepada Allah"],["لَعَلَّكُمْ","supaya kamu"],["تُرْحَمُونَ","mendapat rahmat"]]],"4623":["(Hai orang-orang yang beriman, janganlah berolok-olokan) dan seterusnya, ayat ini diturunkan berkenaan dengan delegasi dari Bani Tamim sewaktu mereka mengejek orang-orang muslim yang miskin, seperti Ammar bin Yasir dan Shuhaib Ar-Rumi. As-Sukhriyah artinya merendahkan dan menghina (suatu kaum) yakni sebagian di antara kalian (kepada kaum yang lain karena boleh jadi mereka yang diolok-olokkan lebih baik dari mereka yang mengolok-olokkan) di sisi Allah (dan jangan pula wanita-wanita) di antara kalian mengolok-olokkan (wanita-wanita lain karena boleh jadi wanita-wanita yang diperolok-olokkan lebih baik dari wanita-wanita yang mengolok-olokkan dan janganlah kalian mencela diri kalian sendiri) artinya, janganlah kalian mencela, maka karenanya kalian akan dicela; makna yang dimaksud ialah, janganlah sebagian dari kalian mencela sebagian yang lain (dan janganlah kalian panggil-memanggil dengan gelar-gelar yang buruk) yaitu janganlah sebagian di antara kalian memanggil sebagian yang lain dengan nama julukan yang tidak disukainya, antara lain seperti, hai orang fasik, atau hai orang kafir. (Seburuk-buruk nama) panggilan yang telah disebutkan di atas, yaitu memperolok-olokkan orang lain mencela dan memanggil dengan nama julukan yang buruk (ialah nama yang buruk sesudah iman) lafal Al-Fusuuq merupakan Badal dari lafal Al-Ismu, karena nama panggilan yang dimaksud memberikan pengertian fasik dan juga karena nama panggilan itu biasanya diulang-ulang (dan barang siapa yang tidak bertobat) dari perbuatan tersebut (maka mereka itulah orang-orang yang lalim.)",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["لَا","(Biar) jangan"],["يَسْخَرْ","ejekan"],["قَوْمٌۭ","suatu kaum"],["مِّن","[daripada]"],["قَوْمٍ","(orang lain)."],["عَسَىٰٓ","mungkin"],["أَن","bahawa"],["يَكُونُوا۟","mereka mungkin"],["خَيْرًۭا","lebih baik"],["مِّنْهُمْ","daripada mereka"],["وَلَا","dan (biar) jangan"],["نِسَآءٌۭ","perempuan"],["مِّن","[daripada]"],["نِّسَآءٍ","(lain) perempuan"],["عَسَىٰٓ","mungkin"],["أَن","bahawa"],["يَكُنَّ","mereka mungkin"],["خَيْرًۭا","lebih baik"],["مِّنْهُنَّ ۖ","daripada mereka"],["وَلَا","Dan jangan"],["تَلْمِزُوٓا۟","menghina"],["أَنفُسَكُمْ","kamu sendiri"],["وَلَا","dan jangan"],["تَنَابَزُوا۟","memanggil satu sama lain"],["بِٱلْأَلْقَـٰبِ ۖ","dengan nama panggilan"],["بِئْسَ","Malangnya"],["ٱلِٱسْمُ","nama"],["ٱلْفُسُوقُ","(dari) kemaksiatan"],["بَعْدَ","selepas"],["ٱلْإِيمَـٰنِ ۚ","iman"],["وَمَن","Dan sesiapa"],["لَّمْ","tidak"],["يَتُبْ","bertaubat"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","mereka"],["ٱلظَّـٰلِمُونَ","(adalah) orang-orang yang zalim"]]],"4624":["(Hai orang-orang yang beriman, jauhilah kebanyakan dari prasangka, sesungguhnya sebagian prasangka itu adalah dosa) artinya, menjerumuskan kepada dosa, jenis prasangka itu cukup banyak, antara lain ialah berburuk sangka kepada orang mukmin yang selalu berbuat baik. Orang-orang mukmin yang selalu berbuat baik itu cukup banyak, berbeda keadaannya dengan orang-orang fasik dari kalangan kaum muslimin, maka tiada dosa bila kita berburuk sangka terhadapnya menyangkut masalah keburukan yang tampak dari mereka (dan janganlah kalian mencari-cari kesalahan orang lain) lafal Tajassasuu pada asalnya adalah Tatajassasuu, lalu salah satu dari kedua huruf Ta dibuang sehingga jadilah Tajassasuu, artinya janganlah kalian mencari-cari aurat dan keaiban mereka dengan cara menyelidikinya (dan janganlah sebagian kalian menggunjing sebagian yang lain) artinya, janganlah kamu mempergunjingkan dia dengan sesuatu yang tidak diakuinya, sekalipun hal itu benar ada padanya. (Sukakah salah seorang di antara kalian memakan daging saudaranya yang sudah mati?) lafal Maytan dapat pula dibaca Mayyitan; maksudnya tentu saja hal ini tidak layak kalian lakukan. (Maka tentulah kalian merasa jijik kepadanya) maksudnya, mempergunjingkan orang semasa hidupnya sama saja artinya dengan memakan dagingnya sesudah ia mati. Kalian jelas tidak akan menyukainya, oleh karena itu janganlah kalian melakukan hal ini. (Dan bertakwalah kepada Allah) yakni takutlah akan azab-Nya bila kalian hendak mempergunjingkan orang lain, maka dari itu bertobatlah kalian dari perbuatan ini (sesungguhnya Allah Maha Penerima tobat) yakni selalu menerima tobat orang-orang yang bertobat (lagi Maha Penyayang) kepada mereka yang bertobat.",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["ٱجْتَنِبُوا۟","elakkan"],["كَثِيرًۭا","banyak"],["مِّنَ","daripada"],["ٱلظَّنِّ","andaian itu"],["إِنَّ","Sesungguhnya"],["بَعْضَ","beberapa"],["ٱلظَّنِّ","andaian"],["إِثْمٌۭ ۖ","(adalah) dosa"],["وَلَا","Dan jangan"],["تَجَسَّسُوا۟","pengintip"],["وَلَا","dan jangan"],["يَغْتَب","mengumpat"],["بَّعْضُكُم","sebahagian daripada kamu"],["بَعْضًا ۚ","(kepada) orang lain"],["أَيُحِبُّ","mahu"],["أَحَدُكُمْ","salah seorang daripada kamu"],["أَن","kepada"],["يَأْكُلَ","makan"],["لَحْمَ","(the) daging"],["أَخِيهِ","(dari) saudaranya"],["مَيْتًۭا","mati"],["فَكَرِهْتُمُوهُ ۚ","Tidak, kamu akan membencinya"],["وَٱتَّقُوا۟","Dan bertakwalah kepada Allah"],["ٱللَّهَ ۚ","Dan bertakwalah kepada Allah"],["إِنَّ","sesungguhnya"],["ٱللَّهَ","Allah"],["تَوَّابٌۭ","(ialah) Sering Pulang"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"4625":["(Hai manusia, sesungguhnya Kami menciptakan kalian dari seorang laki-laki dan seorang perempuan) yakni dari Adam dan Hawa (dan Kami menjadikan kalian berbangsa-bangsa) lafal Syu'uuban adalah bentuk jamak dari lafal Sya'bun, yang artinya tingkatan nasab keturunan yang paling tinggi (dan bersuku-suku) kedudukan suku berada di bawah bangsa, setelah suku atau kabilah disebut Imarah, lalu Bathn, sesudah Bathn adalah Fakhdz dan yang paling bawah adalah Fashilah. Contohnya ialah Khuzaimah adalah nama suatu bangsa, Kinanah adalah nama suatu kabilah atau suku, Quraisy adalah nama suatu Imarah, Qushay adalah nama suatu Bathn, Hasyim adalah nama suatu Fakhdz, dan Al-Abbas adalah nama suatu Fashilah (supaya kalian saling kenal-mengenal) lafal Ta'aarafuu asalnya adalah Tata'aarafuu, kemudian salah satu dari kedua huruf Ta dibuang sehingga jadilah Ta'aarafuu; maksudnya supaya sebagian dari kalian saling mengenal sebagian yang lain bukan untuk saling membanggakan ketinggian nasab atau keturunan, karena sesungguhnya kebanggaan itu hanya dinilai dari segi ketakwaan. (Sesungguhnya orang yang paling mulia di antara kalian di sisi Allah ialah orang yang paling bertakwa. Sesungguhnya Allah Maha Mengetahui) tentang kalian (lagi Maha Mengenal) apa yang tersimpan di dalam batin kalian.",[["يَـٰٓأَيُّهَا","Wahai umat manusia"],["ٱلنَّاسُ","Wahai umat manusia"],["إِنَّا","Sesungguhnya Kami"],["خَلَقْنَـٰكُم","mencipta kamu"],["مِّن","daripada"],["ذَكَرٍۢ","seorang lelaki"],["وَأُنثَىٰ","dan seorang perempuan"],["وَجَعَلْنَـٰكُمْ","dan Kami jadikan kamu"],["شُعُوبًۭا","bangsa-bangsa"],["وَقَبَآئِلَ","dan suku kaum"],["لِتَعَارَفُوٓا۟ ۚ","supaya kamu berkenalan antara satu sama lain"],["إِنَّ","Sesungguhnya"],["أَكْرَمَكُمْ","(yang) paling mulia di antara kamu"],["عِندَ","dekat"],["ٱللَّهِ","Allah"],["أَتْقَىٰكُمْ ۚ","(ialah) yang paling bertakwa di antara kamu"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلِيمٌ","Maha Mengetahui"],["خَبِيرٌۭ","Maha Mengetahui"]]],"4626":["(Orang-orang Arab Badui itu berkata,) yang dimaksud adalah segolongan dari kalangan Bani Asad (\"Kami telah beriman\") yakni hati kami telah beriman. (Katakanlah) kepada mereka, (\"Kalian belum beriman, tetapi katakanlah, 'Kami telah berserah diri,'\") artinya, kami telah tunduk secara lahiriah (karena masih belumlah) yakni masih belum lagi (iman masuk ke dalam hati kalian) sampai sekarang hanya saja hal itu baru merupakan dugaan bagi kalian (dan jika kalian taat kepada Allah dan Rasul-Nya) yakni dengan cara beriman yang sesungguhnya dan taat dalam segala hal (Dia tidak akan mengurangi) Dia tidak akan mengurangkan (amal-amal kalian) yakni pahala amal-amal kalian (barang sedikit pun; sesungguhnya Allah Maha Pengampun) kepada orang-orang mukmin (lagi Maha Penyayang\") kepada mereka.",[["۞ قَالَتِ","Katakanlah"],["ٱلْأَعْرَابُ","orang Badwi"],["ءَامَنَّا ۖ","Kami beriman"],["قُل","Katakanlah"],["لَّمْ","Tidak"],["تُؤْمِنُوا۟","kamu beriman"],["وَلَـٰكِن","tetapi"],["قُولُوٓا۟","berkata"],["أَسْلَمْنَا","Kami telah menyerahkan"],["وَلَمَّا","dan belum lagi"],["يَدْخُلِ","masuk"],["ٱلْإِيمَـٰنُ","iman"],["فِى","dalam"],["قُلُوبِكُمْ ۖ","hati kamu"],["وَإِن","Tetapi jika"],["تُطِيعُوا۟","kamu taat"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["لَا","tidak"],["يَلِتْكُم","Dia akan menghalang kamu"],["مِّنْ","daripada"],["أَعْمَـٰلِكُمْ","perbuatan kamu"],["شَيْـًٔا ۚ","sesuatu"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌ","Maha Mengasihani"]]],"4627":["(Sesungguhnya orang-orang yang beriman) yakni orang-orang yang benar-benar beriman, sebagaimana yang telah diterangkan sebelumnya (hanyalah orang-orang yang beriman kepada Allah dan Rasul-Nya kemudian mereka tidak ragu-ragu) dalam keimanannya (dan mereka berjihad dengan harta dan jiwa mereka pada jalan Allah) mereka benar-benar berjihad berkat kesungguhan iman mereka (mereka itulah orang-orang yang benar) dalam keimanan mereka, bukan seperti orang-orang yang mengatakan, \"Kami telah beriman\", sedangkan dalam diri mereka yang dijumpai hanya ketundukan belaka.",[["إِنَّمَا","Hanya"],["ٱلْمُؤْمِنُونَ","orang yang beriman"],["ٱلَّذِينَ","(adalah) mereka yang"],["ءَامَنُوا۟","beriman"],["بِٱللَّهِ","kepada Allah"],["وَرَسُولِهِۦ","dan Rasul-Nya"],["ثُمَّ","kemudian"],["لَمْ","jangan"],["يَرْتَابُوا۟","keraguan"],["وَجَـٰهَدُوا۟","tetapi berusaha"],["بِأَمْوَٰلِهِمْ","dengan kekayaan mereka"],["وَأَنفُسِهِمْ","dan kehidupan mereka"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ ۚ","(milik) Allah"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["هُمُ","[mereka]"],["ٱلصَّـٰدِقُونَ","(adalah) orang-orang yang benar"]]],"4628":["(Katakanlah) kepada mereka (\"Apakah kalian akan memberitahukan kepada Allah tentang agama kalian) lafal Tu'allimuuna berasal dari 'Allama yang artinya Sya'ara atau memberitahukan. Maksudnya, apakah kalian melalui perkataan kalian, 'Kami telah beriman', hendak memberitahukan kepada Allah tentang keyakinan kalian (padahal Allah mengetahui apa yang ada di langit dan apa yang ada di bumi dan Allah Mengetahui segala sesuatu.\")",[["قُلْ","Katakanlah"],["أَتُعَلِّمُونَ","Adakah kamu akan berkenalan"],["ٱللَّهَ","Allah"],["بِدِينِكُمْ","dengan agama kamu"],["وَٱللَّهُ","sedangkan Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۚ","bumi"],["وَٱللَّهُ","Dan Allah"],["بِكُلِّ","daripada setiap"],["شَىْءٍ","perkara"],["عَلِيمٌۭ","Maha Mengetahui"]]],"4629":["(Mereka telah merasa memberi nikmat kepadamu dengan keislaman mereka) tanpa melalui perang, berbeda dengan orang-orang selain mereka yang masuk Islam setelah melalui peperangan terlebih dahulu. (Katakanlah, \"Janganlah kalian merasa telah memberi nikmat kepadaku dengan keislaman kalian) lafal Islamakum dinashabkan karena huruf Jarrnya yaitu Ba dicabut darinya, sebagaimana keberadaan huruf Ba ini diperkirakan pula sebelum An pada permulaan ayat (sebenarnya Allah Dialah yang melimpahkan nikmat kepada kalian dengan menunjuki kalian kepada keimanan, jika kalian adalah orang-orang yang benar\") di dalam perkataan kalian yang menyatakan, \"Kami telah beriman.\"",[["يَمُنُّونَ","Mereka menganggap (itu) suatu nikmat"],["عَلَيْكَ","kepada kamu"],["أَنْ","bahawa"],["أَسْلَمُوا۟ ۖ","mereka telah menerima Islam"],["قُل","Katakanlah"],["لَّا","Jangan"],["تَمُنُّوا۟","menganggap nikmat"],["عَلَىَّ","pada aku"],["إِسْلَـٰمَكُم ۖ","Islam kamu"],["بَلِ","Bahkan"],["ٱللَّهُ","Allah"],["يَمُنُّ","telah memberi nikmat"],["عَلَيْكُمْ","ke atas kamu"],["أَنْ","bahawa"],["هَدَىٰكُمْ","Dia telah membimbing kamu"],["لِلْإِيمَـٰنِ","kepada iman"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"4630":["(Sesungguhnya Allah mengetahui apa yang gaib di langit dan di bumi) yakni apa-apa yang tidak kelihatan pada keduanya. (Dan Allah Maha Melihat apa yang kalian kerjakan) dapat dibaca Ta'maluuna atau Ya'maluuna, kalau dibaca Ya'maluuna artinya, Allah Maha Melihat apa yang mereka kerjakan. Maksudnya tiada sesuatu pun darinya yang samar bagi-Nya.",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يَعْلَمُ","mengetahui"],["غَيْبَ","(yang) ghaib"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["وَٱللَّهُ","Dan Allah"],["بَصِيرٌۢ","(ialah) Maha Melihat"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"4631":["(Qaaf) hanya Allah saja yang mengetahui arti dan maksudnya. (Demi Alquran yang sangat agung) artinya, yang sangat mulia, tiadalah orang-orang kafir Mekah beriman kepada Nabi Muhammad saw.",[["قٓ ۚ","Qaf"],["وَٱلْقُرْءَانِ","Oleh al-Quran"],["ٱلْمَجِيدِ","yang Mulia"]]],"4632":["(Bahkan mereka tercengang karena telah datang kepada mereka seorang pemberi peringatan dari kalangan mereka sendiri) yakni seorang rasul yang memperingatkan mereka tentang adanya azab neraka sesudah hari berbangkit, bila mereka tidak beriman (maka berkatalah orang-orang kafir, \"Ini) tentang peringatan itu (adalah suatu hal yang amat ajaib.)",[["بَلْ","Bahkan"],["عَجِبُوٓا۟","mereka tertanya-tanya"],["أَن","bahawa"],["جَآءَهُم","telah datang kepada mereka"],["مُّنذِرٌۭ","seorang pemberi amaran"],["مِّنْهُمْ","daripada mereka"],["فَقَالَ","Jadi katakan"],["ٱلْكَـٰفِرُونَ","orang kafir"],["هَـٰذَا","Ini"],["شَىْءٌ","(adalah) sesuatu"],["عَجِيبٌ","menakjubkan"]]],"4633":["(Apakah bila) dapat dibaca Tahqiq, dapat pula dibaca Tas-hil (kami telah mati dan setelah menjadi tanah) kami akan kembali menjadi hidup? (itu adalah suatu pengembalian yang tidak mungkin\") yakni sangat jauh dari kemungkinan.",[["أَءِذَا","Apa! apabila"],["مِتْنَا","kita mati"],["وَكُنَّا","dan telah menjadi"],["تُرَابًۭا ۖ","habuk"],["ذَٰلِكَ","Itu"],["رَجْعٌۢ","(adalah) pulangan"],["بَعِيدٌۭ","jauh"]]],"4634":["(Sesungguhnya Kami telah mengetahui apa yang dihancurkan oleh bumi) apa yang telah dimakan olehnya (dari tubuh-tubuh mereka, dan pada sisi Kami ada kitab yang memelihara) yaitu Lohmahfuz, di dalamnya telah tertera segala sesuatu yang telah dipastikan ketentuannya.",[["قَدْ","Sungguh"],["عَلِمْنَا","Kami tahu"],["مَا","apa"],["تَنقُصُ","berkurangan"],["ٱلْأَرْضُ","bumi"],["مِنْهُمْ ۖ","daripada mereka"],["وَعِندَنَا","dan dengan Kami"],["كِتَـٰبٌ","(ialah) sebuah Kitab"],["حَفِيظٌۢ","terjaga"]]],"4635":["(Sebenarnya mereka telah mendustakan kebenaran) yakni Alquran (tatkala kebenaran itu datang kepada mereka, maka mereka) menanggapi tentang perihal Nabi saw. dan Alquran (berada dalam keadaan kacau-balau) yakni tidak menentu, terkadang mereka mengatakan, bahwa Nabi adalah penyihir dan Alquran adalah sihir, terkadang juga mengatakan bahwa dia adalah penyair dan Alquran adalah syairnya, terkadang mereka mengatakan bahwa dia adalah seorang peramal dan Alquran adalah ramalannya.",[["بَلْ","Bahkan"],["كَذَّبُوا۟","mereka menafikan"],["بِٱلْحَقِّ","kebenaran"],["لَمَّا","apabila"],["جَآءَهُمْ","ia datang (kepada) mereka"],["فَهُمْ","jadi mereka"],["فِىٓ","(ada) dalam"],["أَمْرٍۢ","sebuah negeri"],["مَّرِيجٍ","keliru"]]],"4636":["(Maka apakah mereka tidak melihat) dengan mata mereka. Padahal mata itu, dipasang untuk mengambil pelajaran dari apa yang dilihatnya, yaitu sewaktu mereka ingkar kepada adanya hari berbangkit (akan langit) yang ada (di atas mereka bagaimana Kami telah membangunnya) tanpa tiang penyangga (dan Kami hiasi dia) dengan bintang-bintang (dan langit itu tidak mempunyai retak-retak sedikit pun?) yakni tidak ada celah-celah yang membuatnya cacat.",[["أَفَلَمْ","Kemudian jangan"],["يَنظُرُوٓا۟","mereka melihat"],["إِلَى","di"],["ٱلسَّمَآءِ","langit"],["فَوْقَهُمْ","di atas mereka"],["كَيْفَ","bagaimana"],["بَنَيْنَـٰهَا","Kami menstrukturkannya"],["وَزَيَّنَّـٰهَا","dan menghiasinya"],["وَمَا","dan bukan"],["لَهَا","baginya"],["مِن","sebarang"],["فُرُوجٍۢ","keretakan"]]],"4637":["(Dan bumi itu) di'athafkan kepada kedudukan lafal As-samaa' yakni, dan bumi itu bagaimana (Kami hamparkan) Kami jadikan terhampar menurut pandangan mata di atas permukaan air (dan Kami letakkan padanya gunung-gunung) yang memantapkannya (dan Kami tumbuhkan padanya segala macam tanaman) segala jenis tumbuh-tumbuhan (yang indah) yang tampak sangat indah dipandang mata karena keindahannya.",[["وَٱلْأَرْضَ","Dan bumi"],["مَدَدْنَـٰهَا","Kami telah menyebarkannya"],["وَأَلْقَيْنَا","dan membuang"],["فِيهَا","di dalamnya"],["رَوَٰسِىَ","gunung yang kukuh"],["وَأَنۢبَتْنَا","dan Kami tumbuhkan"],["فِيهَا","di dalamnya"],["مِن","daripada"],["كُلِّ","setiap"],["زَوْجٍۭ","baik hati"],["بَهِيجٍۢ","cantik"]]],"4638":["(Untuk menjadi pelajaran) menjadi maf'ul lah, yakni, Kami lakukan hal tersebut sebagai pemberian pelajaran dari Kami (dan peringatan) untuk dijadikan sebagai peringatan (bagi tiap-tiap hamba yang kembali) untuk taat kepada Kami.",[["تَبْصِرَةًۭ","Memberi pandangan"],["وَذِكْرَىٰ","dan peringatan"],["لِكُلِّ","untuk setiap"],["عَبْدٍۢ","hamba"],["مُّنِيبٍۢ","yang berpaling"]]],"4639":["(Dan Kami turunkan dari langit air yang penuh keberkatan) berkah dan manfaatnya (lalu Kami tumbuhkan dengan air itu pohon-pohon) maksudnya kebun-kebun (dan biji-biji tanaman) yakni ladang-ladang (yang diketam) yang dipanen.",[["وَنَزَّلْنَا","Dan Kami telah menurunkan"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ","air"],["مُّبَـٰرَكًۭا","diberkati"],["فَأَنۢبَتْنَا","kemudian Kami tumbuhkan"],["بِهِۦ","dengan itu"],["جَنَّـٰتٍۢ","taman-taman"],["وَحَبَّ","dan bijirin"],["ٱلْحَصِيدِ","(untuk) tuaian"]]],"4640":["(Dan pohon-pohon kurma yang tinggi-tinggi) lafal Baasiqaatin ini berkedudukan menjadi Hal bagi lafal yang diperkirakan keberadaannya (yang mempunyai mayang yang bersusun-susun) yaitu sebagian di antaranya bertumpuk di atas sebagian yang lain.",[["وَٱلنَّخْلَ","Dan pokok palma"],["بَاسِقَـٰتٍۢ","tinggi"],["لَّهَا","baginya"],["طَلْعٌۭ","(adalah) lapisan"],["نَّضِيدٌۭ","tersusun"]]],"4641":["(Untuk menjadi rezeki bagi hamba-hamba) Kami; lafal Rizqan menjadi Maf'ul Lah (dan Kami hidupkan dengan air itu tanah yang mati) lafal Maytan dapat digunakan untuk Mudzakkar dan Muannats. (Seperti itulah) dengan cara itulah (terjadinya kebangkitan) dari kubur, maka mengapa kalian mengingkarinya? Istifham atau kata tanya mengandung makna Taqrir, makna yang dimaksud adalah bahwa mereka melihat dan mengetahui hal tersebut.",[["رِّزْقًۭا","Satu peruntukan"],["لِّلْعِبَادِ ۖ","untuk budak-budak"],["وَأَحْيَيْنَا","dan Kami memberi kehidupan"],["بِهِۦ","dengan itu"],["بَلْدَةًۭ","(ke) tanah"],["مَّيْتًۭا ۚ","mati"],["كَذَٰلِكَ","Demikianlah"],["ٱلْخُرُوجُ","(akan menjadi) kedatangan"]]],"4642":["(Sebelum mereka telah mendustakan pula kaum Nuh) di-ta`nits-kannya dhamir yang ada pada lafal Kadzdzabat karena memandang makna yang terkandung dalam lafal Qaumun (dan penduduk Rass) Rass adalah nama sebuah sumur yang di sekitarnya tinggal suatu kaum berikut ternak mereka; mereka menyembah berhala, menurut suatu pendapat nabi mereka bernama Hanzhalah bin Shafwan; menurut pendapat lainnya bukanlah dia, (dan Tsamud) yaitu kaum Nabi Shaleh.",[["كَذَّبَتْ","dinafikan"],["قَبْلَهُمْ","sebelum mereka"],["قَوْمُ","kaum"],["نُوحٍۢ","(daripada) Nuh"],["وَأَصْحَـٰبُ","dan (para) sahabat"],["ٱلرَّسِّ","(dari) Ar-Raas"],["وَثَمُودُ","dan kaum Thamud"]]],"4643":["(Dan kaum Ad) kaum Nabi Hud (kaum Firaun dan kaum Luth.)",[["وَعَادٌۭ","Dan Aad"],["وَفِرْعَوْنُ","dan Firaun"],["وَإِخْوَٰنُ","dan (para) saudara"],["لُوطٍۢ","(dari) Lut"]]],"4644":["(Dan penduduk Aikah) yakni penduduk Ghaidhah kaum Nabi Syuaib (serta kaum Tubba') Tubba' adalah nama raja di negeri Yaman; ia masuk Islam lalu menyeru kaumnya untuk masuk Islam, tetapi mereka mendustakannya (masing-masing) dari kaum-kaum yang telah disebutkan tadi (mendustakan rasul-rasul) sebagaimana yang dilakukan oleh kabilah Quraisy (maka sudah semestinya mereka mendapat ancaman-Ku) artinya sudah semestinya semuanya menerima azab-Ku, maka janganlah kamu susah dengan kekafiran orang-orang Quraisy terhadap dirimu.",[["وَأَصْحَـٰبُ","Dan (para) sahabat"],["ٱلْأَيْكَةِ","(dari) kayu itu"],["وَقَوْمُ","dan (orang-orang) itu"],["تُبَّعٍۢ ۚ","(daripada) Tubba"],["كُلٌّۭ","Semua"],["كَذَّبَ","dinafikan"],["ٱلرُّسُلَ","para Rasul"],["فَحَقَّ","jadi dipenuhi"],["وَعِيدِ","Ancaman Aku"]]],"4645":["(Maka apakah Kami letih dengan penciptaan yang pertama?) maksudnya, Kami tidak merasa letih dengan penciptaan yang pertama itu, demikian pula Kami tidak merasa letih untuk mengembalikan mereka. (Sebenarnya mereka dalam keadaan ragu-ragu) yakni berada dalam keragu-raguan (tentang penciptaan yang baru) yaitu membangkitkan mereka menjadi hidup kembali pada hari berbangkit nanti.",[["أَفَعَيِينَا","Adakah Kami ketika itu letih"],["بِٱلْخَلْقِ","dengan penciptaan"],["ٱلْأَوَّلِ ۚ","yang pertama"],["بَلْ","Bahkan"],["هُمْ","mereka"],["فِى","(ada) dalam"],["لَبْسٍۢ","keraguan"],["مِّنْ","tentang"],["خَلْقٍۢ","sebuah ciptaan"],["جَدِيدٍۢ","baru"]]],"4646":["(Dan sesungguhnya Kami telah menciptakan manusia sedangkan Kami mengetahui) lafal Na'lamu ini berkedudukan menjadi Hal atau kata keterangan keadaan dan sebelumnya diperkirakan adanya lafal Nahnu (apa) huruf Maa di sini adalah Mashdariyah (yang dibisikkan) dibicarakan (oleh dia) yakni oleh manusia, huruf Ba di sini adalah Zaidah, atau untuk Ta'diyah (dalam hatinya, dan Kami lebih dekat kepadanya) maksudnya ilmu Kami (daripada urat lehernya) Idhafah di sini mengandung makna Bayan atau untuk menjelaskan, dan pengertian yang dimaksud dari lafal Al-Wariid adalah dua urat vital yang terdapat pada bagian belakang leher.",[["وَلَقَدْ","Dan sungguh"],["خَلَقْنَا","Kami mencipta"],["ٱلْإِنسَـٰنَ","lelaki"],["وَنَعْلَمُ","dan Kami tahu"],["مَا","apa"],["تُوَسْوِسُ","berbisik"],["بِهِۦ","kepadanya"],["نَفْسُهُۥ ۖ","jiwanya"],["وَنَحْنُ","dan Kami"],["أَقْرَبُ","(ada) lebih dekat"],["إِلَيْهِ","kepadanya"],["مِنْ","daripada"],["حَبْلِ","(nya) urat lehernya"],["ٱلْوَرِيدِ","(nya) urat lehernya"]]],"4647":["(Ingatlah ketika) lafal Idz di sini dinashabkan oleh lafal Udzkur yang keberadaannya diperkirakan (mencatat) yakni menulis (dua malaikat pencatat amal) artinya, yang diserahi tugas oleh Allah untuk mencatat amal perbuatan yang dilakukan oleh manusia (yang satu berada di sebelah kanan dan yang lain berada di sebelah kiri) manusia (dalam keadaan duduk) yakni keduanya duduk, lafal Qa'iid ini adalah Mubtada dan Khabarnya adalah lafal sebelumnya.",[["إِذْ","Apabila"],["يَتَلَقَّى","menerima"],["ٱلْمُتَلَقِّيَانِ","kedua-dua penerima"],["عَنِ","pada"],["ٱلْيَمِينِ","yang betul"],["وَعَنِ","dan seterusnya"],["ٱلشِّمَالِ","sebelah kiri"],["قَعِيدٌۭ","duduk"]]],"4648":["(Tiada suatu ucapan pun yang dikatakan melainkan ada malaikat pengawas) yakni malaikat pencatat amal (yang selalu hadir) selalu berada di sisinya; lafal Raqiib dan 'Atiid ini keduanya mengandung makna Mutsanna.",[["مَّا","Tidak"],["يَلْفِظُ","dia bersuara"],["مِن","sebarang"],["قَوْلٍ","perkataan"],["إِلَّا","tetapi"],["لَدَيْهِ","dengan dia"],["رَقِيبٌ","(adalah) seorang pemerhati"],["عَتِيدٌۭ","sedia"]]],"4649":["(Dan datanglah sakaratul maut) yakni kesusahan dan rasa sakit yang memuncak menjelang maut (dengan membawa kebenaran) yakni perkara akhirat, hingga orang yang ingkar kepada hari akhirat dapat melihatnya secara nyata, hal ini termasuk pula hal yang menyakitkan. (Itulah) kematian itu (hal yang kamu tidak dapat menghindar darinya) yakni tidak dapat melarikan diri darinya.",[["وَجَآءَتْ","Dan akan datang"],["سَكْرَةُ","(yang) buntu"],["ٱلْمَوْتِ","(dari) kematian"],["بِٱلْحَقِّ ۖ","dalam kebenaran"],["ذَٰلِكَ","Itu"],["مَا","(ialah) apa"],["كُنتَ","kamu dahulu"],["مِنْهُ","[daripadanya]"],["تَحِيدُ","mengelak"]]],"4650":["(Dan ditiuplah sangkakala) untuk membangkitkan manusia. (Itulah) yakni hari peniupan itu (hari terlaksananya ancaman) bagi orang-orang kafir, yaitu mereka akan mengalami siksaan.",[["وَنُفِخَ","Dan akan ditiup"],["فِى","[dalam]"],["ٱلصُّورِ ۚ","sangkakala"],["ذَٰلِكَ","Itu"],["يَوْمُ","(ialah) Hari"],["ٱلْوَعِيدِ","(dari) Amaran"]]],"4651":["(Dan datanglah) pada hari itu (tiap-tiap diri) ke tempat mereka dikumpulkan yaitu padang Mahsyar (bersama dengan dia penggiringnya) yaitu malaikat yang menggiringnya ke padang Mahsyar (dan pemberi saksi) yang akan memberikan kesaksian tentang semua amal perbuatannya, yaitu tangan dan kakinya serta anggota-anggota tubuhnya yang lain. Kemudian pada saat itu dikatakan kepada orang yang kafir:",[["وَجَآءَتْ","Dan akan datang"],["كُلُّ","setiap"],["نَفْسٍۢ","jiwa"],["مَّعَهَا","dengannya"],["سَآئِقٌۭ","seorang pemandu"],["وَشَهِيدٌۭ","dan saksi"]]],"4652":["(\"Sesungguhnya kamu) sewaktu di dunia (berada dalam keadaan lalai dari hal ini) yang sekarang menimpa kamu (maka Kami singkapkan daripadamu tutupmu) maksudnya, Kami lenyapkan kelalaianmu dengan apa yang kamu saksikan sekarang ini (maka penglihatanmu pada hari ini tajam\") yakni menjadi terang dan dapat melihat apa yang kamu ingkari sewaktu di dunia.",[["لَّقَدْ","Sungguh"],["كُنتَ","kamu dahulu"],["فِى","dalam"],["غَفْلَةٍۢ","kelalaian"],["مِّنْ","daripada"],["هَـٰذَا","ini"],["فَكَشَفْنَا","Maka Kami telah hapuskan"],["عَنكَ","daripada kamu"],["غِطَآءَكَ","penutup kamu"],["فَبَصَرُكَ","jadi penglihatan kamu"],["ٱلْيَوْمَ","hari ini"],["حَدِيدٌۭ","(adalah) tajam"]]],"4653":["(Dan yang menyertai dia berkata,) yakni malaikat yang diserahi tugas mencatat amal perbuatannya: (\"Inilah apa) yakni catatan amalmu (yang ada pada sisiku\") yakni catatan amalmu yang ada padaku. Lalu dikatakan kepada malaikat Malik:",[["وَقَالَ","Dan (akan) berkata"],["قَرِينُهُۥ","temannya"],["هَـٰذَا","Ini"],["مَا","(ialah) apa"],["لَدَىَّ","(ada) dengan aku"],["عَتِيدٌ","sedia"]]],"4654":["(\"Lemparkanlah olehmu ke dalam neraka Jahanam) maksudnya, lemparkanlah, atau cepat lemparkan. Menurut bacaan atau qiraat Imam Al-Hasan lafal Alqiyaa dibaca Alqiyan. Jadi asal kata lafal Alqiyaa adalah Alqiyan, kemudian huruf Nun Taukidnya diganti menjadi Alif sehingga jadilah Alqiyaa (semua orang yang ingkar dan keras kepala) maksudnya, membangkang terhadap perkara yang hak.",[["أَلْقِيَا","Baling"],["فِى","dalam (ke)"],["جَهَنَّمَ","Neraka"],["كُلَّ","setiap"],["كَفَّارٍ","orang kafir"],["عَنِيدٍۢ","degil"]]],"4655":["(Yang sangat menghalangi kebaikan) seperti perkara zakat (melanggar batas) yakni suka berbuat zalim (lagi ragu-ragu) ragu dalam agamanya.",[["مَّنَّاعٍۢ","Pengharam"],["لِّلْخَيْرِ","daripada kebaikan"],["مُعْتَدٍۢ","pelanggar"],["مُّرِيبٍ","ragu-ragu"]]],"4656":["(Yang menjadikan tuhan lain di samping Allah) lafal ayat ini berkedudukan menjadi Mubtada yang mengandung makna Syarat, sedangkan Khabarnya ialah: (maka lemparkanlah dia ke dalam siksaan yang keras\") penafsiran lafal ayat ini sama dengan ayat yang semisal dengannya di atas tadi.",[["ٱلَّذِى","Siapa"],["جَعَلَ","dibuat"],["مَعَ","dengan"],["ٱللَّهِ","Allah"],["إِلَـٰهًا","tuhan"],["ءَاخَرَ","yang lain"],["فَأَلْقِيَاهُ","jadi buang dia"],["فِى","dalam (ke)"],["ٱلْعَذَابِ","azab"],["ٱلشَّدِيدِ","yang teruk"]]],"4657":["(Yang menyertai dia berkata) yakni setannya mengatakan: (\"Ya Rabb kami! Aku tidak menyesatkannya) kami tidak membuatnya sesat (tetapi dialah yang berada dalam kesesatan yang jauh\") lalu kami mengajaknya dan ternyata ia memenuhi ajakanku. Sedangkan dia menjawab, \"Setanlah yang menyesatkan aku\", yaitu melalui ajakannya.",[["۞ قَالَ","Akan berkata"],["قَرِينُهُۥ","temannya"],["رَبَّنَا","Wahai Tuhan kami"],["مَآ","tidak"],["أَطْغَيْتُهُۥ","Aku membuat dia melampaui batas"],["وَلَـٰكِن","tetapi"],["كَانَ","dia adalah"],["فِى","dalam"],["ضَلَـٰلٍۭ","ralat"],["بَعِيدٍۢ","jauh"]]],"4658":["(Allah berfirman,) Maha Tinggi Dia (\"Janganlah kalian bertengkar di hadapan-Ku) maksudnya, tiada gunanya pertengkaran kalian di sini (padahal sesungguhnya Aku dahulu telah memberikan kepada kalian) sewaktu kalian hidup di dunia (ancaman) akan adanya azab di akhirat jika kalian tidak beriman, dan ini merupakan suatu kepastian yang tidak dapat dihindari lagi.",[["قَالَ","Dia akan berkata"],["لَا","Jangan"],["تَخْتَصِمُوا۟","pertikaian"],["لَدَىَّ","(dalam) kehadiran aku"],["وَقَدْ","dan sesungguhnya"],["قَدَّمْتُ","Aku menghantar"],["إِلَيْكُم","kepada kamu"],["بِٱلْوَعِيدِ","Amaran itu"]]],"4659":["(Tidaklah dapat diganti) diubah (keputusan yang ada di sisi-Ku) mengenai hal tersebut (dan Aku sekali-kali tidak menganiaya hamba-hamba-Ku) yaitu dengan cara Aku mengazab mereka tanpa dosa; lafal Zhallaamin bermakna seperti lafal Dzuu Zhulmin yaitu menganiaya, demikian itu karena ada firman lainnya yang mengatakan, \"Tidak ada yang dianiaya pada hari ini.\" (Q.S. Al-Mukmin, 17)",[["مَا","Tidak"],["يُبَدَّلُ","akan diubah"],["ٱلْقَوْلُ","perkataan itu"],["لَدَىَّ","dengan Aku"],["وَمَآ","dan bukan"],["أَنَا۠","Aku"],["بِظَلَّـٰمٍۢ","tidak adil"],["لِّلْعَبِيدِ","kepada hamba-hamba-Ku"]]],"4660":["(Pada hari) lafal ini dinashabkan oleh lafal Zhallaamin (Kami bertanya) dapat dibaca Naquulu atau Yaquulu, kalau dibaca Yaquulu artinya, Allah bertanya (kepada neraka Jahanam, \"Apakah kamu sudah penuh?\") kata tanya di sini dimaksud mengecek ancaman-Nya yang menyatakan akan memenuhinya. (Dan dia menjawab, \"Masih adakah tambahan?\") maksudnya, kami tidak memuat melainkan hanya apa yang telah Engkau penuhkan kepada kami. Artinya kami telah penuh.",[["يَوْمَ","(The) Hari"],["نَقُولُ","Kami akan berkata"],["لِجَهَنَّمَ","ke Neraka"],["هَلِ","Adakah"],["ٱمْتَلَأْتِ","kamu penuhkan"],["وَتَقُولُ","Dan ia akan berkata"],["هَلْ","Adakah"],["مِن","(ada) mana-mana"],["مَّزِيدٍۢ","lebih"]]],"4661":["(Dan didekatkanlah surga itu) atau dijadikan dekat (kepada orang-orang yang bertakwa) surga itu didekatkan pada suatu tempat (yang tidak jauh) dari orang-orang yang bertakwa, sehingga mereka dapat melihatnya dengan jelas, kemudian dikatakan kepada mereka:",[["وَأُزْلِفَتِ","Dan akan didekatkan"],["ٱلْجَنَّةُ","syurga itu"],["لِلْمُتَّقِينَ","kepada orang yang soleh"],["غَيْرَ","tidak"],["بَعِيدٍ","jauh"]]],"4662":["(Inilah) artinya, pemandangan yang dilihat ini (yang dijanjikan kepada kalian) dapat dibaca Tuu'aduuna atau Yuu'aduuna, kalau dibaca Yuu'aduuna artinya, yang dijanjikan kepada mereka sewaktu mereka di dunia. Kemudian lafal Al-Muttaqiina tadi dijelaskan melalui firman selanjutnya, yaitu: (kepada setiap hamba yang selalu kembali) yakni kembali kepada jalan ketaatan kepada Allah (lagi memelihara) batasan-batasan-Nya.",[["هَـٰذَا","Ini"],["مَا","(ialah) apa"],["تُوعَدُونَ","kamu telah dijanjikan"],["لِكُلِّ","untuk semua orang"],["أَوَّابٍ","yang berpaling"],["حَفِيظٍۢ","(dan) siapa yang menyimpan"]]],"4663":["(Yaitu orang yang takut kepada Yang Maha Pemurah sedangkan Dia tidak kelihatan olehnya) sekalipun ia tidak melihat-Nya (dan dia datang dengan kalbu yang bertobat) yakni dengan kalbu yang taat kepada-Nya. Dan dikatakan pula kepada orang-orang yang bertakwa:",[["مَّنْ","Siapa"],["خَشِىَ","ditakuti"],["ٱلرَّحْمَـٰنَ","Yang Maha Pemurah"],["بِٱلْغَيْبِ","dalam ghaib"],["وَجَآءَ","dan datang"],["بِقَلْبٍۢ","dengan hati"],["مُّنِيبٍ","kembali"]]],"4664":["(\"Masukilah surga itu dengan aman) artinya, dengan perasaan yang aman dari semua hal yang menakutkan. Atau dengan selamat, yakni selamatlah dan masuklah kalian ke dalamnya (itulah) yaitu hari sewaktu mereka memasuki surga itu (hari kekekalan\") artinya hidup abadi di dalam surga.",[["ٱدْخُلُوهَا","Masukkan ia"],["بِسَلَـٰمٍۢ ۖ","dalam keadaan aman"],["ذَٰلِكَ","Itu"],["يَوْمُ","(adalah) sehari"],["ٱلْخُلُودِ","(dari) Keabadian"]]],"4665":["(Mereka di dalamnya memperoleh apa yang mereka kehendaki; dan pada sisi Kami ada tambahannya) yakni sebagai pahala tambahan dari apa yang telah kalian amalkan, dan sebagai tambahan dari apa yang telah kalian minta.",[["لَهُم","Untuk mereka"],["مَّا","apa sahaja"],["يَشَآءُونَ","mereka mahu"],["فِيهَا","di dalamnya"],["وَلَدَيْنَا","dan dengan Kami"],["مَزِيدٌۭ","(adalah) lebih"]]],"4666":["(Dan berapa banyaknya umat-umat yang telah Kami binasakan sebelum mereka) sebelum orang-orang kafir Quraisy Kami telah membinasakan banyak umat yang kafir (yang mereka itu lebih besar kekuatannya daripada mereka ini) maksudnya umat-umat dahulu itu jauh lebih kuat daripada mereka (maka mereka telah pernah menjelajah) telah mengembara (di beberapa negeri. Adakah mereka mendapat tempat lari) dari kematian; yang dimaksud adalah mereka yang telah dibinasakan atau lainnya. Maka ternyata mereka tidak dapat menemukan jalan untuk melarikan diri dari kematian.",[["وَكَمْ","Dan berapa banyak"],["أَهْلَكْنَا","Kami musnahkan"],["قَبْلَهُم","sebelum mereka"],["مِّن","daripada"],["قَرْنٍ","satu generasi"],["هُمْ","mereka"],["أَشَدُّ","(adalah) lebih kuat"],["مِنْهُم","daripada mereka"],["بَطْشًۭا","(dalam) kuasa"],["فَنَقَّبُوا۟","jadi mereka meneroka"],["فِى","sepanjang"],["ٱلْبِلَـٰدِ","tanah-tanah itu"],["هَلْ","Adakah (ada)"],["مِن","sebarang"],["مَّحِيصٍ","tempat melarikan diri"]]],"4667":["(Sesungguhnya pada yang demikian itu) pada hal-hal yang telah disebutkan itu (benar-benar terdapat peringatan) yakni pelajaran (bagi orang yang mempunyai akal) pikiran (atau yang menggunakan pendengarannya) artinya, mau mendengar nasihat (sedangkan dia menyaksikannya) maksudnya, hatinya hadir.",[["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَذِكْرَىٰ","sesungguhnya, adalah peringatan"],["لِمَن","untuk (seorang) yang"],["كَانَ","ialah"],["لَهُۥ","baginya"],["قَلْبٌ","sebuah hati"],["أَوْ","atau"],["أَلْقَى","(yang) memberi telinga"],["ٱلسَّمْعَ","(yang) memberi telinga"],["وَهُوَ","sedangkan dia"],["شَهِيدٌۭ","(adalah) saksi"]]],"4668":["(Dan sesungguhnya telah Kami ciptakan langit dan bumi dan apa yang ada antara keduanya dalam enam hari) pada permulaannya adalah hari Ahad dan selesai pada hari Jumat (dan Kami sedikit pun tidak ditimpa keletihan) kepayahan. Ayat ini diturunkan sebagai sanggahan terhadap orang-orang Yahudi yang telah mengatakan bahwa Allah swt. pada hari Sabtu-Nya beristirahat. Ditiadakannya sifat lebih daripada-Nya karena memang Dia Maha Suci dari sifat-sifat yang dimiliki oleh makhluk-Nya, dan pula karena tiada kesamaan antara Allah dan selain-Nya. Di dalam ayat lain sehubungan dengan masalah penciptaan ini disebutkan melalui firman-Nya, \"Sesungguhnya keadaan-Nya apabila Dia menghendaki sesuatu hanyalah berkata kepadanya, 'Jadilah!' Maka terjadilah ia.\" (Q.S. Yaasin, 82)",[["وَلَقَدْ","Dan sungguh"],["خَلَقْنَا","Kami mencipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["وَمَا","dan apa sahaja"],["بَيْنَهُمَا","(adalah) antara keduanya"],["فِى","dalam"],["سِتَّةِ","enam"],["أَيَّامٍۢ","tempoh"],["وَمَا","dan (tidak) tidak"],["مَسَّنَا","sentuh Kami"],["مِن","sebarang"],["لُّغُوبٍۢ","keletihan"]]],"4669":["(Maka bersabarlah kamu) khithab pada ayat ini ditujukan kepada Nabi saw. (terhadap apa yang mereka katakan) yang dikatakan orang-orang Yahudi dan lainnya yang menyerupakan Allah dengan makhluk-Nya dan yang mendustakan kamu (dan bertasbihlah seraya memuji Rabbmu) yakni salatlah seraya memuji-Nya (sebelum terbit matahari) yakni salat Subuh (dan sebelum terbenamnya) yakni salat Zuhur dan salat Asar.",[["فَٱصْبِرْ","Jadi bersabarlah"],["عَلَىٰ","atas"],["مَا","apa"],["يَقُولُونَ","mereka berkata"],["وَسَبِّحْ","dan bertasbih"],["بِحَمْدِ","(yang) pujian"],["رَبِّكَ","Tuhanmu"],["قَبْلَ","sebelum"],["طُلُوعِ","(yang) meningkat"],["ٱلشَّمْسِ","(dari) matahari"],["وَقَبْلَ","dan sebelum ini"],["ٱلْغُرُوبِ","tetapan"]]],"4670":["(Dan bertasbihlah kamu di malam hari) artinya lakukanlah kedua salat pada waktu permulaan malam hari (dan setiap selesai salat) kalau dibaca Adbaar berarti bentuk jamak dari lafal Duburun, sedangkan kalau dibaca Idbaar berarti Mashdar dari lafal Adbara. Artinya, lakukanlah salat tambahan yang disunahkan setiap selesai menjalankan salat fardu. Menurut suatu pendapat makna yang dimaksud adalah hakikat dari ucapan tasbih seraya memuji Allah yang dilakukan pada waktu-waktu tersebut.",[["وَمِنَ","Dan daripada"],["ٱلَّيْلِ","malam"],["فَسَبِّحْهُ","bertasbih kepadaNya"],["وَأَدْبَـٰرَ","dan selepas"],["ٱلسُّجُودِ","sujud itu"]]],"4671":["(Dan dengarkanlah) hai orang yang diajak bicara akan seruan-Ku ini (pada hari penyeru menyeru) yakni malaikat Israfil (dari tempat yang dekat) dari langit, yaitu dari atas Kubbah Shakhr di Baitulmakdis, karena tempat itu yang paling dekat dengan langit. Ia menyerukan kata-kata, \"Hai tulang-belulang yang telah hancur dan sendi-sendi yang telah bercerai-berai dan daging-daging yang telah tercabik-cabik dan rambut-rambut yang telah berantakan! Sesungguhnya Allah memerintahkan kalian semua untuk berhimpun guna melaksanakan peradilan.\"",[["وَٱسْتَمِعْ","Dan dengar"],["يَوْمَ","(The) Hari"],["يُنَادِ","akan memanggil"],["ٱلْمُنَادِ","pemanggil"],["مِن","daripada"],["مَّكَانٍۢ","sebuah tempat"],["قَرِيبٍۢ","dekat"]]],"4672":["(Yaitu pada hari) menjadi Badal Isytimal dari lafal Yauma sebelumnya (mereka mendengar) maksudnya, ketika makhluk semuanya mendengar (teriakan dengan sebenar-benarnya) untuk membangkitkan makhluk semuanya, yaitu tiupan yang kedua dari malaikat Israfil. Dan teriakan ini adakalanya sesudah seruan itu atau sebelumnya (itulah) yakni hari seruan yang semua makhluk mendengarnya (hari keluar) dari kubur. Dan yang menashabkan lafal Yauma Yunaadi keberadaannya diperkirakan; lengkapnya: Mereka mengetahui akibat dari kedustaan mereka itu, pada hari penyeru menyerukan.",[["يَوْمَ","(The) Hari"],["يَسْمَعُونَ","mereka akan mendengar"],["ٱلصَّيْحَةَ","Letupan itu"],["بِٱلْحَقِّ ۚ","dalam kebenaran"],["ذَٰلِكَ","Itu"],["يَوْمُ","(ialah) Hari"],["ٱلْخُرُوجِ","(dari) keluar"]]],"4673":["(Sesungguhnya Kami menghidupkan dan mematikan dan hanya kepada Kamilah tempat kembali -semua makhluk-.)",[["إِنَّا","Sesungguhnya Kami"],["نَحْنُ","[Kami]"],["نُحْىِۦ","[Kami] memberi kehidupan"],["وَنُمِيتُ","dan [Kami] menyebabkan kematian"],["وَإِلَيْنَا","dan kepada Kami"],["ٱلْمَصِيرُ","(ialah) pulangan terakhir"]]],"4674":["(Yaitu pada hari) lafal Yauma pada ayat ini menjadi Badal atau pengganti dari lafal Yauma sebelumnya, sedangkan kalimat-kalimat yang menengah-nengahi di antara keduanya merupakan jumlah I'tiradh atau kalimat sisipan (terbelah-belah) dapat dibaca Tasyaqqaqu atau Tasysyaqqaqu, pada asalnya adalah Tatasyaqqaqu, lalu huruf Ta yang kedua diidgamkan kepada huruf Syin sehingga menjadi Tasysyaqqaqu (bumi menampakkan mereka dengan cepat) lafal Siraa'an adalah bentuk jamak dari lafal Sarii'un yang artinya cepat; berkedudukan menjadi Hal atau kata keterangan keadaan bagi lafal yang diperkirakan keberadaannya. Lengkapnya, mereka keluar dengan cepat dari kuburnya masing-masing. (Yang demikian itu adalah pengumpulan yang mudah bagi Kami) pada ayat ini terdapat Fashl atau pemisah yang memisahkan antara Maushuf dan Shifatnya, yang menjadi pemisah adalah Muta'alliqnya, hal ini mengandung makna Ikhtishash, dan hal seperti ini tidak mengapa. Demikian ini mengisyaratkan kepada pengertian pengumpulan yang dimaksud, yaitu menghidupkan kembali makhluk yang telah mati, dan pengumpulan ini dimaksud untuk menghadapkan semua makhluk ke hadapan-Nya guna menjalani hisab.",[["يَوْمَ","(The) Hari"],["تَشَقَّقُ","akan berpecah"],["ٱلْأَرْضُ","bumi"],["عَنْهُمْ","daripada mereka"],["سِرَاعًۭا ۚ","tergesa-gesa"],["ذَٰلِكَ","Itu"],["حَشْرٌ","(adalah) perhimpunan"],["عَلَيْنَا","untuk Kami"],["يَسِيرٌۭ","mudah"]]],"4675":["(Kami lebih mengetahui tentang apa yang mereka katakan) yaitu yang dikatakan oleh orang-orang kafir Quraisy (dan kamu sekali-kali bukanlah seorang pemaksa terhadap mereka yang memaksa mereka untuk beriman, ayat ini diturunkan sebelum ada perintah berjihad. (Maka berilah peringatan dengan Alquran orang yang takut kepada ancaman-Ku) mereka adalah orang-orang mukmin.",[["نَّحْنُ","Kami"],["أَعْلَمُ","tahu yang terbaik"],["بِمَا","[dari] apa"],["يَقُولُونَ ۖ","mereka berkata"],["وَمَآ","dan bukan"],["أَنتَ","(adakah) kamu"],["عَلَيْهِم","atas mereka"],["بِجَبَّارٍۢ ۖ","yang memaksa"],["فَذَكِّرْ","Tapi ingatkan"],["بِٱلْقُرْءَانِ","dengan al-Quran"],["مَن","sesiapa sahaja"],["يَخَافُ","ketakutan"],["وَعِيدِ","ugutan aku"]]],"4676":["(Demi yang menerbangkan debu) yakni angin dan lain-lainnya (dengan sekuat-kuatnya) adalah Mashdar, yang diambil dari kata: Tudzriihi Dzaryan, artinya angin itu menerbangkannya.",[["وَٱلذَّٰرِيَـٰتِ","Oleh mereka yang berselerak"],["ذَرْوًۭا","bersurai"]]],"4677":["(Dan demi awan yang mengandung) awan yang membawa air (hujan) yakni beban berupa air hujan, berkedudukan menjadi Maf'ul dari lafal Al Haamiaat.",[["فَٱلْحَـٰمِلَـٰتِ","Dan mereka yang membawa"],["وِقْرًۭا","satu beban"]]],"4678":["(Dan demi yang berlayar) yakni kapal-kapal yang berlayar di atas permukaan air (dengan mudah) dengan sangat mudahnya. Kalimat ini adalah Mashdar yang berkedudukan menjadi Hal, yakni Muyassaratan.",[["فَٱلْجَـٰرِيَـٰتِ","Dan mereka yang berlayar"],["يُسْرًۭا","(dengan) mudah"]]],"4679":["(Dan demi yang membagi-bagi urusan) demi malaikat-malaikat yang membagi-bagi rezeki, hujan dan lain-lainnya ke berbagai negeri dan kepada semua hamba-hamba Allah.",[["فَٱلْمُقَسِّمَـٰتِ","Dan mereka yang mengedarkan"],["أَمْرًا","Perintah"]]],"4680":["(Sesungguhnya apa yang dijanjikan kepada kalian) huruf Maa pada lafal Innamaa adalah Mashdariyah; yakni janji Allah kepada mereka, yaitu tentang hari berbangkit dan lain-lainnya (pasti benar) artinya sungguh merupakan janji yang benar.",[["إِنَّمَا","Memang apa"],["تُوعَدُونَ","kamu dijanjikan"],["لَصَادِقٌۭ","(adalah) pasti benar"]]],"4681":["(Dan Sesungguhnya pembalasan itu) yakni pembalasan sesudah hisab (pasti terjadi) pasti akan terjadi.",[["وَإِنَّ","Dan sesungguhnya"],["ٱلدِّينَ","Penghakiman"],["لَوَٰقِعٌۭ","(adalah) pasti berlaku"]]],"4682":["(Demi langit yang mempunyai jalan-jalan) lafal Al Hubuk adalah bentuk jamak dari Habiikah, sama halnya dengan lafal Thariiqah yang bentuk jamaknya Thuruq, yakni sejak ia diciptakan mempunyai jalan-jalan, sebagaimana jalan di padang pasir.",[["وَٱلسَّمَآءِ","Demi syurga"],["ذَاتِ","penuh dengan"],["ٱلْحُبُكِ","laluan"]]],"4683":["(Sesungguhnya kalian) hai penduduk Mekah terhadap Nabi saw. dan Alquran (benar-benar dalam keadaan berbeda-beda pendapat) terkadang mengatakannya sebagai penyair, dan terkadang penyihir, dan terkadang peramal, dan terhadap Alquran terkadang mereka mengatakannya sebagai syair; terkadang sebagai sihir dan terkadang dianggap sebagai ramalan.",[["إِنَّكُمْ","Sesungguhnya kamu"],["لَفِى","(ada) pasti dalam"],["قَوْلٍۢ","sebuah ucapan"],["مُّخْتَلِفٍۢ","berbeza"]]],"4684":["(Dipalingkan) dijauhkan (daripadanya) dari Nabi saw. dan Alquran; maksudnya dipalingkan dari beriman kepadanya (orang yang dipalingkan) dari jalan petunjuk, menurut ilmu Allah swt.",[["يُؤْفَكُ","Terpedaya jauh"],["عَنْهُ","daripadanya"],["مَنْ","(adakah dia) siapa"],["أُفِكَ","tertipu"]]],"4685":["(Terkutuklah orang-orang yang banyak berdusta) amat terkutuklah orang-orang yang berdusta, yaitu orang-orang yang mempunyai pendapat yang berbeda-beda.",[["قُتِلَ","Terkutuklah"],["ٱلْخَرَّٰصُونَ","pendusta"]]],"4686":["(Yaitu orang-orang yang terbenam di dalam kebodohannya) di dalam kebodohan yang menutupi akal mereka (lagi lalai) akan perkara akhirat.",[["ٱلَّذِينَ","Orang yang"],["هُمْ","[mereka]"],["فِى","(ada) dalam"],["غَمْرَةٍۢ","banjir"],["سَاهُونَ","(dari) kelalaian"]]],"4687":["(Mereka bertanya) kepada nabi dengan nada memperolok-olokkan, (\"Bilakah hari pembalasan?\") kapan datangnya hari pembalasan itu. Jawaban yang patut buat mereka ialah, \"Memang Kiamat pasti datang,",[["يَسْـَٔلُونَ","Mereka bertanya"],["أَيَّانَ","Apabila"],["يَوْمُ","(ialah) Hari"],["ٱلدِّينِ","(dari) Penghakiman"]]],"4688":["(Yaitu pada hari ketika mereka di azab di dalam neraka\") yakni sewaktu mereka diazab di dalamnya, lalu dikatakan kepada mereka ketika mereka sedang diazab,",[["يَوْمَ","Sehari"],["هُمْ","mereka"],["عَلَى","atas"],["ٱلنَّارِ","neraka"],["يُفْتَنُونَ","akan dicuba"]]],"4689":["(\"Rasakanlah azab kalian) siksaan kalian. (Inilah) azab (yang dahulu kalian minta supaya disegerakan\") di dunia dengan nada mengejek.",[["ذُوقُوا۟","rasa"],["فِتْنَتَكُمْ","percubaan kamu"],["هَـٰذَا","Ini"],["ٱلَّذِى","(ialah) apa"],["كُنتُم","kamu dahulu"],["بِهِۦ","baginya"],["تَسْتَعْجِلُونَ","berusaha untuk menyegerakan"]]],"4690":["(Sesungguhnya orang-orang yang bertakwa berada di dalam surga) di taman-taman surga (dan di mata air-mata air) yang mengalir di dalam surga.",[["إِنَّ","Sesungguhnya"],["ٱلْمُتَّقِينَ","orang yang soleh"],["فِى","(akan) masuk"],["جَنَّـٰتٍۢ","Taman-taman"],["وَعُيُونٍ","dan mata air"]]],"4691":["(Sambil mengambil) menjadi Hal dari Dhamir yang terkandung di dalam Khabarnya Inna (apa yang didatangkan kepada mereka) apa yang diberikan kepada mereka (oleh Rabb mereka) yaitu berupa pahala-pahala. (Sesungguhnya mereka sebelum itu) sebelum mereka masuk surga (adalah orang-orang yang berbuat baik) di dunia.",[["ءَاخِذِينَ","Mengambil"],["مَآ","apa"],["ءَاتَىٰهُمْ","telah diberikan Tuhan mereka kepada mereka"],["رَبُّهُمْ ۚ","telah diberikan Tuhan mereka kepada mereka"],["إِنَّهُمْ","Sesungguhnya mereka"],["كَانُوا۟","adalah"],["قَبْلَ","sebelum"],["ذَٰلِكَ","bahawa"],["مُحْسِنِينَ","orang yang berbuat baik"]]],"4692":["(Mereka sedikit sekali tidur di waktu malam) lafal Yahja'uuna artinya mereka tidur, dan lafal Maa adalah Zaidah, sedangkan lafal Yahja'uuna adalah Khabar dari Kaana, dan lafal Qaliilan adalah Zharaf. Yakni, mereka tidur di malam hari hanya sedikit, karena kebanyakan dipakai untuk salat.",[["كَانُوا۟","Mereka dulu"],["قَلِيلًۭا","sedikit"],["مِّنَ","daripada"],["ٱلَّيْلِ","malam"],["مَا","[apa]"],["يَهْجَعُونَ","tidur"]]],"4693":["(Dan di akhir-akhir malam mereka memohon ampun) mereka berdoa dengan mengucapkan, \"Allaahumaghfir Lanaa\", Ya Allah ampunilah kami.",[["وَبِٱلْأَسْحَارِ","Dan pada jam sebelum subuh"],["هُمْ","mereka"],["يَسْتَغْفِرُونَ","akan meminta ampun"]]],"4694":["(Dan pada harta-harta mereka ada hak untuk orang miskin yang meminta dan orang miskin yang tidak meminta-minta) karena ia memelihara dirinya dari perbuatan itu.",[["وَفِىٓ","Dan dalam"],["أَمْوَٰلِهِمْ","kekayaan mereka"],["حَقٌّۭ","(adalah) betul"],["لِّلسَّآئِلِ","(dari) orang-orang yang bertanya"],["وَٱلْمَحْرُومِ","dan yang terlantar"]]],"4695":["(Dan di bumi itu) yakni gunung-gunung, tanahnya, lautan, pohon-pohonan, buah-buahan, dan tumbuh-tumbuhannya serta lain-lainnya (terdapat tanda-tanda) yang menunjukkan akan kekuasaan Allah swt. dan keesaan-Nya (bagi orang-orang yang yakin).",[["وَفِى","Dan dalam"],["ٱلْأَرْضِ","bumi"],["ءَايَـٰتٌۭ","(adalah) tanda-tanda"],["لِّلْمُوقِنِينَ","bagi mereka yang pasti"]]],"4696":["(Dan juga pada diri kalian sendiri) terdapat pula tanda-tanda yang menunjukkan kekuasaan dan keesaan-Nya, yaitu mulai dari permulaan penciptaan kalian hingga akhirnya, dan di dalam susunan penciptaan kalian terkandung pula keajaiban-keajaiban. (Maka apakah kalian tidak memperhatikan?) akan hal tersebut yang karena itu lalu kalian dapat menyimpulkan akan Penciptanya dan kekuasaan-Nya yang Maha Besar.",[["وَفِىٓ","Dan dalam"],["أَنفُسِكُمْ ۚ","kamu sendiri"],["أَفَلَا","Kemudian tidak akan"],["تُبْصِرُونَ","kamu lihat"]]],"4697":["(Dan di langit terdapat rezeki kalian) yaitu hujan yang menyebabkan tumbuhnya tumbuh-tumbuhan sebagai rezeki (dan terdapat pula apa yang dijanjikan kepada kalian) yakni tempat kembali, pahala, dan siksaan. Catatan mengenai hal tersebut terdapat di langit.",[["وَفِى","Dan dalam"],["ٱلسَّمَآءِ","syurga itu"],["رِزْقُكُمْ","(adalah) peruntukan kamu"],["وَمَا","dan apa"],["تُوعَدُونَ","kamu dijanjikan"]]],"4698":["(Maka demi Rabb langit dan bumi, sesungguhnya ia) yakni apa yang dijanjikan kepada kalian (adalah benar seperti perkataan yang kalian ucapkan) di-rafa-kannya lafal Mitslu karena menjadi sifat, sedangkan huruf Maa yang sesudahnya adalah Zaidah. Bila dibaca Mitsla maka tulisannya disatukan dengan Maa. Maknanya, kenyataannya seperti perkataan yang kalian ucapkan, yakni pengetahuan mengenai hal itu sudah dimaklumi oleh kalian, dan hal itu justru timbul dari diri kalian sendiri.",[["فَوَرَبِّ","Kemudian demi Tuhan"],["ٱلسَّمَآءِ","(dari) syurga"],["وَٱلْأَرْضِ","dan bumi"],["إِنَّهُۥ","sesungguhnya, ia"],["لَحَقٌّۭ","sesungguhnya (adalah) kebenaran"],["مِّثْلَ","(hanya) sebagai"],["مَآ","[apa]"],["أَنَّكُمْ","kamu"],["تَنطِقُونَ","bercakap"]]],"4699":["(Sudahkah sampai kepadamu) khithab ini ditujukan kepada Nabi saw. (cerita tamu Ibrahim yang dimuliakan) mereka adalah malaikat-malaikat yang jumlahnya ada dua belas atau sepuluh atau tiga malaikat; di antara mereka terdapat malaikat Jibril.",[["هَلْ","Mempunyai"],["أَتَىٰكَ","sampai kepada kamu"],["حَدِيثُ","(the) penceritaan"],["ضَيْفِ","(daripada) tetamu"],["إِبْرَٰهِيمَ","(dari) Ibrahim"],["ٱلْمُكْرَمِينَ","yang dihormati"]]],"4700":["(Ketika) lafal Idz di sini berkedudukan menjadi Zharaf bagi lafal Hadiitsu Dhaifi Ibraahiima (mereka masuk ke tempatnya lalu mengucapkan, \"Salaaman\") tamu-tamu itu mengucapkan perkataan tersebut. (Ibrahim menjawab, \"Salaamun\") menjawab dengan ucapan yang sama (mereka adalah orang-orang yang tidak dikenal) maksudnya, kami tidak mengenal mereka, Nabi Ibrahim mengatakan ucapan ini di dalam hatinya. Kalimat ini berkedudukan menjadi Khabar dari Mubtada yang keberadaannya diperkirakan, yaitu lafal Haa`ulaa`i yang artinya mereka.",[["إِذْ","Apabila"],["دَخَلُوا۟","mereka masuk"],["عَلَيْهِ","atasnya"],["فَقَالُوا۟","dan berkata"],["سَلَـٰمًۭا ۖ","Damai"],["قَالَ","Dia berkata"],["سَلَـٰمٌۭ","Damai"],["قَوْمٌۭ","suatu kaum"],["مُّنكَرُونَ","tidak diketahui"]]],"4701":["(Maka dia pergi) yakni ia beranjak dari situ (menemui keluarganya) dengan diam-diam (kemudian dibawanya daging anak sapi yang gemuk). Di dalam surah Hud telah disebutkan pula melalui firman-Nya, \"... dengan membawa daging anak sapi yang dipanggang.\" (Q.S. Hud, 69) yakni daging anak sapi gemuk itu sudah dipanggang.",[["فَرَاغَ","Kemudian dia pergi"],["إِلَىٰٓ","kepada"],["أَهْلِهِۦ","rumah tangganya"],["فَجَآءَ","dan datang"],["بِعِجْلٍۢ","dengan anak lembu"],["سَمِينٍۢ","gemuk"]]],"4702":["(Lalu dihidangkannya kepada mereka. Ibrahim berkata, \"Silakan kalian makan\") Nabi Ibrahim mempersilakan mereka untuk makan, tetapi mereka tidak mau memakannya.",[["فَقَرَّبَهُۥٓ","Dan dia meletakkannya berhampiran"],["إِلَيْهِمْ","[kepada] mereka"],["قَالَ","dia berkata"],["أَلَا","tidak akan"],["تَأْكُلُونَ","kamu makan"]]],"4703":["(Maka Ibrahim memendam) di dalam hatinya (rasa takut terhadap mereka. Mereka berkata, \"Janganlah kamu takut\") sesungguhnya kami adalah utusan-utusan Rabbmu (dan mereka memberi kabar gembira dengan kelahiran seorang anak yang alim) yakni anak yang mempunyai ilmu banyak yaitu, Nabi Ishak sebagaimana yang telah disebutkan di dalam surah Hud.",[["فَأَوْجَسَ","Kemudian dia merasa"],["مِنْهُمْ","daripada mereka"],["خِيفَةًۭ ۖ","ketakutan"],["قَالُوا۟","Mereka berkata"],["لَا","Jangan"],["تَخَفْ ۖ","bertakwa"],["وَبَشَّرُوهُ","dan mereka memberi khabar gembira kepadanya"],["بِغُلَـٰمٍ","seorang anak lelaki"],["عَلِيمٍۢ","dipelajari"]]],"4704":["(Kemudian istrinya datang) yakni Siti Sarah (seraya memekik) karena tercengang, berkedudukan menjadi Hal; yakni Siti Sarah datang seraya memekik karena kaget (lalu menepuk mukanya sendiri) menampar mukanya sendiri (seraya berkata, \"Aku adalah seorang perempuan tua yang mandul\") yang tidak dapat melahirkan anak sama sekali, pada saat itu umur Sarah mencapai sembilan puluh sembilan tahun, sedangkan Nabi Ibrahim seratus tahun; atau umur Nabi Ibrahim pada saat itu seratus dua puluh tahun, sedangkan umur Siti Sarah sembilan puluh tahun.",[["فَأَقْبَلَتِ","Kemudian datang ke hadapan"],["ٱمْرَأَتُهُۥ","isterinya"],["فِى","dengan"],["صَرَّةٍۢ","suara yang lantang"],["فَصَكَّتْ","dan dipukul"],["وَجْهَهَا","muka dia"],["وَقَالَتْ","dan dia berkata"],["عَجُوزٌ","Seorang wanita tua"],["عَقِيمٌۭ","mandul"]]],"4705":["(Mereka berkata, \"Demikianlah) sebagaimana perkataan kami tentang berita gembira ini (Rabbmu memfirmankan\". Sesungguhnya Dialah Yang Maha Bijaksana) di dalam perbuatan-Nya (lagi Maha Mengetahui) tentang makhluk-Nya.",[["قَالُوا۟","Mereka berkata"],["كَذَٰلِكِ","Demikianlah"],["قَالَ","berkata"],["رَبُّكِ ۖ","Tuhanmu"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","[Dia]"],["ٱلْحَكِيمُ","(ialah) Yang Maha Bijaksana"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]]});